(window.SKILL_FILES = window.SKILL_FILES || {})["continuous-learning-v2"] = [{"path":"agents/observer-loop.sh","text":"#!/usr/bin/env bash\n# Continuous Learning v2 - Observer background loop\n#\n# Fix for #521: Added re-entrancy guard, cooldown throttle, and\n# tail-based sampling to prevent memory explosion from runaway\n# parallel Claude analysis processes.\n\nset +e\nunset CLAUDECODE\n\nSLEEP_PID=\"\"\nUSR1_FIRED=0\nPENDING_ANALYSIS=0\nANALYZING=0\nLAST_ANALYSIS_EPOCH=0\n# Minimum seconds between analyses (prevents rapid re-triggering)\nANALYSIS_COOLDOWN=\"${ECC_OBSERVER_ANALYSIS_COOLDOWN:-60}\"\nIDLE_TIMEOUT_SECONDS=\"${ECC_OBSERVER_IDLE_TIMEOUT_SECONDS:-1800}\"\nSESSION_LEASE_DIR=\"${PROJECT_DIR}/.observer-sessions\"\nACTIVITY_FILE=\"${PROJECT_DIR}/.observer-last-activity\"\n\n# Resolve this script's own directory so sibling scripts (session-guardian.sh)\n# and relative helpers (../scripts/instinct-cli.py) resolve correctly whether\n# this file is executed or sourced. $0 is the *caller* when sourced, so prefer\n# ${BASH_SOURCE[0]}, which always points at this file (#2370).\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\n\ncleanup() {\n  [ -n \"$SLEEP_PID\" ] && kill \"$SLEEP_PID\" 2>/dev/null\n  if [ -f \"$PID_FILE\" ] && [ \"$(cat \"$PID_FILE\" 2>/dev/null)\" = \"$$\" ]; then\n    rm -f \"$PID_FILE\"\n  fi\n  exit 0\n}\ntrap cleanup TERM INT\n\nfile_mtime_epoch() {\n  local file=\"$1\"\n  if [ ! -f \"$file\" ]; then\n    printf '0\\n'\n    return\n  fi\n\n  if stat -c %Y \"$file\" >/dev/null 2>&1; then\n    stat -c %Y \"$file\" 2>/dev/null || printf '0\\n'\n    return\n  fi\n\n  if stat -f %m \"$file\" >/dev/null 2>&1; then\n    stat -f %m \"$file\" 2>/dev/null || printf '0\\n'\n    return\n  fi\n\n  printf '0\\n'\n}\n\nhas_active_session_leases() {\n  if [ ! -d \"$SESSION_LEASE_DIR\" ]; then\n    return 1\n  fi\n\n  find \"$SESSION_LEASE_DIR\" -type f -name '*.json' -print -quit 2>/dev/null | grep -q .\n}\n\nlatest_activity_epoch() {\n  local observations_epoch activity_epoch\n  observations_epoch=\"$(file_mtime_epoch \"$OBSERVATIONS_FILE\")\"\n  activity_epoch=\"$(file_mtime_epoch \"$ACTIVITY_FILE\")\"\n\n  if [ \"$activity_epoch\" -gt \"$observations_epoch\" ] 2>/dev/null; then\n    printf '%s\\n' \"$activity_epoch\"\n  else\n    printf '%s\\n' \"$observations_epoch\"\n  fi\n}\n\nexit_if_idle_without_sessions() {\n  if has_active_session_leases; then\n    return\n  fi\n\n  local last_activity now_epoch idle_for\n  last_activity=\"$(latest_activity_epoch)\"\n  now_epoch=\"$(date +%s)\"\n  idle_for=$(( now_epoch - last_activity ))\n\n  if [ \"$last_activity\" -eq 0 ] || [ \"$idle_for\" -ge \"$IDLE_TIMEOUT_SECONDS\" ]; then\n    echo \"[$(date)] Observer idle without active session leases for ${idle_for}s; exiting\" >> \"$LOG_FILE\"\n    cleanup\n  fi\n}\n\nwait_for_claude_analysis() {\n  local child_pid=\"$1\"\n  local wait_status=0\n\n  while true; do\n    wait \"$child_pid\"\n    wait_status=$?\n\n    if [ \"$wait_status\" -eq 0 ]; then\n      return 0\n    fi\n\n    # SIGUSR1 can interrupt wait while the Claude child is still running.\n    # Re-wait in that case so a signal is not logged as a false child failure.\n    if kill -0 \"$child_pid\" 2>/dev/null; then\n      continue\n    fi\n\n    return \"$wait_status\"\n  done\n}\n\nanalyze_observations() {\n  if [ ! -f \"$OBSERVATIONS_FILE\" ]; then\n    return\n  fi\n\n  obs_count=$(wc -l < \"$OBSERVATIONS_FILE\" 2>/dev/null || echo 0)\n  if [ \"$obs_count\" -lt \"$MIN_OBSERVATIONS\" ]; then\n    return\n  fi\n\n  echo \"[$(date)] Analyzing $obs_count observations for project ${PROJECT_NAME}...\" >> \"$LOG_FILE\"\n\n  if [ \"${CLV2_IS_WINDOWS:-false}\" = \"true\" ] && [ \"${ECC_OBSERVER_ALLOW_WINDOWS:-false}\" != \"true\" ]; then\n    echo \"[$(date)] Skipping claude analysis on Windows due to known non-interactive hang issue (#295). Set ECC_OBSERVER_ALLOW_WINDOWS=true to override.\" >> \"$LOG_FILE\"\n    return\n  fi\n\n  if ! command -v claude >/dev/null 2>&1; then\n    echo \"[$(date)] claude CLI not found, skipping analysis\" >> \"$LOG_FILE\"\n    return\n  fi\n\n  # session-guardian: gate observer cycle (active hours, cooldown, idle detection)\n  if ! bash \"${SCRIPT_DIR}/session-guardian.sh\"; then\n    echo \"[$(date)] Observer cycle skipped by session-guardian\" >> \"$LOG_FILE\"\n    return\n  fi\n\n  # Sample recent observations instead of loading the entire file (#521).\n  # This prevents multi-MB payloads from being passed to the LLM.\n  MAX_ANALYSIS_LINES=\"${ECC_OBSERVER_MAX_ANALYSIS_LINES:-500}\"\n  observer_tmp_dir=\"${PROJECT_DIR}/.observer-tmp\"\n  mkdir -p \"$observer_tmp_dir\"\n  # Keep the XXXXXX run at the very end of the template: BSD/macOS mktemp only\n  # substitutes a trailing X run, so a suffix after it (e.g. `.jsonl`) produces a\n  # literal, non-random name that wedges every later cycle with \"File exists\" (#2417).\n  analysis_file=\"$(mktemp \"${observer_tmp_dir}/ecc-observer-analysis.jsonl.XXXXXX\")\"\n  tail -n \"$MAX_ANALYSIS_LINES\" \"$OBSERVATIONS_FILE\" > \"$analysis_file\"\n  analysis_count=$(wc -l < \"$analysis_file\" 2>/dev/null || echo 0)\n  echo \"[$(date)] Using last $analysis_count of $obs_count observations for analysis\" >> \"$LOG_FILE\"\n\n  # Use relative path from PROJECT_DIR for cross-platform compatibility (#842).\n  # On Windows (Git Bash/MSYS2), absolute paths from mktemp may use MSYS-style\n  # prefixes (e.g. /c/Users/...) that the Claude subprocess cannot resolve.\n  analysis_relpath=\".observer-tmp/$(basename \"$analysis_file\")\"\n\n  prompt_file=\"$(mktemp \"${observer_tmp_dir}/ecc-observer-prompt.XXXXXX\")\"\n  cat > \"$prompt_file\" <<PROMPT\nIMPORTANT: You are running in non-interactive --print mode. You MUST use the Write tool directly to create files. Do NOT ask for permission, do NOT ask for confirmation, do NOT output summaries instead of writing. Just read, analyze, and write.\n\nRead ${analysis_relpath} and identify patterns for the project ${PROJECT_NAME} (user corrections, error resolutions, repeated workflows, tool preferences).\nIf you find 3+ occurrences of the same pattern, you MUST write an instinct file directly to ${INSTINCTS_DIR}/<id>.md using the Write tool.\nDo NOT ask for permission to write files, do NOT describe what you would write, and do NOT stop at analysis when a qualifying pattern exists.\n\nCRITICAL: Every instinct file MUST use this exact format:\n\n---\nid: kebab-case-name\ntrigger: when <specific condition>\nconfidence: <0.3-0.85 based on frequency: 3-5 times=0.5, 6-10=0.7, 11+=0.85>\ndomain: <one of: code-style, testing, git, debugging, workflow, file-patterns>\nsource: session-observation\nscope: project\nproject_id: ${PROJECT_ID}\nproject_name: ${PROJECT_NAME}\n---\n\n# Title\n\n## Action\n<what to do, one clear sentence>\n\n## Evidence\n- Observed N times in session <id>\n- Pattern: <description>\n- Last observed: <date>\n\nRules:\n- Be conservative, only clear patterns with 3+ observations\n- Use narrow, specific triggers\n- Never include actual code snippets, only describe patterns\n- When a qualifying pattern exists, write or update the instinct file in this run instead of asking for confirmation\n- If a similar instinct already exists in ${INSTINCTS_DIR}/, update it instead of creating a duplicate\n- The YAML frontmatter (between --- markers) with id field is MANDATORY\n- If a pattern seems universal (not project-specific), set scope to global instead of project\n- Examples of global patterns: always validate user input, prefer explicit error handling\n- Examples of project patterns: use React functional components, follow Django REST framework conventions\nPROMPT\n\n  # Read the prompt into memory before the Claude subprocess is spawned.\n  # On Windows/MSYS2, the mktemp path can differ from the shell's later path\n  # resolution, so relying on cat \"$prompt_file\" inside the claude invocation\n  # can fail even though the file was created successfully.\n  prompt_content=\"$(cat \"$prompt_file\" 2>/dev/null || true)\"\n  rm -f \"$prompt_file\"\n  if [ -z \"$prompt_content\" ]; then\n    echo \"[$(date)] Failed to load observer prompt content, skipping analysis\" >> \"$LOG_FILE\"\n    rm -f \"$analysis_file\"\n    return\n  fi\n\n  timeout_seconds=\"${ECC_OBSERVER_TIMEOUT_SECONDS:-120}\"\n  # Auto-scale max_turns proportional to analysis batch size when not explicitly set.\n  # The old hardcoded default of 20 is insufficient for the 500-line MAX_ANALYSIS_LINES\n  # default: Claude hits --max-turns before it can write all discovered instinct files.\n  # Formula: 1 turn per 10 analysis lines, floor 20, cap 100. (#2035)\n  if [ -n \"${ECC_OBSERVER_MAX_TURNS:-}\" ]; then\n    max_turns=\"${ECC_OBSERVER_MAX_TURNS}\"\n  else\n    max_turns=$(( analysis_count / 10 ))\n    if [ \"$max_turns\" -lt 20 ]; then max_turns=20; fi\n    if [ \"$max_turns\" -gt 100 ]; then max_turns=100; fi\n  fi\n  exit_code=0\n\n  # Sanitize max_turns. The auto-scaled path above always yields a valid value >=20,\n  # but an explicit ECC_OBSERVER_MAX_TURNS override may be non-numeric, empty, or too\n  # small, so guard here and fall back to the safe default of 20.\n  case \"$max_turns\" in\n    ''|*[!0-9]*)\n      max_turns=20\n      ;;\n  esac\n\n  if [ \"$max_turns\" -lt 4 ]; then\n    max_turns=20\n  fi\n\n  # Ensure CWD is PROJECT_DIR so the relative analysis_relpath resolves correctly\n  # on all platforms, not just when the observer happens to be launched from the project root.\n  cd \"$PROJECT_DIR\" || { echo \"[$(date)] Failed to cd to PROJECT_DIR ($PROJECT_DIR), skipping analysis\" >> \"$LOG_FILE\"; rm -f \"$analysis_file\"; return; }\n\n  # Prevent observe.sh from recording this automated observer session as observations.\n  # Pass prompt via -p flag instead of stdin redirect for Windows compatibility (#842).\n  # prompt_content is already loaded in-memory so this no longer depends on the\n  # mktemp absolute path continuing to resolve after cwd changes (#1296).\n  # stdin is explicitly closed with </dev/null: on Git Bash/MSYS2 the backgrounded\n  # child otherwise inherits an open stdin, and claude waits on it, warns\n  # \"no stdin data received\", and exits 1 before reading the analysis file (#2452).\n  # Model is configurable via ECC_OBSERVER_MODEL (defaults to haiku for cost efficiency);\n  # e.g. ECC_OBSERVER_MODEL=opus for higher-quality instinct extraction. Heavier models are\n  # slower — consider raising ECC_OBSERVER_TIMEOUT_SECONDS (default 120s) so the watchdog\n  # doesn't kill the analysis mid-run.\n  ECC_SKIP_OBSERVE=1 ECC_HOOK_PROFILE=minimal claude --model \"${ECC_OBSERVER_MODEL:-haiku}\" --max-turns \"$max_turns\" --print \\\n    --allowedTools \"Read,Write\" \\\n    -p \"$prompt_content\" < /dev/null >> \"$LOG_FILE\" 2>&1 &\n  claude_pid=$!\n\n  (\n    sleep \"$timeout_seconds\"\n    if kill -0 \"$claude_pid\" 2>/dev/null; then\n      echo \"[$(date)] Claude analysis timed out after ${timeout_seconds}s; terminating process\" >> \"$LOG_FILE\"\n      kill \"$claude_pid\" 2>/dev/null || true\n    fi\n  ) &\n  watchdog_pid=$!\n\n  wait_for_claude_analysis \"$claude_pid\"\n  exit_code=$?\n  kill \"$watchdog_pid\" 2>/dev/null || true\n  rm -f \"$analysis_file\"\n\n  if [ \"$exit_code\" -ne 0 ]; then\n    echo \"[$(date)] Claude analysis failed (exit $exit_code); retaining observations for retry\" >> \"$LOG_FILE\"\n    return\n  fi\n\n  # Archive observations only after a successful analysis. A transient\n  # failure (timeout, non-zero exit, rate limit) must not discard the batch\n  # before it has been turned into instincts, since the analyzer only ever\n  # reads the live observations file (#2370).\n  if [ -f \"$OBSERVATIONS_FILE\" ]; then\n    archive_dir=\"${PROJECT_DIR}/observations.archive\"\n    mkdir -p \"$archive_dir\"\n    mv \"$OBSERVATIONS_FILE\" \"$archive_dir/processed-$(date +%Y%m%d-%H%M%S)-$$.jsonl\" 2>/dev/null || true\n  fi\n}\n\non_usr1() {\n  [ -n \"$SLEEP_PID\" ] && kill \"$SLEEP_PID\" 2>/dev/null\n  SLEEP_PID=\"\"\n\n  # Re-entrancy guard: defer the nudge so the main loop runs a follow-up\n  # analysis immediately after the current analysis finishes.\n  if [ \"$ANALYZING\" -eq 1 ]; then\n    PENDING_ANALYSIS=1\n    echo \"[$(date)] Analysis already in progress, deferring signal\" >> \"$LOG_FILE\"\n    return\n  fi\n\n  USR1_FIRED=1\n\n  # Cooldown: skip if last analysis was too recent (#521)\n  now_epoch=$(date +%s)\n  elapsed=$(( now_epoch - LAST_ANALYSIS_EPOCH ))\n  if [ \"$elapsed\" -lt \"$ANALYSIS_COOLDOWN\" ]; then\n    echo \"[$(date)] Analysis cooldown active (${elapsed}s < ${ANALYSIS_COOLDOWN}s), skipping\" >> \"$LOG_FILE\"\n    return\n  fi\n\n  ANALYZING=1\n  analyze_observations\n  LAST_ANALYSIS_EPOCH=$(date +%s)\n  ANALYZING=0\n}\ntrap on_usr1 USR1\n\n# When this file is sourced (e.g. by tests/hooks/observer-loop-archive.test.js)\n# rather than executed, stop here so callers can invoke individual functions\n# such as analyze_observations without starting the observer loop. The only\n# production caller (start-observer.sh) executes the script, so $0 equals\n# BASH_SOURCE[0] there and this guard is a no-op (#2370).\nif [ \"${BASH_SOURCE[0]}\" != \"${0}\" ]; then\n  return 0 2>/dev/null || true\nfi\n\necho \"$$\" > \"$PID_FILE\"\necho \"[$(date)] Observer started for ${PROJECT_NAME} (PID: $$)\" >> \"$LOG_FILE\"\n\n# Prune expired pending instincts before analysis (SCRIPT_DIR resolved at top\n# via ${BASH_SOURCE[0]} so it is correct under both execution and sourcing).\n\"${CLV2_PYTHON_CMD:-python3}\" \"${SCRIPT_DIR}/../scripts/instinct-cli.py\" prune --quiet >> \"$LOG_FILE\" 2>&1 || echo \"[$(date)] Warning: instinct prune failed (non-fatal)\" >> \"$LOG_FILE\"\n\nwhile true; do\n  exit_if_idle_without_sessions\n\n  if [ \"$PENDING_ANALYSIS\" -eq 1 ]; then\n    PENDING_ANALYSIS=0\n    USR1_FIRED=0\n    ANALYZING=1\n    analyze_observations\n    LAST_ANALYSIS_EPOCH=$(date +%s)\n    ANALYZING=0\n    continue\n  fi\n\n  sleep \"$OBSERVER_INTERVAL_SECONDS\" &\n  SLEEP_PID=$!\n  wait \"$SLEEP_PID\" 2>/dev/null\n  SLEEP_PID=\"\"\n\n  exit_if_idle_without_sessions\n  if [ \"$USR1_FIRED\" -eq 1 ]; then\n    USR1_FIRED=0\n  else\n    ANALYZING=1\n    analyze_observations\n    LAST_ANALYSIS_EPOCH=$(date +%s)\n    ANALYZING=0\n  fi\ndone\n"},{"path":"agents/observer.md","text":"---\nname: observer\ndescription: Background agent that analyzes session observations to detect patterns and create instincts. Uses Haiku for cost-efficiency. v2.1 adds project-scoped instincts.\nmodel: haiku\n---\n\n# Observer Agent\n\nA background agent that analyzes observations from Claude Code sessions to detect patterns and create instincts.\n\n## When to Run\n\n- After enough observations accumulate (configurable, default 20)\n- On a scheduled interval (configurable, default 5 minutes)\n- When triggered on demand via SIGUSR1 to the observer process\n\n## Input\n\nReads observations from the **project-scoped** observations file:\n- Project: `${XDG_DATA_HOME:-~/.local/share}/ecc-homunculus/projects/<project-hash>/observations.jsonl`\n- Global fallback: `${XDG_DATA_HOME:-~/.local/share}/ecc-homunculus/observations.jsonl`\n\n```jsonl\n{\"timestamp\":\"2025-01-22T10:30:00Z\",\"event\":\"tool_start\",\"session\":\"abc123\",\"tool\":\"Edit\",\"input\":\"...\",\"project_id\":\"a1b2c3d4e5f6\",\"project_name\":\"my-react-app\"}\n{\"timestamp\":\"2025-01-22T10:30:01Z\",\"event\":\"tool_complete\",\"session\":\"abc123\",\"tool\":\"Edit\",\"output\":\"...\",\"project_id\":\"a1b2c3d4e5f6\",\"project_name\":\"my-react-app\"}\n{\"timestamp\":\"2025-01-22T10:30:05Z\",\"event\":\"tool_start\",\"session\":\"abc123\",\"tool\":\"Bash\",\"input\":\"npm test\",\"project_id\":\"a1b2c3d4e5f6\",\"project_name\":\"my-react-app\"}\n{\"timestamp\":\"2025-01-22T10:30:10Z\",\"event\":\"tool_complete\",\"session\":\"abc123\",\"tool\":\"Bash\",\"output\":\"All tests pass\",\"project_id\":\"a1b2c3d4e5f6\",\"project_name\":\"my-react-app\"}\n```\n\n## Pattern Detection\n\nLook for these patterns in observations:\n\n### 1. User Corrections\nWhen a user's follow-up message corrects Claude's previous action:\n- \"No, use X instead of Y\"\n- \"Actually, I meant...\"\n- Immediate undo/redo patterns\n\n→ Create instinct: \"When doing X, prefer Y\"\n\n### 2. Error Resolutions\nWhen an error is followed by a fix:\n- Tool output contains error\n- Next few tool calls fix it\n- Same error type resolved similarly multiple times\n\n→ Create instinct: \"When encountering error X, try Y\"\n\n### 3. Repeated Workflows\nWhen the same sequence of tools is used multiple times:\n- Same tool sequence with similar inputs\n- File patterns that change together\n- Time-clustered operations\n\n→ Create workflow instinct: \"When doing X, follow steps Y, Z, W\"\n\n### 4. Tool Preferences\nWhen certain tools are consistently preferred:\n- Always uses Grep before Edit\n- Prefers Read over Bash cat\n- Uses specific Bash commands for certain tasks\n\n→ Create instinct: \"When needing X, use tool Y\"\n\n## Output\n\nCreates/updates instincts in the **project-scoped** instincts directory:\n- Project: `${XDG_DATA_HOME:-~/.local/share}/ecc-homunculus/projects/<project-hash>/instincts/personal/`\n- Global: `${XDG_DATA_HOME:-~/.local/share}/ecc-homunculus/instincts/personal/` (for universal patterns)\n\n### Project-Scoped Instinct (default)\n\n```yaml\n---\nid: use-react-hooks-pattern\ntrigger: \"when creating React components\"\nconfidence: 0.65\ndomain: \"code-style\"\nsource: \"session-observation\"\nscope: project\nproject_id: \"a1b2c3d4e5f6\"\nproject_name: \"my-react-app\"\n---\n\n# Use React Hooks Pattern\n\n## Action\nAlways use functional components with hooks instead of class components.\n\n## Evidence\n- Observed 8 times in session abc123\n- Pattern: All new components use useState/useEffect\n- Last observed: 2025-01-22\n```\n\n### Global Instinct (universal patterns)\n\n```yaml\n---\nid: always-validate-user-input\ntrigger: \"when handling user input\"\nconfidence: 0.75\ndomain: \"security\"\nsource: \"session-observation\"\nscope: global\n---\n\n# Always Validate User Input\n\n## Action\nValidate and sanitize all user input before processing.\n\n## Evidence\n- Observed across 3 different projects\n- Pattern: User consistently adds input validation\n- Last observed: 2025-01-22\n```\n\n## Scope Decision Guide\n\nWhen creating instincts, determine scope based on these heuristics:\n\n> **Scope Decision Guide** – See the canonical table under the \"Scope Decision Guide\" heading in `skills/continuous-learning-v2/SKILL.md`.\n\n**When in doubt, default to `scope: project`** — it's safer to be project-specific and promote later than to contaminate the global space.\n\n## Confidence Calculation\n\nInitial confidence based on observation frequency:\n- 1-2 observations: 0.3 (tentative)\n- 3-5 observations: 0.5 (moderate)\n- 6-10 observations: 0.7 (strong)\n- 11+ observations: 0.85 (very strong)\n\nConfidence adjusts over time:\n- +0.05 for each confirming observation\n- -0.1 for each contradicting observation\n- -0.02 per week without observation (decay)\n\n## Instinct Promotion (Project → Global)\n\nAn instinct should be promoted from project-scoped to global when:\n1. The **same pattern** (by id or similar trigger) exists in **2+ different projects**\n2. Average confidence across instances is **>= 0.8**\n3. The domain is in the global-friendly list (security, general-best-practices, workflow)\n\nPromotion is handled by the `instinct-cli.py promote` command or the `/evolve` analysis.\n\n## Important Guidelines\n\n1. **Be Conservative**: Only create instincts for clear patterns (3+ observations)\n2. **Be Specific**: Narrow triggers are better than broad ones\n3. **Track Evidence**: Always include what observations led to the instinct\n4. **Respect Privacy**: Never include actual code snippets, only patterns\n5. **Merge Similar**: If a new instinct is similar to existing, update rather than duplicate\n6. **Default to Project Scope**: Unless the pattern is clearly universal, make it project-scoped\n7. **Include Project Context**: Always set `project_id` and `project_name` for project-scoped instincts\n\n## Example Analysis Session\n\nGiven observations:\n```jsonl\n{\"event\":\"tool_start\",\"tool\":\"Grep\",\"input\":\"pattern: useState\",\"project_id\":\"a1b2c3\",\"project_name\":\"my-app\"}\n{\"event\":\"tool_complete\",\"tool\":\"Grep\",\"output\":\"Found in 3 files\",\"project_id\":\"a1b2c3\",\"project_name\":\"my-app\"}\n{\"event\":\"tool_start\",\"tool\":\"Read\",\"input\":\"src/hooks/useAuth.ts\",\"project_id\":\"a1b2c3\",\"project_name\":\"my-app\"}\n{\"event\":\"tool_complete\",\"tool\":\"Read\",\"output\":\"[file content]\",\"project_id\":\"a1b2c3\",\"project_name\":\"my-app\"}\n{\"event\":\"tool_start\",\"tool\":\"Edit\",\"input\":\"src/hooks/useAuth.ts...\",\"project_id\":\"a1b2c3\",\"project_name\":\"my-app\"}\n```\n\nAnalysis:\n- Detected workflow: Grep → Read → Edit\n- Frequency: Seen 5 times this session\n- **Scope decision**: This is a general workflow pattern (not project-specific) → **global**\n- Create instinct:\n  - trigger: \"when modifying code\"\n  - action: \"Search with Grep, confirm with Read, then Edit\"\n  - confidence: 0.6\n  - domain: \"workflow\"\n  - scope: \"global\"\n\n## Integration with Skill Creator\n\nWhen instincts are imported from Skill Creator (repo analysis), they have:\n- `source: \"repo-analysis\"`\n- `source_repo: \"https://github.com/...\"`\n- `scope: \"project\"` (since they come from a specific repo)\n\nThese should be treated as team/project conventions with higher initial confidence (0.7+).\n"},{"path":"agents/session-guardian.sh","text":"#!/usr/bin/env bash\n# session-guardian.sh — Observer session guard\n# Exit 0 = proceed. Exit 1 = skip this observer cycle.\n# Called by observer-loop.sh before spawning any Claude session.\n#\n# Config (env vars, all optional):\n#   OBSERVER_INTERVAL_SECONDS    default: 300   (per-project cooldown)\n#   OBSERVER_LAST_RUN_LOG        default: ~/.claude/observer-last-run.log\n#   OBSERVER_ACTIVE_HOURS_START  default: 800   (8:00 AM local, set to 0 to disable)\n#   OBSERVER_ACTIVE_HOURS_END    default: 2300  (11:00 PM local, set to 0 to disable)\n#   OBSERVER_MAX_IDLE_SECONDS    default: 1800  (30 min; set to 0 to disable)\n#\n# Gate execution order (cheapest first):\n#   Gate 1: Time window check    (~0ms, string comparison)\n#   Gate 2: Project cooldown log (~1ms, file read + mkdir lock)\n#   Gate 3: Idle detection       (~5-50ms, OS syscall; fail open)\n\nset -euo pipefail\n\nINTERVAL=\"${OBSERVER_INTERVAL_SECONDS:-300}\"\nLOG_PATH=\"${OBSERVER_LAST_RUN_LOG:-$HOME/.claude/observer-last-run.log}\"\nACTIVE_START=\"${OBSERVER_ACTIVE_HOURS_START:-800}\"\nACTIVE_END=\"${OBSERVER_ACTIVE_HOURS_END:-2300}\"\nMAX_IDLE=\"${OBSERVER_MAX_IDLE_SECONDS:-1800}\"\n\n# ── Gate 1: Time Window ───────────────────────────────────────────────────────\n# Skip observer cycles outside configured active hours (local system time).\n# Uses HHMM integer comparison. Works on BSD date (macOS) and GNU date (Linux).\n# Supports overnight windows such as 2200-0600.\n# Set both ACTIVE_START and ACTIVE_END to 0 to disable this gate.\nif [ \"$ACTIVE_START\" -ne 0 ] || [ \"$ACTIVE_END\" -ne 0 ]; then\n  current_hhmm=$(date +%k%M | tr -d ' ')\n  current_hhmm_num=$(( 10#${current_hhmm:-0} ))\n  active_start_num=$(( 10#${ACTIVE_START:-800} ))\n  active_end_num=$(( 10#${ACTIVE_END:-2300} ))\n\n  within_active_hours=0\n  if [ \"$active_start_num\" -lt \"$active_end_num\" ]; then\n    if [ \"$current_hhmm_num\" -ge \"$active_start_num\" ] && [ \"$current_hhmm_num\" -lt \"$active_end_num\" ]; then\n      within_active_hours=1\n    fi\n  else\n    if [ \"$current_hhmm_num\" -ge \"$active_start_num\" ] || [ \"$current_hhmm_num\" -lt \"$active_end_num\" ]; then\n      within_active_hours=1\n    fi\n  fi\n\n  if [ \"$within_active_hours\" -ne 1 ]; then\n    echo \"session-guardian: outside active hours (${current_hhmm}, window ${ACTIVE_START}-${ACTIVE_END})\" >&2\n    exit 1\n  fi\nfi\n\n# ── Gate 2: Project Cooldown Log ─────────────────────────────────────────────\n# Prevent the same project being observed faster than OBSERVER_INTERVAL_SECONDS.\n# Key: PROJECT_DIR when provided by the observer, otherwise git root path.\n# Uses mkdir-based lock for safe concurrent access. Skips the cycle on lock contention.\n# stderr uses basename only — never prints the full absolute path.\n\nproject_root=\"${PROJECT_DIR:-}\"\nif [ -z \"$project_root\" ] || [ ! -d \"$project_root\" ]; then\n  project_root=\"$(git rev-parse --show-toplevel 2>/dev/null || echo \"$PWD\")\"\nfi\nproject_name=\"$(basename \"$project_root\")\"\nnow=\"$(date +%s)\"\n\nmkdir -p \"$(dirname \"$LOG_PATH\")\" || {\n  echo \"session-guardian: cannot create log dir, proceeding\" >&2\n  exit 0\n}\n\n_lock_dir=\"${LOG_PATH}.lock\"\nif ! mkdir \"$_lock_dir\" 2>/dev/null; then\n  # Another observer holds the lock — skip this cycle to avoid double-spawns\n  echo \"session-guardian: log locked by concurrent process, skipping cycle\" >&2\n  exit 1\nelse\n  trap 'rm -rf \"$_lock_dir\"' EXIT INT TERM\n\n  last_spawn=0\n  last_spawn=$(awk -F '\\t' -v key=\"$project_root\" '$1 == key { value = $2 } END { if (value != \"\") print value }' \"$LOG_PATH\" 2>/dev/null) || true\n  last_spawn=\"${last_spawn:-0}\"\n  [[ \"$last_spawn\" =~ ^[0-9]+$ ]] || last_spawn=0\n\n  elapsed=$(( now - last_spawn ))\n  if [ \"$elapsed\" -lt \"$INTERVAL\" ]; then\n    rm -rf \"$_lock_dir\"\n    trap - EXIT INT TERM\n    echo \"session-guardian: cooldown active for '${project_name}' (last spawn ${elapsed}s ago, interval ${INTERVAL}s)\" >&2\n    exit 1\n  fi\n\n  # Update log: remove old entry for this project, append new timestamp (tab-delimited)\n  tmp_log=\"$(mktemp \"$(dirname \"$LOG_PATH\")/observer-last-run.XXXXXX\")\"\n  awk -F '\\t' -v key=\"$project_root\" '$1 != key' \"$LOG_PATH\" > \"$tmp_log\" 2>/dev/null || true\n  printf '%s\\t%s\\n' \"$project_root\" \"$now\" >> \"$tmp_log\"\n  mv \"$tmp_log\" \"$LOG_PATH\"\n\n  rm -rf \"$_lock_dir\"\n  trap - EXIT INT TERM\nfi\n\n# ── Gate 3: Idle Detection ────────────────────────────────────────────────────\n# Skip cycles when no user input received for too long. Fail open if idle time\n# cannot be determined (Linux without xprintidle, headless, unknown OS).\n# Set OBSERVER_MAX_IDLE_SECONDS=0 to disable this gate.\n\nget_idle_seconds() {\n  local _raw\n  case \"$(uname -s)\" in\n    Darwin)\n      _raw=$( { /usr/sbin/ioreg -c IOHIDSystem \\\n        | /usr/bin/awk '/HIDIdleTime/ {print int($NF/1000000000); exit}'; } \\\n        2>/dev/null ) || true\n      printf '%s\\n' \"${_raw:-0}\" | head -n1\n      ;;\n    Linux)\n      if command -v xprintidle >/dev/null 2>&1; then\n        _raw=$(xprintidle 2>/dev/null) || true\n        echo $(( ${_raw:-0} / 1000 ))\n      else\n        echo 0  # fail open: xprintidle not installed\n      fi\n      ;;\n    *MINGW*|*MSYS*|*CYGWIN*)\n      _raw=$(powershell.exe -NoProfile -NonInteractive -Command \\\n        \"try { \\\n          Add-Type -MemberDefinition '[DllImport(\\\"user32.dll\\\")] public static extern bool GetLastInputInfo(ref LASTINPUTINFO p); [StructLayout(LayoutKind.Sequential)] public struct LASTINPUTINFO { public uint cbSize; public int dwTime; }' -Name WinAPI -Namespace PInvoke; \\\n          \\$l = New-Object PInvoke.WinAPI+LASTINPUTINFO; \\$l.cbSize = 8; \\\n          [PInvoke.WinAPI]::GetLastInputInfo([ref]\\$l) | Out-Null; \\\n          [int][Math]::Max(0, [long]([Environment]::TickCount - [long]\\$l.dwTime) / 1000) \\\n        } catch { 0 }\" \\\n        2>/dev/null | tr -d '\\r') || true\n      printf '%s\\n' \"${_raw:-0}\" | head -n1\n      ;;\n    *)\n      echo 0  # fail open: unknown platform\n      ;;\n  esac\n}\n\nif [ \"$MAX_IDLE\" -gt 0 ]; then\n  idle_seconds=$(get_idle_seconds)\n  if [ \"$idle_seconds\" -gt \"$MAX_IDLE\" ]; then\n    echo \"session-guardian: user idle ${idle_seconds}s (threshold ${MAX_IDLE}s), skipping\" >&2\n    exit 1\n  fi\nfi\n\nexit 0\n"},{"path":"agents/start-observer.sh","text":"#!/usr/bin/env bash\n# Continuous Learning v2 - Observer Agent Launcher\n#\n# Starts the background observer agent that analyzes observations\n# and creates instincts. Uses Haiku model for cost efficiency.\n#\n# v2.1: Project-scoped — detects current project and analyzes\n#       project-specific observations into project-scoped instincts.\n#\n# Usage:\n#   start-observer.sh              # Start observer for current project (or global)\n#   start-observer.sh --reset      # Clear lock and restart observer for current project\n#   start-observer.sh stop         # Stop running observer\n#   start-observer.sh status       # Check if observer is running\n\nset -e\n\n# NOTE: set -e is disabled inside the background subshell below\n# to prevent claude CLI failures from killing the observer loop.\n\n# ─────────────────────────────────────────────\n# Project detection\n# ─────────────────────────────────────────────\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"$0\")\" && pwd)\"\nSKILL_ROOT=\"$(cd \"$SCRIPT_DIR/..\" && pwd)\"\nOBSERVER_LOOP_SCRIPT=\"${SCRIPT_DIR}/observer-loop.sh\"\n\n# Source shared project detection helper\n# This sets: PROJECT_ID, PROJECT_NAME, PROJECT_ROOT, PROJECT_DIR\nsource \"${SKILL_ROOT}/scripts/detect-project.sh\"\nPYTHON_CMD=\"${CLV2_PYTHON_CMD:-}\"\n\n# ─────────────────────────────────────────────\n# Configuration\n# ─────────────────────────────────────────────\n\n# shellcheck disable=SC1091\n. \"${SKILL_ROOT}/scripts/lib/homunculus-dir.sh\"\nCONFIG_DIR=\"$(_clv2_resolve_homunculus_dir)\"\nif [ -n \"${CLV2_CONFIG:-}\" ]; then\n  CONFIG_FILE=\"$CLV2_CONFIG\"\nelif [ -f \"${CONFIG_DIR}/config.json\" ]; then\n  CONFIG_FILE=\"${CONFIG_DIR}/config.json\"\nelse\n  CONFIG_FILE=\"${SKILL_ROOT}/config.json\"\nfi\n# PID file is project-scoped so each project can have its own observer\nPID_FILE=\"${PROJECT_DIR}/.observer.pid\"\nLOG_FILE=\"${PROJECT_DIR}/observer.log\"\nOBSERVATIONS_FILE=\"${PROJECT_DIR}/observations.jsonl\"\nINSTINCTS_DIR=\"${PROJECT_DIR}/instincts/personal\"\nSENTINEL_FILE=\"${CLV2_OBSERVER_SENTINEL_FILE:-${PROJECT_ROOT:-$PROJECT_DIR}/.observer.lock}\"\n\nwrite_guard_sentinel() {\n  printf '%s\\n' 'observer paused: confirmation or permission prompt detected; rerun start-observer.sh --reset after reviewing observer.log' > \"$SENTINEL_FILE\"\n}\n\nstop_observer_if_running() {\n  if [ -f \"$PID_FILE\" ]; then\n    pid=$(cat \"$PID_FILE\")\n    if kill -0 \"$pid\" 2>/dev/null; then\n      echo \"Stopping observer for ${PROJECT_NAME} (PID: $pid)...\"\n      kill \"$pid\"\n      rm -f \"$PID_FILE\"\n      echo \"Observer stopped.\"\n      return 0\n    fi\n\n    echo \"Observer not running (stale PID file).\"\n    rm -f \"$PID_FILE\"\n    return 1\n  fi\n\n  echo \"Observer not running.\"\n  return 1\n}\n\n# Read config values from config.json\nOBSERVER_INTERVAL_MINUTES=5\nMIN_OBSERVATIONS=20\nOBSERVER_ENABLED=false\nif [ -f \"$CONFIG_FILE\" ]; then\n  if [ -z \"$PYTHON_CMD\" ]; then\n    echo \"No python interpreter found; using built-in observer defaults.\" >&2\n  else\n    _config=$(CLV2_CONFIG=\"$CONFIG_FILE\" \"$PYTHON_CMD\" -c \"\nimport json, os\nwith open(os.environ['CLV2_CONFIG']) as f:\n    cfg = json.load(f)\nobs = cfg.get('observer', {})\nprint(obs.get('run_interval_minutes', 5))\nprint(obs.get('min_observations_to_analyze', 20))\nprint(str(obs.get('enabled', False)).lower())\n\" 2>/dev/null || echo \"5\n20\nfalse\")\n    _interval=$(echo \"$_config\" | sed -n '1p')\n    _min_obs=$(echo \"$_config\" | sed -n '2p')\n    _enabled=$(echo \"$_config\" | sed -n '3p')\n    if [ \"$_interval\" -gt 0 ] 2>/dev/null; then\n      OBSERVER_INTERVAL_MINUTES=\"$_interval\"\n    fi\n    if [ \"$_min_obs\" -gt 0 ] 2>/dev/null; then\n      MIN_OBSERVATIONS=\"$_min_obs\"\n    fi\n    if [ \"$_enabled\" = \"true\" ]; then\n      OBSERVER_ENABLED=true\n    fi\n  fi\nfi\nOBSERVER_INTERVAL_SECONDS=$((OBSERVER_INTERVAL_MINUTES * 60))\n\necho \"Project: ${PROJECT_NAME} (${PROJECT_ID})\"\necho \"Storage: ${PROJECT_DIR}\"\n\n# Windows/Git-Bash detection (Issue #295)\nUNAME_LOWER=\"$(uname -s 2>/dev/null | tr '[:upper:]' '[:lower:]')\"\nIS_WINDOWS=false\ncase \"$UNAME_LOWER\" in\n  *mingw*|*msys*|*cygwin*) IS_WINDOWS=true ;;\nesac\n\nACTION=\"start\"\nRESET_OBSERVER=false\n\nfor arg in \"$@\"; do\n  case \"$arg\" in\n    start|stop|status)\n      ACTION=\"$arg\"\n      ;;\n    --reset)\n      RESET_OBSERVER=true\n      ;;\n    *)\n      echo \"Usage: $0 [start|stop|status] [--reset]\"\n      exit 1\n      ;;\n  esac\ndone\n\nif [ \"$RESET_OBSERVER\" = \"true\" ]; then\n  rm -f \"$SENTINEL_FILE\"\nfi\n\ncase \"$ACTION\" in\n  stop)\n    stop_observer_if_running || true\n    exit 0\n    ;;\n\n  status)\n    if [ -f \"$PID_FILE\" ]; then\n      pid=$(cat \"$PID_FILE\")\n      if kill -0 \"$pid\" 2>/dev/null; then\n        echo \"Observer is running (PID: $pid)\"\n        echo \"Log: $LOG_FILE\"\n        echo \"Observations: $(wc -l < \"$OBSERVATIONS_FILE\" 2>/dev/null || echo 0) lines\"\n        # Also show instinct count\n        instinct_count=$(find \"$INSTINCTS_DIR\" -name \"*.yaml\" 2>/dev/null | wc -l)\n        echo \"Instincts: $instinct_count\"\n        exit 0\n      else\n        echo \"Observer not running (stale PID file)\"\n        rm -f \"$PID_FILE\"\n        exit 1\n      fi\n    else\n      echo \"Observer not running\"\n      exit 1\n    fi\n    ;;\n\n  start)\n    # Check if observer is disabled in config\n    if [ \"$OBSERVER_ENABLED\" != \"true\" ]; then\n      echo \"Observer is disabled in config.json (observer.enabled: false).\"\n      echo \"Set observer.enabled to true in config.json to enable.\"\n      exit 1\n    fi\n\n    # Check if already running\n    if [ -f \"$PID_FILE\" ]; then\n      pid=$(cat \"$PID_FILE\")\n      if kill -0 \"$pid\" 2>/dev/null; then\n        echo \"Observer already running for ${PROJECT_NAME} (PID: $pid)\"\n        exit 0\n      fi\n      rm -f \"$PID_FILE\"\n    fi\n\n    echo \"Starting observer agent for ${PROJECT_NAME}...\"\n\n    if [ ! -x \"$OBSERVER_LOOP_SCRIPT\" ]; then\n      echo \"Observer loop script not found or not executable: $OBSERVER_LOOP_SCRIPT\"\n      exit 1\n    fi\n\n    mkdir -p \"$PROJECT_DIR\"\n    touch \"$LOG_FILE\"\n    start_line=$(wc -l < \"$LOG_FILE\" 2>/dev/null || echo 0)\n\n    nohup env \\\n      CONFIG_DIR=\"$CONFIG_DIR\" \\\n      PID_FILE=\"$PID_FILE\" \\\n      LOG_FILE=\"$LOG_FILE\" \\\n      OBSERVATIONS_FILE=\"$OBSERVATIONS_FILE\" \\\n      INSTINCTS_DIR=\"$INSTINCTS_DIR\" \\\n      PROJECT_DIR=\"$PROJECT_DIR\" \\\n      PROJECT_NAME=\"$PROJECT_NAME\" \\\n      PROJECT_ID=\"$PROJECT_ID\" \\\n      MIN_OBSERVATIONS=\"$MIN_OBSERVATIONS\" \\\n      OBSERVER_INTERVAL_SECONDS=\"$OBSERVER_INTERVAL_SECONDS\" \\\n      CLV2_IS_WINDOWS=\"$IS_WINDOWS\" \\\n      CLV2_OBSERVER_PROMPT_PATTERN=\"$CLV2_OBSERVER_PROMPT_PATTERN\" \\\n      \"$OBSERVER_LOOP_SCRIPT\" >> \"$LOG_FILE\" 2>&1 &\n\n    # Wait for PID file (poll up to 10s, exits early when it appears).\n    # Trade-off vs the old `sleep 2`: healthy startups return in iteration 1\n    # (no fixed latency), but a loop that crashes before writing the PID file\n    # is now detected in ~10s instead of ~2s. The longer ceiling is needed to\n    # tolerate slow filesystems where 2s under-waited and false-negatived.\n    for _i in $(seq 1 50); do [ -f \"$PID_FILE\" ] && break; sleep 0.2; done\n\n    # Check for confirmation-seeking output in the observer log\n    if tail -n +\"$((start_line + 1))\" \"$LOG_FILE\" 2>/dev/null | grep -E -i -q \"$CLV2_OBSERVER_PROMPT_PATTERN\"; then\n      echo \"OBSERVER_ABORT: Confirmation or permission prompt detected in observer output. Failing closed.\"\n      stop_observer_if_running >/dev/null 2>&1 || true\n      write_guard_sentinel\n      exit 2\n    fi\n\n    if [ -f \"$PID_FILE\" ]; then\n      pid=$(cat \"$PID_FILE\")\n      if kill -0 \"$pid\" 2>/dev/null; then\n        echo \"Observer started (PID: $pid)\"\n        echo \"Log: $LOG_FILE\"\n      else\n        echo \"Failed to start observer (process died immediately, check $LOG_FILE)\"\n        exit 1\n      fi\n    else\n      echo \"Failed to start observer\"\n      exit 1\n    fi\n    ;;\n\n  *)\n    echo \"Usage: $0 [start|stop|status] [--reset]\"\n    exit 1\n    ;;\nesac\n"},{"path":"config.json","text":"{\n  \"version\": \"2.1\",\n  \"observer\": {\n    \"enabled\": false,\n    \"run_interval_minutes\": 5,\n    \"min_observations_to_analyze\": 20\n  }\n}\n"},{"path":"hooks/observe.sh","text":"#!/usr/bin/env bash\n# Continuous Learning v2 - Observation Hook\n#\n# Captures tool use events for pattern analysis.\n# Claude Code passes hook data via stdin as JSON.\n#\n# v2.1: Project-scoped observations — detects current project context\n#       and writes observations to project-specific directory.\n#\n# Registered via plugin hooks/hooks.json (auto-loaded when plugin is enabled).\n# Can also be registered manually in ~/.claude/settings.json.\n\nset -e\n\n# Hook phase from CLI argument: \"pre\" (PreToolUse) or \"post\" (PostToolUse).\n# Manual settings.json installs can call this script without the plugin\n# wrapper's positional phase argument, but Claude Code still exposes the hook\n# event name in CLAUDE_HOOK_EVENT_NAME.  Fall back to that env var before\n# defaulting to post so manually registered PreToolUse hooks are recorded as\n# tool_start instead of being silently misclassified as tool_complete.\nHOOK_PHASE=\"${1:-}\"\nif [ -z \"$HOOK_PHASE\" ]; then\n  case \"${CLAUDE_HOOK_EVENT_NAME:-}\" in\n    PreToolUse|pretooluse|pre_tool_use|pre) HOOK_PHASE=\"pre\" ;;\n    PostToolUse|posttooluse|post_tool_use|post) HOOK_PHASE=\"post\" ;;\n    *) HOOK_PHASE=\"post\" ;;\n  esac\nfi\n\n# ─────────────────────────────────────────────\n# Read stdin first (before project detection)\n# ─────────────────────────────────────────────\n\n# Read JSON from stdin (Claude Code hook format)\nINPUT_JSON=$(cat)\n\n# Exit if no input\nif [ -z \"$INPUT_JSON\" ]; then\n  exit 0\nfi\n\n_is_windows_app_installer_stub() {\n  # Windows 10/11 ships an \"App Execution Alias\" stub at\n  #   %LOCALAPPDATA%\\Microsoft\\WindowsApps\\python.exe\n  #   %LOCALAPPDATA%\\Microsoft\\WindowsApps\\python3.exe\n  # Both are symlinks to AppInstallerPythonRedirector.exe which, when Python\n  # is not installed from the Store, neither launches Python nor honors \"-c\".\n  # Calls to it hang or print a bare \"Python \" line, silently breaking every\n  # JSON-parsing step in this hook. Detect and skip such stubs here.\n  local _candidate=\"$1\"\n  [ -z \"$_candidate\" ] && return 1\n  local _resolved\n  _resolved=\"$(command -v \"$_candidate\" 2>/dev/null || true)\"\n  [ -z \"$_resolved\" ] && return 1\n  case \"$_resolved\" in\n    *AppInstallerPythonRedirector.exe|*AppInstallerPythonRedirector.EXE) return 0 ;;\n  esac\n  # Also resolve one level of symlink on POSIX-like shells (Git Bash, WSL).\n  if command -v readlink >/dev/null 2>&1; then\n    local _target\n    _target=\"$(readlink -f \"$_resolved\" 2>/dev/null || readlink \"$_resolved\" 2>/dev/null || true)\"\n    case \"$_target\" in\n      *AppInstallerPythonRedirector.exe|*AppInstallerPythonRedirector.EXE) return 0 ;;\n    esac\n  fi\n  return 1\n}\n\nresolve_python_cmd() {\n  if [ -n \"${CLV2_PYTHON_CMD:-}\" ] && command -v \"$CLV2_PYTHON_CMD\" >/dev/null 2>&1; then\n    printf '%s\\n' \"$CLV2_PYTHON_CMD\"\n    return 0\n  fi\n\n  if command -v python3 >/dev/null 2>&1 && ! _is_windows_app_installer_stub python3; then\n    printf '%s\\n' python3\n    return 0\n  fi\n\n  if command -v python >/dev/null 2>&1 && ! _is_windows_app_installer_stub python; then\n    printf '%s\\n' python\n    return 0\n  fi\n\n  return 1\n}\n\nPYTHON_CMD=\"$(resolve_python_cmd 2>/dev/null || true)\"\nif [ -z \"$PYTHON_CMD\" ]; then\n  echo \"[observe] No python interpreter found, skipping observation\" >&2\n  exit 0\nfi\n\n# Propagate our stub-aware selection so detect-project.sh (which is sourced\n# below) does not re-resolve and silently fall back to the App Installer stub.\n# detect-project.sh honors an already-set CLV2_PYTHON_CMD.\nexport CLV2_PYTHON_CMD=\"${CLV2_PYTHON_CMD:-$PYTHON_CMD}\"\n\n# ─────────────────────────────────────────────\n# Extract cwd from stdin for project detection\n# ─────────────────────────────────────────────\n\n# Extract cwd from the hook JSON to use for project detection.\n# If cwd is a subdirectory inside a git repo, resolve it to the repo root so\n# observations attach to the project instead of a nested path.\nSTDIN_CWD=$(echo \"$INPUT_JSON\" | \"$PYTHON_CMD\" -c '\nimport json, sys\ntry:\n    data = json.load(sys.stdin)\n    cwd = data.get(\"cwd\", \"\")\n    print(cwd)\nexcept(KeyError, TypeError, ValueError):\n    print(\"\")\n' 2>/dev/null || echo \"\")\n\n# If cwd was provided in stdin, use it for project detection\nif [ -n \"$STDIN_CWD\" ] && [ -d \"$STDIN_CWD\" ]; then\n  _GIT_ROOT=$(git -C \"$STDIN_CWD\" rev-parse --show-toplevel 2>/dev/null || true)\n  if [ -n \"$_GIT_ROOT\" ]; then\n    export CLAUDE_PROJECT_DIR=\"$_GIT_ROOT\"\n    unset CLV2_NO_PROJECT\n  else\n    unset CLAUDE_PROJECT_DIR\n    export CLV2_NO_PROJECT=1\n  fi\nfi\n\n# ─────────────────────────────────────────────\n# Lightweight config and automated session guards\n# ─────────────────────────────────────────────\n#\n# IMPORTANT: keep these guards above detect-project.sh.\n# Sourcing detect-project.sh creates project-scoped directories and updates\n# projects.json, so automated sessions must return before that point.\n\n# shellcheck disable=SC1091\n. \"$(dirname \"$0\")/../scripts/lib/homunculus-dir.sh\"\nCONFIG_DIR=\"$(_clv2_resolve_homunculus_dir)\"\n\n# Skip if disabled (check both default and CLV2_CONFIG-derived locations)\nif [ -f \"$CONFIG_DIR/disabled\" ]; then\n  exit 0\nfi\nif [ -n \"${CLV2_CONFIG:-}\" ] && [ -f \"$(dirname \"$CLV2_CONFIG\")/disabled\" ]; then\n  exit 0\nfi\n\n# Prevent observe.sh from firing on non-human sessions to avoid:\n#   - ECC observing its own Haiku observer sessions (self-loop)\n#   - ECC observing other tools' automated sessions\n#   - automated sessions creating project-scoped homunculus metadata\n\n# Layer 1: entrypoint. Only interactive terminal sessions should continue.\n# sdk-ts: Agent SDK sessions can be human-interactive (e.g. via Happy).\n# Non-interactive SDK automation is still filtered by Layers 2-5 below\n# (ECC_HOOK_PROFILE=minimal, ECC_SKIP_OBSERVE=1, agent_id, path exclusions).\ncase \"${CLAUDE_CODE_ENTRYPOINT:-cli}\" in\n  cli|sdk-ts|claude-desktop|claude-vscode) ;;\n  *) exit 0 ;;\nesac\n\n# Layer 2: minimal hook profile suppresses non-essential hooks.\n[ \"${ECC_HOOK_PROFILE:-standard}\" = \"minimal\" ] && exit 0\n\n# Layer 3: cooperative skip env var for automated sessions.\n[ \"${ECC_SKIP_OBSERVE:-0}\" = \"1\" ] && exit 0\n\n# Layer 4: subagent sessions are automated by definition.\n_ECC_AGENT_ID=$(echo \"$INPUT_JSON\" | \"$PYTHON_CMD\" -c \"import json,sys; print(json.load(sys.stdin).get('agent_id',''))\" 2>/dev/null || true)\n[ -n \"$_ECC_AGENT_ID\" ] && exit 0\n\n# Layer 5: known observer-session path exclusions.\n_ECC_SKIP_PATHS=\"${ECC_OBSERVE_SKIP_PATHS:-observer-sessions,.claude-mem}\"\nif [ -n \"$STDIN_CWD\" ]; then\n  IFS=',' read -ra _ECC_SKIP_ARRAY <<< \"$_ECC_SKIP_PATHS\"\n  for _pattern in \"${_ECC_SKIP_ARRAY[@]}\"; do\n    _pattern=\"${_pattern#\"${_pattern%%[![:space:]]*}\"}\"\n    _pattern=\"${_pattern%\"${_pattern##*[![:space:]]}\"}\"\n    [ -z \"$_pattern\" ] && continue\n    case \"$STDIN_CWD\" in *\"$_pattern\"*) exit 0 ;; esac\n  done\nfi\n\n# ─────────────────────────────────────────────\n# Project detection\n# ─────────────────────────────────────────────\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"$0\")\" && pwd)\"\nSKILL_ROOT=\"$(cd \"$SCRIPT_DIR/..\" && pwd)\"\n\n# Source shared project detection helper\n# This sets: PROJECT_ID, PROJECT_NAME, PROJECT_ROOT, PROJECT_DIR\nsource \"${SKILL_ROOT}/scripts/detect-project.sh\"\nPYTHON_CMD=\"${CLV2_PYTHON_CMD:-$PYTHON_CMD}\"\n\n# ─────────────────────────────────────────────\n# Configuration\n# ─────────────────────────────────────────────\n\nOBSERVATIONS_FILE=\"${PROJECT_DIR}/observations.jsonl\"\nMAX_FILE_SIZE_MB=10\n\n# Auto-purge observation files older than 30 days (runs once per session)\nPURGE_MARKER=\"${PROJECT_DIR}/.last-purge\"\nif [ ! -f \"$PURGE_MARKER\" ] || [ \"$(find \"$PURGE_MARKER\" -mtime +1 2>/dev/null)\" ]; then\n  find \"${PROJECT_DIR}\" -name \"observations-*.jsonl\" -mtime +30 -delete 2>/dev/null || true\n  touch \"$PURGE_MARKER\" 2>/dev/null || true\nfi\n\n# Parse using Python via stdin pipe (safe for all JSON payloads)\n# Pass HOOK_PHASE via env var since Claude Code does not include hook type in stdin JSON\nPARSED=$(echo \"$INPUT_JSON\" | HOOK_PHASE=\"$HOOK_PHASE\" \"$PYTHON_CMD\" -c '\nimport json\nimport sys\nimport os\n\ntry:\n    data = json.load(sys.stdin)\n\n    # Determine event type from CLI argument passed via env var.\n    # Claude Code does NOT include a \"hook_type\" field in the stdin JSON,\n    # so we rely on the shell argument (\"pre\" or \"post\") instead.\n    hook_phase = os.environ.get(\"HOOK_PHASE\", \"post\")\n    event = \"tool_start\" if hook_phase == \"pre\" else \"tool_complete\"\n\n    # Extract fields - Claude Code hook format\n    tool_name = data.get(\"tool_name\", data.get(\"tool\", \"unknown\"))\n    tool_input = data.get(\"tool_input\", data.get(\"input\", {}))\n    tool_output = data.get(\"tool_response\")\n    if tool_output is None:\n        tool_output = data.get(\"tool_output\", data.get(\"output\", \"\"))\n    session_id = data.get(\"session_id\", \"unknown\")\n    tool_use_id = data.get(\"tool_use_id\", \"\")\n    cwd = data.get(\"cwd\", \"\")\n\n    # Truncate large inputs/outputs\n    if isinstance(tool_input, dict):\n        tool_input_str = json.dumps(tool_input)[:5000]\n    else:\n        tool_input_str = str(tool_input)[:5000]\n\n    if isinstance(tool_output, dict):\n        tool_response_str = json.dumps(tool_output)[:5000]\n    else:\n        tool_response_str = str(tool_output)[:5000]\n\n    print(json.dumps({\n        \"parsed\": True,\n        \"event\": event,\n        \"tool\": tool_name,\n        \"input\": tool_input_str if event == \"tool_start\" else None,\n        \"output\": tool_response_str if event == \"tool_complete\" else None,\n        \"session\": session_id,\n        \"tool_use_id\": tool_use_id,\n        \"cwd\": cwd\n    }))\nexcept Exception as e:\n    print(json.dumps({\"parsed\": False, \"error\": str(e)}))\n')\n\n# Check if parsing succeeded\nPARSED_OK=$(echo \"$PARSED\" | \"$PYTHON_CMD\" -c \"import json,sys; print(json.load(sys.stdin).get('parsed', False))\" 2>/dev/null || echo \"False\")\n\nif [ \"$PARSED_OK\" != \"True\" ]; then\n  # Fallback: log raw input for debugging (scrub secrets before persisting)\n  timestamp=$(date -u +\"%Y-%m-%dT%H:%M:%SZ\")\n  export TIMESTAMP=\"$timestamp\"\n  echo \"$INPUT_JSON\" | \"$PYTHON_CMD\" -c '\nimport json, sys, os, re\n\n# Linear-time secret matcher. Bounded quantifiers and a fixed set of auth\n# schemes (instead of a generic [A-Za-z]+\\s+ that overlapped the value class)\n# prevent the catastrophic backtracking that pegged python at 100% CPU (#2278).\n_SECRET_RE = re.compile(\n    r\"(?i)(api[_-]?key|token|secret|password|authorization|credentials?|auth)\"\n    r\"\"\"([\"'\"'\"'\\s:=]{1,8})\"\"\"\n    r\"((?:bearer|basic|token|bot)\\s+)?\"\n    r\"([A-Za-z0-9_\\-/.+=]{8,256})\"\n)\n\nimport signal\ndef _clv2_bail(*_):\n    print(\"[observe] SIGALRM timeout: parse-error fallback observation dropped before write (#2300)\", file=sys.stderr)\n    sys.exit(0)\ntry:\n    signal.signal(signal.SIGALRM, _clv2_bail)\n    signal.alarm(8)  # self-terminate before the async hook 10s timeout can orphan us (#2278)\nexcept Exception:\n    pass\n\nraw = sys.stdin.read()[:2000]\nraw = _SECRET_RE.sub(lambda m: m.group(1) + m.group(2) + (m.group(3) or \"\") + \"[REDACTED]\", raw)\nprint(json.dumps({\"timestamp\": os.environ[\"TIMESTAMP\"], \"event\": \"parse_error\", \"raw\": raw}))\n' >> \"$OBSERVATIONS_FILE\"\n  exit 0\nfi\n\n# Archive if file too large (atomic: rename with unique suffix to avoid race)\nif [ -f \"$OBSERVATIONS_FILE\" ]; then\n  file_size_mb=$(du -m \"$OBSERVATIONS_FILE\" 2>/dev/null | cut -f1)\n  if [ \"${file_size_mb:-0}\" -ge \"$MAX_FILE_SIZE_MB\" ]; then\n    archive_dir=\"${PROJECT_DIR}/observations.archive\"\n    mkdir -p \"$archive_dir\"\n    mv \"$OBSERVATIONS_FILE\" \"$archive_dir/observations-$(date +%Y%m%d-%H%M%S)-$$.jsonl\" 2>/dev/null || true\n  fi\nfi\n\n# Build and write observation (now includes project context)\n# Scrub common secret patterns from tool I/O before persisting\ntimestamp=$(date -u +\"%Y-%m-%dT%H:%M:%SZ\")\n\nexport PROJECT_ID_ENV=\"$PROJECT_ID\"\nexport PROJECT_NAME_ENV=\"$PROJECT_NAME\"\nexport TIMESTAMP=\"$timestamp\"\n\necho \"$PARSED\" | \"$PYTHON_CMD\" -c '\nimport json, sys, os, re\nimport signal\n\ndef _clv2_bail(*_):\n    print(\"[observe] SIGALRM timeout: in-flight observation dropped before write (#2300)\", file=sys.stderr)\n    sys.exit(0)\ntry:\n    signal.signal(signal.SIGALRM, _clv2_bail)\n    signal.alarm(8)  # self-terminate before the async hook 10s timeout can orphan us (#2278)\nexcept Exception:\n    pass\n\nparsed = json.load(sys.stdin)\nobservation = {\n    \"timestamp\": os.environ[\"TIMESTAMP\"],\n    \"event\": parsed[\"event\"],\n    \"tool\": parsed[\"tool\"],\n    \"session\": parsed[\"session\"],\n    \"project_id\": os.environ.get(\"PROJECT_ID_ENV\", \"global\"),\n    \"project_name\": os.environ.get(\"PROJECT_NAME_ENV\", \"global\")\n}\n\n# Scrub secrets: match common key=value, key: value, and key\"value patterns\n# Includes optional auth scheme (e.g., \"Bearer\", \"Basic\") before token\n# Linear-time secret matcher. Bounded quantifiers and a fixed set of auth\n# schemes (instead of a generic [A-Za-z]+\\s+ that overlapped the value class)\n# prevent the catastrophic backtracking that pegged python at 100% CPU (#2278).\n_SECRET_RE = re.compile(\n    r\"(?i)(api[_-]?key|token|secret|password|authorization|credentials?|auth)\"\n    r\"\"\"([\"'\"'\"'\\s:=]{1,8})\"\"\"\n    r\"((?:bearer|basic|token|bot)\\s+)?\"\n    r\"([A-Za-z0-9_\\-/.+=]{8,256})\"\n)\n\ndef scrub(val):\n    if val is None:\n        return None\n    return _SECRET_RE.sub(lambda m: m.group(1) + m.group(2) + (m.group(3) or \"\") + \"[REDACTED]\", str(val))\n\nif parsed[\"input\"]:\n    observation[\"input\"] = scrub(parsed[\"input\"])\nif parsed[\"output\"] is not None:\n    observation[\"output\"] = scrub(parsed[\"output\"])\n\nprint(json.dumps(observation))\n' >> \"$OBSERVATIONS_FILE\"\n\n# Lazy-start observer if enabled but not running (first-time setup)\n# Use flock for atomic check-then-act to prevent race conditions\n# Fallback for macOS (no flock): use lockfile or skip\nLAZY_START_LOCK=\"${PROJECT_DIR}/.observer-start.lock\"\n_REMOVE_FILE_IF_PRESENT() {\n  local target=\"$1\"\n  if [ -n \"$target\" ] && [ -e \"$target\" ]; then\n    rm -- \"$target\" 2>/dev/null || true\n  fi\n}\n\n_START_OBSERVER_LOGGED() {\n  local bootstrap_log=\"${PROJECT_DIR}/observer-start.log\"\n  mkdir -p \"$PROJECT_DIR\"\n  \"${SKILL_ROOT}/agents/start-observer.sh\" start >> \"$bootstrap_log\" 2>&1 || true\n}\n\n_CHECK_OBSERVER_RUNNING() {\n  local pid_file=\"$1\"\n  if [ -f \"$pid_file\" ]; then\n    local pid\n    pid=$(cat \"$pid_file\" 2>/dev/null)\n    # Validate PID is a positive integer (>1) to prevent signaling invalid targets\n    case \"$pid\" in\n      ''|*[!0-9]*|0|1)\n        _REMOVE_FILE_IF_PRESENT \"$pid_file\"\n        return 1\n        ;;\n    esac\n    if kill -0 \"$pid\" 2>/dev/null; then\n      return 0  # Process is alive\n    fi\n    # Stale PID file - remove it\n    _REMOVE_FILE_IF_PRESENT \"$pid_file\"\n  fi\n  return 1  # No PID file or process dead\n}\n\nif [ -f \"${CONFIG_DIR}/disabled\" ]; then\n  OBSERVER_ENABLED=false\nelse\n  OBSERVER_ENABLED=false\n  if [ -n \"${CLV2_CONFIG:-}\" ]; then\n    CONFIG_FILE=\"$CLV2_CONFIG\"\n  elif [ -f \"${CONFIG_DIR}/config.json\" ]; then\n    CONFIG_FILE=\"${CONFIG_DIR}/config.json\"\n  else\n    CONFIG_FILE=\"${SKILL_ROOT}/config.json\"\n  fi\n  # Use effective config path for both existence check and reading\n  EFFECTIVE_CONFIG=\"$CONFIG_FILE\"\n  if [ -f \"$EFFECTIVE_CONFIG\" ] && [ -n \"$PYTHON_CMD\" ]; then\n    _enabled=$(CLV2_CONFIG_PATH=\"$EFFECTIVE_CONFIG\" \"$PYTHON_CMD\" -c \"\nimport json, os\nwith open(os.environ['CLV2_CONFIG_PATH']) as f:\n    cfg = json.load(f)\nprint(str(cfg.get('observer', {}).get('enabled', False)).lower())\n\" 2>/dev/null || echo \"false\")\n    if [ \"$_enabled\" = \"true\" ]; then\n      OBSERVER_ENABLED=true\n    fi\n  fi\nfi\n\n# Check both project-scoped AND global PID files (with stale PID recovery)\nif [ \"$OBSERVER_ENABLED\" = \"true\" ]; then\n  # Clean up stale PID files first\n  _CHECK_OBSERVER_RUNNING \"${PROJECT_DIR}/.observer.pid\" || true\n  _CHECK_OBSERVER_RUNNING \"${CONFIG_DIR}/.observer.pid\" || true\n\n  # Check if observer is now running after cleanup\n  if [ ! -f \"${PROJECT_DIR}/.observer.pid\" ] && [ ! -f \"${CONFIG_DIR}/.observer.pid\" ]; then\n    # Use flock if available (Linux), fallback for macOS\n    if command -v flock >/dev/null 2>&1; then\n      (\n        flock -n 9 || exit 0\n        # Double-check PID files after acquiring lock\n        _CHECK_OBSERVER_RUNNING \"${PROJECT_DIR}/.observer.pid\" || true\n        _CHECK_OBSERVER_RUNNING \"${CONFIG_DIR}/.observer.pid\" || true\n        if [ ! -f \"${PROJECT_DIR}/.observer.pid\" ] && [ ! -f \"${CONFIG_DIR}/.observer.pid\" ]; then\n          _START_OBSERVER_LOGGED\n        fi\n      ) 9>\"$LAZY_START_LOCK\"\n    else\n      # macOS fallback: use lockfile if available, otherwise mkdir-based lock\n      if command -v lockfile >/dev/null 2>&1; then\n        # Use subshell to isolate exit and add trap for cleanup\n        (\n          trap '_REMOVE_FILE_IF_PRESENT \"$LAZY_START_LOCK\"' EXIT\n          lockfile -r 1 -l 30 \"$LAZY_START_LOCK\" 2>/dev/null || exit 0\n          _CHECK_OBSERVER_RUNNING \"${PROJECT_DIR}/.observer.pid\" || true\n          _CHECK_OBSERVER_RUNNING \"${CONFIG_DIR}/.observer.pid\" || true\n          if [ ! -f \"${PROJECT_DIR}/.observer.pid\" ] && [ ! -f \"${CONFIG_DIR}/.observer.pid\" ]; then\n            _START_OBSERVER_LOGGED\n          fi\n          _REMOVE_FILE_IF_PRESENT \"$LAZY_START_LOCK\"\n        )\n      else\n        # POSIX fallback: mkdir is atomic -- fails if dir already exists\n        (\n          trap 'rmdir \"${LAZY_START_LOCK}.d\" 2>/dev/null || true' EXIT\n          mkdir \"${LAZY_START_LOCK}.d\" 2>/dev/null || exit 0\n          _CHECK_OBSERVER_RUNNING \"${PROJECT_DIR}/.observer.pid\" || true\n          _CHECK_OBSERVER_RUNNING \"${CONFIG_DIR}/.observer.pid\" || true\n          if [ ! -f \"${PROJECT_DIR}/.observer.pid\" ] && [ ! -f \"${CONFIG_DIR}/.observer.pid\" ]; then\n            _START_OBSERVER_LOGGED\n          fi\n        )\n      fi\n    fi\n  fi\nfi\n\n# Throttle SIGUSR1: only signal observer every N observations (#521)\n# This prevents rapid signaling when tool calls fire every second,\n# which caused runaway parallel Claude analysis processes.\nSIGNAL_EVERY_N=\"${ECC_OBSERVER_SIGNAL_EVERY_N:-20}\"\nSIGNAL_COUNTER_FILE=\"${PROJECT_DIR}/.observer-signal-counter\"\nSIGNAL_COUNTER_LOCK=\"${SIGNAL_COUNTER_FILE}.lock\"\nACTIVITY_FILE=\"${PROJECT_DIR}/.observer-last-activity\"\n\ntouch \"$ACTIVITY_FILE\" 2>/dev/null || true\n\n# Serialize the throttle-counter read-modify-write. observe.sh runs on every\n# tool call (which can fire every second), so concurrent invocations previously\n# raced on this counter: both read the same value, both incremented, and one\n# write was lost, signaling the observer at unpredictable intervals (#2296).\n# Prefer flock (a kernel advisory lock the OS releases automatically if the hook\n# is killed); fall back to the atomic mkdir lock this script already uses for\n# the lazy-start path above. Both wrap the same read-modify-write below.\nshould_signal=0\n\n_clv2_bump_signal_counter() {\n  if [ -f \"$SIGNAL_COUNTER_FILE\" ]; then\n    counter=$(cat \"$SIGNAL_COUNTER_FILE\" 2>/dev/null || echo 0)\n    # Guard against a corrupt counter file: a non-integer value would abort the\n    # hook under `set -e` at the arithmetic below.\n    case \"$counter\" in\n      ''|*[!0-9]*) counter=0 ;;\n    esac\n    counter=$((counter + 1))\n    if [ \"$counter\" -ge \"$SIGNAL_EVERY_N\" ]; then\n      should_signal=1\n      counter=0\n    fi\n    echo \"$counter\" > \"$SIGNAL_COUNTER_FILE\"\n  else\n    echo \"1\" > \"$SIGNAL_COUNTER_FILE\"\n  fi\n}\n\nif command -v flock >/dev/null 2>&1 && exec 8>\"$SIGNAL_COUNTER_LOCK\" 2>/dev/null; then\n  # flock is auto-released when fd 8 closes or the process dies, so there is no\n  # stale lock and no lost increment. Use a bounded -w wait so the hook never\n  # blocks indefinitely, and only bump the counter while the lock is held -- on\n  # a timeout we skip the tick rather than doing an unlocked read-modify-write.\n  if flock -w 2 8 2>/dev/null; then\n    _clv2_bump_signal_counter\n    flock -u 8 2>/dev/null || true\n  fi\n  exec 8>&- 2>/dev/null || true\nelse\n  # No flock (e.g. macOS): atomic mkdir lock with a bounded spin so the hook\n  # never blocks indefinitely. A trap releases the lock on every exit path --\n  # including the async-timeout SIGTERM -- so a killed hook does not strand the\n  # directory. We deliberately do NOT hand-roll PID-based stale reclaim:\n  # re-verifying then removing another process's lock is racy and can delete a\n  # live re-acquirer's directory, reintroducing the very race this fixes.\n  _signal_lock_held=0\n  _signal_lock_spins=0\n  while [ \"$_signal_lock_spins\" -lt 100 ]; do\n    if mkdir \"$SIGNAL_COUNTER_LOCK\" 2>/dev/null; then\n      # EXIT cleans up on normal completion. INT/TERM must release AND exit:\n      # a signal trap that only released the lock would otherwise fall through\n      # and continue the read-modify-write without ownership.\n      trap 'rmdir \"$SIGNAL_COUNTER_LOCK\" 2>/dev/null || true' EXIT\n      trap 'rmdir \"$SIGNAL_COUNTER_LOCK\" 2>/dev/null || true; exit 130' INT\n      trap 'rmdir \"$SIGNAL_COUNTER_LOCK\" 2>/dev/null || true; exit 143' TERM\n      _signal_lock_held=1\n      break\n    fi\n    _signal_lock_spins=$((_signal_lock_spins + 1))\n    sleep 0.02\n  done\n  if [ \"$_signal_lock_held\" -eq 1 ]; then\n    # Bump only under the held lock -- never an unlocked read-modify-write.\n    _clv2_bump_signal_counter\n    rmdir \"$SIGNAL_COUNTER_LOCK\" 2>/dev/null || true\n    trap - EXIT INT TERM\n  fi\n  # If the lock could not be acquired within the spin budget we skip this tick\n  # rather than racing on an unlocked counter. Dropping one throttle tick under\n  # extreme contention only delays the next observer signal slightly; it never\n  # corrupts the counter or signals spuriously.\nfi\n\n# Signal observer if running and throttle allows (check both project-scoped and global observer, deduplicate)\nif [ \"$should_signal\" -eq 1 ]; then\n  signaled_pids=\" \"\n  for pid_file in \"${PROJECT_DIR}/.observer.pid\" \"${CONFIG_DIR}/.observer.pid\"; do\n    if [ -f \"$pid_file\" ]; then\n      observer_pid=$(cat \"$pid_file\" 2>/dev/null || true)\n      # Validate PID is a positive integer (>1)\n      case \"$observer_pid\" in\n        ''|*[!0-9]*|0|1)\n          _REMOVE_FILE_IF_PRESENT \"$pid_file\"\n          continue\n          ;;\n      esac\n      # Deduplicate: skip if already signaled this pass\n      case \"$signaled_pids\" in\n        *\" $observer_pid \"*) continue ;;\n      esac\n      if kill -0 \"$observer_pid\" 2>/dev/null; then\n        kill -USR1 \"$observer_pid\" 2>/dev/null || true\n        signaled_pids=\"${signaled_pids}${observer_pid} \"\n      fi\n    fi\n  done\nfi\n\nexit 0\n"},{"path":"scripts/detect-project.sh","text":"#!/usr/bin/env bash\n# Continuous Learning v2 - Project Detection Helper\n#\n# Shared logic for detecting current project context.\n# Sourced by observe.sh and start-observer.sh.\n#\n# Exports:\n#   _CLV2_PROJECT_ID     - Short hash identifying the project (or \"global\")\n#   _CLV2_PROJECT_NAME   - Human-readable project name\n#   _CLV2_PROJECT_ROOT   - Absolute path to project root\n#   _CLV2_PROJECT_DIR    - Project-scoped storage directory under homunculus\n#\n# Also sets unprefixed convenience aliases:\n#   PROJECT_ID, PROJECT_NAME, PROJECT_ROOT, PROJECT_DIR\n#\n# Detection priority:\n#   1. CLAUDE_PROJECT_DIR env var (if set)\n#   2. git remote URL (hashed for uniqueness across machines)\n#   3. git repo root path (fallback, machine-specific)\n#   4. \"global\" (no project context detected)\n\n# shellcheck disable=SC1091\n. \"$(dirname \"${BASH_SOURCE[0]}\")/lib/homunculus-dir.sh\"\n_CLV2_HOMUNCULUS_DIR=\"$(_clv2_resolve_homunculus_dir)\"\n_CLV2_PROJECTS_DIR=\"${_CLV2_HOMUNCULUS_DIR}/projects\"\n_CLV2_REGISTRY_FILE=\"${_CLV2_HOMUNCULUS_DIR}/projects.json\"\n\n_clv2_resolve_python_cmd() {\n  if [ -n \"${CLV2_PYTHON_CMD:-}\" ] && command -v \"$CLV2_PYTHON_CMD\" >/dev/null 2>&1; then\n    printf '%s\\n' \"$CLV2_PYTHON_CMD\"\n    return 0\n  fi\n\n  if command -v python3 >/dev/null 2>&1; then\n    printf '%s\\n' python3\n    return 0\n  fi\n\n  if command -v python >/dev/null 2>&1; then\n    printf '%s\\n' python\n    return 0\n  fi\n\n  return 1\n}\n\n_CLV2_PYTHON_CMD=\"$(_clv2_resolve_python_cmd 2>/dev/null || true)\"\nCLV2_PYTHON_CMD=\"$_CLV2_PYTHON_CMD\"\nexport CLV2_PYTHON_CMD\n\nCLV2_OBSERVER_PROMPT_PATTERN='Can you confirm|requires permission|Awaiting (user confirmation|confirmation|approval|permission)|confirm I should proceed|once granted access|grant.*access'\nexport CLV2_OBSERVER_PROMPT_PATTERN\n\n_clv2_normalize_remote_url() {\n  local url=\"$1\"\n  [ -z \"$url\" ] && return 0\n\n  local is_network=0\n  case \"$url\" in\n    file://*) is_network=0 ;;\n    *://*) is_network=1 ;;\n    *@*:*) is_network=1 ;;\n    *) is_network=0 ;;\n  esac\n\n  url=$(printf '%s' \"$url\" | sed -E 's|://[^@]+@|://|')\n  url=$(printf '%s' \"$url\" | sed -E 's|^[A-Za-z][A-Za-z0-9+.-]*://||')\n  url=$(printf '%s' \"$url\" | sed -E 's|^[^@/:]+@([^:/]+):|\\1/|')\n  url=$(printf '%s' \"$url\" | sed -E 's|\\.git/?$||; s|/+$||')\n\n  if [ \"$is_network\" = \"1\" ]; then\n    printf '%s' \"$url\" | tr '[:upper:]' '[:lower:]'\n  else\n    printf '%s' \"$url\"\n  fi\n}\n\n_clv2_main_worktree_root() {\n  local root=\"$1\"\n  [ -z \"$root\" ] && return 0\n  command -v git >/dev/null 2>&1 || return 0\n\n  git -C \"$root\" worktree list --porcelain 2>/dev/null | while IFS= read -r line; do\n    case \"$line\" in\n      worktree\\ *)\n        printf '%s\\n' \"${line#worktree }\"\n        break\n        ;;\n    esac\n  done\n}\n\n_clv2_detect_project() {\n  local project_root=\"\"\n  local project_name=\"\"\n  local project_id=\"\"\n  local source_hint=\"\"\n\n  if [ \"${CLV2_NO_PROJECT:-0}\" = \"1\" ]; then\n    _CLV2_PROJECT_ID=\"global\"\n    _CLV2_PROJECT_NAME=\"global\"\n    _CLV2_PROJECT_ROOT=\"\"\n    _CLV2_PROJECT_DIR=\"${_CLV2_HOMUNCULUS_DIR}\"\n    mkdir -p \"$_CLV2_PROJECT_DIR\"\n    return 0\n  fi\n\n  # 1. Try CLAUDE_PROJECT_DIR env var (explicit override)\n  if [ -n \"$CLAUDE_PROJECT_DIR\" ] && [ -d \"$CLAUDE_PROJECT_DIR\" ]; then\n    if command -v git &>/dev/null; then\n      project_root=$(git -C \"$CLAUDE_PROJECT_DIR\" rev-parse --show-toplevel 2>/dev/null || true)\n      if [ -n \"$project_root\" ]; then\n        source_hint=\"env\"\n      fi\n    fi\n    # Non-git directory explicitly pointed at by CLAUDE_PROJECT_DIR: honor it as\n    # a project root (path-hash identity) rather than collapsing to the shared\n    # `global` bucket. Gated on the explicit env var so an arbitrary non-git cwd\n    # never becomes a \"project\" — priority 2 below stays git-only on purpose.\n    if [ -z \"$project_root\" ]; then\n      project_root=$(cd \"$CLAUDE_PROJECT_DIR\" 2>/dev/null && pwd -P)\n      if [ -n \"$project_root\" ]; then\n        source_hint=\"env-nogit\"\n      fi\n    fi\n  fi\n\n  # 2. Try git repo root from CWD (only if git is available)\n  if [ -z \"$project_root\" ] && command -v git &>/dev/null; then\n    project_root=$(git rev-parse --show-toplevel 2>/dev/null || true)\n    if [ -n \"$project_root\" ]; then\n      source_hint=\"git\"\n    fi\n  fi\n\n  # 3. No project detected — fall back to global\n  if [ -z \"$project_root\" ]; then\n    _CLV2_PROJECT_ID=\"global\"\n    _CLV2_PROJECT_NAME=\"global\"\n    _CLV2_PROJECT_ROOT=\"\"\n    _CLV2_PROJECT_DIR=\"${_CLV2_HOMUNCULUS_DIR}\"\n    mkdir -p \"$_CLV2_PROJECT_DIR\"\n    return 0\n  fi\n\n  # Derive project name from directory basename\n  # Normalize Windows backslashes so basename works when CLAUDE_PROJECT_DIR\n  # is passed as e.g. C:\\Users\\...\\project.\n  local _norm_root\n  _norm_root=$(printf '%s' \"$project_root\" | sed 's|\\\\|/|g')\n  project_name=$(basename \"$_norm_root\")\n\n  # Derive project ID: prefer git remote URL hash (portable across machines),\n  # fall back to path hash (machine-specific but still useful)\n  local remote_url=\"\"\n  if command -v git &>/dev/null; then\n    if [ \"$source_hint\" = \"git\" ] || [ -e \"${project_root}/.git\" ]; then\n      remote_url=$(git -C \"$project_root\" remote get-url origin 2>/dev/null || true)\n    fi\n  fi\n\n  local raw_remote_url=\"$remote_url\"\n\n  # Strip embedded credentials from remote URL (e.g., https://ghp_xxxx@github.com/...)\n  if [ -n \"$remote_url\" ]; then\n    remote_url=$(printf '%s' \"$remote_url\" | sed -E 's|://[^@]+@|://|')\n  fi\n\n  local legacy_hash_input=\"${remote_url:-$project_root}\"\n  local normalized_remote=\"\"\n  if [ -n \"$remote_url\" ]; then\n    normalized_remote=$(_clv2_normalize_remote_url \"$remote_url\")\n  fi\n\n  local fallback_root=\"$project_root\"\n  if [ -z \"$remote_url\" ]; then\n    local main_worktree_root\n    main_worktree_root=$(_clv2_main_worktree_root \"$project_root\")\n    [ -n \"$main_worktree_root\" ] && fallback_root=\"$main_worktree_root\"\n  fi\n\n  local hash_input=\"${normalized_remote:-${remote_url:-$fallback_root}}\"\n  # Prefer Python for consistent SHA256 behavior across shells/platforms.\n  # Pass the value via env var and encode as UTF-8 inside Python so the hash\n  # is locale-independent (shells vary between UTF-8 / CP932 / CP1252, which\n  # would otherwise produce different hashes for the same non-ASCII path).\n  if [ -n \"$_CLV2_PYTHON_CMD\" ]; then\n    project_id=$(_CLV2_HASH_INPUT=\"$hash_input\" \"$_CLV2_PYTHON_CMD\" -c '\nimport os, hashlib\ns = os.environ[\"_CLV2_HASH_INPUT\"]\nprint(hashlib.sha256(s.encode(\"utf-8\")).hexdigest()[:12])\n' 2>/dev/null)\n  fi\n\n  # Fallback if Python is unavailable or hash generation failed.\n  if [ -z \"$project_id\" ]; then\n    project_id=$(printf '%s' \"$hash_input\" | shasum -a 256 2>/dev/null | cut -c1-12 || \\\n                 printf '%s' \"$hash_input\" | sha256sum 2>/dev/null | cut -c1-12 || \\\n                 echo \"fallback\")\n  fi\n\n  # Backward compatibility: migrate a single legacy project directory from\n  # credential-stripped or raw remote hashes to the normalized remote hash.\n  if [ -n \"$_CLV2_PYTHON_CMD\" ] && [ ! -d \"${_CLV2_PROJECTS_DIR}/${project_id}\" ]; then\n    local legacy_inputs=()\n    [ -n \"$legacy_hash_input\" ] && [ \"$legacy_hash_input\" != \"$hash_input\" ] \\\n      && legacy_inputs+=(\"$legacy_hash_input\")\n    [ -n \"$raw_remote_url\" ] && [ \"$raw_remote_url\" != \"$hash_input\" ] \\\n      && [ \"$raw_remote_url\" != \"$legacy_hash_input\" ] \\\n      && legacy_inputs+=(\"$raw_remote_url\")\n\n    local legacy_input legacy_id\n    for legacy_input in \"${legacy_inputs[@]}\"; do\n      legacy_id=$(_CLV2_HASH_INPUT=\"$legacy_input\" \"$_CLV2_PYTHON_CMD\" -c '\nimport os, hashlib\ns = os.environ[\"_CLV2_HASH_INPUT\"]\nprint(hashlib.sha256(s.encode(\"utf-8\")).hexdigest()[:12])\n' 2>/dev/null)\n      if [ -n \"$legacy_id\" ] && [ \"$legacy_id\" != \"$project_id\" ] \\\n         && [ -d \"${_CLV2_PROJECTS_DIR}/${legacy_id}\" ]; then\n        if mv \"${_CLV2_PROJECTS_DIR}/${legacy_id}\" \"${_CLV2_PROJECTS_DIR}/${project_id}\" 2>/dev/null; then\n          break\n        else\n          project_id=\"$legacy_id\"\n          break\n        fi\n      fi\n    done\n  fi\n\n  # Export results\n  _CLV2_PROJECT_ID=\"$project_id\"\n  _CLV2_PROJECT_NAME=\"$project_name\"\n  _CLV2_PROJECT_ROOT=\"$project_root\"\n  _CLV2_PROJECT_DIR=\"${_CLV2_PROJECTS_DIR}/${project_id}\"\n\n  # Ensure project directory structure exists\n  mkdir -p \"${_CLV2_PROJECT_DIR}/instincts/personal\"\n  mkdir -p \"${_CLV2_PROJECT_DIR}/instincts/inherited\"\n  mkdir -p \"${_CLV2_PROJECT_DIR}/observations.archive\"\n  mkdir -p \"${_CLV2_PROJECT_DIR}/evolved/skills\"\n  mkdir -p \"${_CLV2_PROJECT_DIR}/evolved/commands\"\n  mkdir -p \"${_CLV2_PROJECT_DIR}/evolved/agents\"\n\n  # Update project registry (lightweight JSON mapping)\n  _clv2_update_project_registry \"$project_id\" \"$project_name\" \"$project_root\" \"$remote_url\"\n}\n\n_clv2_update_project_registry() {\n  local pid=\"$1\"\n  local pname=\"$2\"\n  local proot=\"$3\"\n  local premote=\"$4\"\n  local pdir=\"$_CLV2_PROJECT_DIR\"\n\n  mkdir -p \"$(dirname \"$_CLV2_REGISTRY_FILE\")\"\n\n  if [ -z \"$_CLV2_PYTHON_CMD\" ]; then\n    return 0\n  fi\n\n  # Pass values via env vars to avoid shell→python injection.\n  # Python reads them with os.environ, which is safe for any string content.\n  _CLV2_REG_PID=\"$pid\" \\\n  _CLV2_REG_PNAME=\"$pname\" \\\n  _CLV2_REG_PROOT=\"$proot\" \\\n  _CLV2_REG_PREMOTE=\"$premote\" \\\n  _CLV2_REG_PDIR=\"$pdir\" \\\n  _CLV2_REG_FILE=\"$_CLV2_REGISTRY_FILE\" \\\n  \"$_CLV2_PYTHON_CMD\" -c '\nimport json, os, tempfile\nfrom datetime import datetime, timezone\n\nregistry_path = os.environ[\"_CLV2_REG_FILE\"]\nproject_dir = os.environ[\"_CLV2_REG_PDIR\"]\nproject_file = os.path.join(project_dir, \"project.json\")\n\nos.makedirs(project_dir, exist_ok=True)\n\ndef atomic_write_json(path, payload):\n    fd, tmp_path = tempfile.mkstemp(\n        prefix=f\".{os.path.basename(path)}.tmp.\",\n        dir=os.path.dirname(path),\n        text=True,\n    )\n    try:\n        with os.fdopen(fd, \"w\") as f:\n            json.dump(payload, f, indent=2)\n            f.write(\"\\n\")\n        os.replace(tmp_path, path)\n    finally:\n        if os.path.exists(tmp_path):\n            os.unlink(tmp_path)\n\ntry:\n    with open(registry_path) as f:\n        registry = json.load(f)\nexcept (FileNotFoundError, json.JSONDecodeError):\n    registry = {}\n\nnow = datetime.now(timezone.utc).isoformat().replace(\"+00:00\", \"Z\")\nentry = registry.get(os.environ[\"_CLV2_REG_PID\"], {})\n\nmetadata = {\n    \"id\": os.environ[\"_CLV2_REG_PID\"],\n    \"name\": os.environ[\"_CLV2_REG_PNAME\"],\n    \"root\": os.environ[\"_CLV2_REG_PROOT\"],\n    \"remote\": os.environ[\"_CLV2_REG_PREMOTE\"],\n    \"created_at\": entry.get(\"created_at\", now),\n    \"last_seen\": now,\n}\n\nregistry[os.environ[\"_CLV2_REG_PID\"]] = metadata\n\natomic_write_json(project_file, metadata)\natomic_write_json(registry_path, registry)\n' 2>/dev/null || true\n}\n\n# Auto-detect on source\n_clv2_detect_project\n\n# Convenience aliases for callers (short names pointing to prefixed vars)\nPROJECT_ID=\"$_CLV2_PROJECT_ID\"\nPROJECT_NAME=\"$_CLV2_PROJECT_NAME\"\nPROJECT_ROOT=\"$_CLV2_PROJECT_ROOT\"\nPROJECT_DIR=\"$_CLV2_PROJECT_DIR\"\n\nif [ -n \"$PROJECT_ROOT\" ]; then\n  CLV2_OBSERVER_SENTINEL_FILE=\"${PROJECT_ROOT}/.observer.lock\"\nelse\n  CLV2_OBSERVER_SENTINEL_FILE=\"${PROJECT_DIR}/.observer.lock\"\nfi\nexport CLV2_OBSERVER_SENTINEL_FILE\n"},{"path":"scripts/instinct-cli.py","text":"#!/usr/bin/env python3\n\"\"\"\nInstinct CLI - Manage instincts for Continuous Learning v2\n\nv2.1: Project-scoped instincts — different projects get different instincts,\n      with global instincts applied universally.\n\nCommands:\n  status   - Show all instincts (project + global) and their status\n  import   - Import instincts from file or URL\n  export   - Export instincts to file\n  evolve   - Cluster instincts into skills/commands/agents\n  promote  - Promote project instincts to global scope\n  projects - List all known projects and their instinct counts\n  prune    - Delete pending instincts older than 30 days (TTL)\n\"\"\"\n\nimport argparse\nimport json\nimport hashlib\nimport os\nimport subprocess\nimport sys\nimport re\nimport shutil\nimport ipaddress\nimport socket\nimport urllib.parse\nimport urllib.request\nimport tempfile\nfrom contextlib import contextmanager\nfrom pathlib import Path\nfrom datetime import datetime, timedelta, timezone\nfrom collections import defaultdict\nfrom typing import Optional\n\nif sys.platform == \"win32\":\n    try:\n        sys.stdout.reconfigure(encoding=\"utf-8\")\n        sys.stderr.reconfigure(encoding=\"utf-8\")\n    except Exception:\n        pass\n\ntry:\n    import fcntl\n    _HAS_FCNTL = True\nexcept ImportError:\n    _HAS_FCNTL = False  # Windows — skip file locking\n\n# ─────────────────────────────────────────────\n# Configuration\n# ─────────────────────────────────────────────\n\ndef _resolve_homunculus_dir() -> Path:\n    override = os.environ.get(\"CLV2_HOMUNCULUS_DIR\")\n    if override:\n        if Path(override).is_absolute():\n            return Path(override)\n        print(f\"[ecc] CLV2_HOMUNCULUS_DIR={override!r} is not absolute; ignoring\", file=sys.stderr)\n\n    xdg = os.environ.get(\"XDG_DATA_HOME\")\n    if xdg:\n        if Path(xdg).is_absolute():\n            return Path(xdg) / \"ecc-homunculus\"\n        print(f\"[ecc] XDG_DATA_HOME={xdg!r} is not absolute; ignoring\", file=sys.stderr)\n\n    return Path.home() / \".local\" / \"share\" / \"ecc-homunculus\"\n\n\ndef _strip_remote_credentials(remote_url: str) -> str:\n    return re.sub(r\"://[^@]+@\", \"://\", remote_url or \"\")\n\n\ndef _normalize_remote_url(remote_url: str) -> str:\n    if not remote_url:\n        return \"\"\n\n    is_network = (\n        not remote_url.startswith(\"file://\")\n        and (\"://\" in remote_url or re.match(r\"^[^@/:]+@[^:/]+:\", remote_url) is not None)\n    )\n    normalized = _strip_remote_credentials(remote_url)\n    normalized = re.sub(r\"^[A-Za-z][A-Za-z0-9+.-]*://\", \"\", normalized)\n    normalized = re.sub(r\"^[^@/:]+@([^:/]+):\", r\"\\1/\", normalized)\n    normalized = re.sub(r\"\\.git/?$\", \"\", normalized)\n    normalized = re.sub(r\"/+$\", \"\", normalized)\n\n    return normalized.lower() if is_network else normalized\n\n\ndef _stream_can_encode(text: str, stream=None) -> bool:\n    stream = stream or sys.stdout\n    encoding = getattr(stream, \"encoding\", None) or sys.getdefaultencoding()\n    try:\n        text.encode(encoding)\n    except (LookupError, UnicodeEncodeError):\n        return False\n    return True\n\n\ndef _confidence_bar(confidence, stream=None) -> str:\n    try:\n        filled = int(float(confidence) * 10)\n    except (TypeError, ValueError):\n        filled = 5\n    filled = max(0, min(10, filled))\n\n    full, empty = (\"\\u2588\", \"\\u2591\") if _stream_can_encode(\"\\u2588\\u2591\", stream) else (\"#\", \".\")\n    return full * filled + empty * (10 - filled)\n\n\ndef _project_hash(value: str) -> str:\n    return hashlib.sha256(value.encode(\"utf-8\")).hexdigest()[:12]\n\n\nHOMUNCULUS_DIR = _resolve_homunculus_dir()\nPROJECTS_DIR = HOMUNCULUS_DIR / \"projects\"\nREGISTRY_FILE = HOMUNCULUS_DIR / \"projects.json\"\n\n# Global (non-project-scoped) paths\nGLOBAL_INSTINCTS_DIR = HOMUNCULUS_DIR / \"instincts\"\nGLOBAL_PERSONAL_DIR = GLOBAL_INSTINCTS_DIR / \"personal\"\nGLOBAL_INHERITED_DIR = GLOBAL_INSTINCTS_DIR / \"inherited\"\nGLOBAL_EVOLVED_DIR = HOMUNCULUS_DIR / \"evolved\"\nGLOBAL_OBSERVATIONS_FILE = HOMUNCULUS_DIR / \"observations.jsonl\"\n\n# Thresholds for auto-promotion\nPROMOTE_CONFIDENCE_THRESHOLD = 0.8\nPROMOTE_MIN_PROJECTS = 2\nALLOWED_INSTINCT_EXTENSIONS = (\".yaml\", \".yml\", \".md\")\n\n# Default TTL for pending instincts (days)\nPENDING_TTL_DAYS = 30\n# Warning threshold: show expiry warning when instinct expires within this many days\nPENDING_EXPIRY_WARNING_DAYS = 7\n\n# Ensure global directories exist (deferred to avoid side effects at import time)\ndef _ensure_global_dirs():\n    for d in [GLOBAL_PERSONAL_DIR, GLOBAL_INHERITED_DIR,\n              GLOBAL_EVOLVED_DIR / \"skills\", GLOBAL_EVOLVED_DIR / \"commands\", GLOBAL_EVOLVED_DIR / \"agents\",\n              PROJECTS_DIR]:\n        d.mkdir(parents=True, exist_ok=True)\n\n\n# ─────────────────────────────────────────────\n# Path Validation\n# ─────────────────────────────────────────────\n\ndef _validate_file_path(path_str: str, must_exist: bool = False) -> Path:\n    \"\"\"Validate and resolve a file path, guarding against path traversal.\n\n    Raises ValueError if the path is invalid or suspicious.\n    \"\"\"\n    path = Path(path_str).expanduser().resolve()\n\n    # Block paths that escape into system directories\n    # We block specific system paths but allow temp dirs (/var/folders on macOS)\n    blocked_prefixes = [\n        \"/etc\", \"/usr\", \"/bin\", \"/sbin\", \"/proc\", \"/sys\",\n        \"/var/log\", \"/var/run\", \"/var/lib\", \"/var/spool\",\n        # macOS resolves /etc → /private/etc\n        \"/private/etc\",\n        \"/private/var/log\", \"/private/var/run\", \"/private/var/db\",\n    ]\n    path_s = str(path)\n    for prefix in blocked_prefixes:\n        if path_s.startswith(prefix + \"/\") or path_s == prefix:\n            raise ValueError(f\"Path '{path}' targets a system directory\")\n\n    if must_exist and not path.exists():\n        raise ValueError(f\"Path does not exist: {path}\")\n\n    return path\n\n\ndef _validate_instinct_id(instinct_id: str) -> bool:\n    \"\"\"Validate instinct IDs before using them in filenames.\"\"\"\n    if not instinct_id or len(instinct_id) > 128:\n        return False\n    if \"/\" in instinct_id or \"\\\\\" in instinct_id:\n        return False\n    if \"..\" in instinct_id:\n        return False\n    if instinct_id.startswith(\".\"):\n        return False\n    return bool(re.match(r\"^[A-Za-z0-9][A-Za-z0-9._-]*$\", instinct_id))\n\n\ndef _validate_import_url(source: str) -> str:\n    \"\"\"Validate remote instinct imports before opening a network connection.\"\"\"\n    parsed = urllib.parse.urlparse(source)\n    if parsed.scheme != \"https\":\n        raise ValueError(\"remote instinct imports require https URLs\")\n    if not parsed.hostname:\n        raise ValueError(\"remote import URL is missing a hostname\")\n\n    try:\n        addr_infos = socket.getaddrinfo(parsed.hostname, parsed.port or 443, type=socket.SOCK_STREAM)\n    except socket.gaierror as exc:\n        raise ValueError(f\"remote import host could not be resolved: {parsed.hostname}\") from exc\n\n    for family, _, _, _, sockaddr in addr_infos:\n        host = sockaddr[0]\n        try:\n            ip = ipaddress.ip_address(host)\n        except ValueError:\n            continue\n        if (\n            ip.is_private\n            or ip.is_loopback\n            or ip.is_link_local\n            or ip.is_multicast\n            or ip.is_reserved\n            or ip.is_unspecified\n        ):\n            raise ValueError(f\"remote import host resolves to a non-public address: {host}\")\n\n    return urllib.parse.urlunparse(parsed)\n\n\ndef _fetch_import_url(source: str, *, max_bytes: int = 2 * 1024 * 1024) -> str:\n    \"\"\"Fetch a validated remote instinct file with bounded size and timeout.\"\"\"\n    url = _validate_import_url(source)\n    req = urllib.request.Request(url, headers={\"User-Agent\": \"ECC-instinct-import/2\"})\n    with urllib.request.urlopen(req, timeout=15) as response:\n        content_type = response.headers.get(\"Content-Type\", \"\")\n        if content_type and not any(\n            allowed in content_type.lower()\n            for allowed in (\"text/\", \"markdown\", \"yaml\", \"json\", \"octet-stream\")\n        ):\n            raise ValueError(f\"unsupported remote content type: {content_type}\")\n        data = response.read(max_bytes + 1)\n    if len(data) > max_bytes:\n        raise ValueError(f\"remote import exceeds {max_bytes} bytes\")\n    return data.decode(\"utf-8\")\n\n\ndef _yaml_quote(value: str) -> str:\n    \"\"\"Quote a string for safe YAML frontmatter serialization.\n\n    Uses double quotes and escapes embedded double-quote characters to\n    prevent malformed YAML when the value contains quotes.\n    \"\"\"\n    escaped = value.replace('\\\\', '\\\\\\\\').replace('\"', '\\\\\"')\n    return f'\"{escaped}\"'\n\n\n# ─────────────────────────────────────────────\n# Project Detection (Python equivalent of detect-project.sh)\n# ─────────────────────────────────────────────\n\ndef _git_repo_root(cwd: Optional[str] = None) -> Optional[str]:\n    args = [\"git\"]\n    if cwd:\n        args.extend([\"-C\", cwd])\n    args.extend([\"rev-parse\", \"--show-toplevel\"])\n    try:\n        result = subprocess.run(args, capture_output=True, text=True, timeout=5)\n        if result.returncode == 0:\n            return result.stdout.strip()\n    except (subprocess.TimeoutExpired, FileNotFoundError):\n        pass\n    return None\n\n\ndef _main_worktree_root(project_root: str) -> str:\n    \"\"\"Return the main worktree root when project_root is a linked worktree.\"\"\"\n    try:\n        result = subprocess.run(\n            [\"git\", \"-C\", project_root, \"worktree\", \"list\", \"--porcelain\"],\n            capture_output=True, text=True, timeout=5\n        )\n    except (subprocess.TimeoutExpired, FileNotFoundError):\n        return project_root\n\n    if result.returncode != 0:\n        return project_root\n\n    for line in result.stdout.splitlines():\n        if line.startswith(\"worktree \"):\n            main_root = line.split(\" \", 1)[1].strip()\n            return main_root or project_root\n    return project_root\n\n\ndef detect_project() -> dict:\n    \"\"\"Detect current project context. Returns dict with id, name, root, project_dir.\"\"\"\n    project_root = None\n\n    if os.environ.get(\"CLV2_NO_PROJECT\") == \"1\":\n        return {\n            \"id\": \"global\",\n            \"name\": \"global\",\n            \"root\": \"\",\n            \"project_dir\": HOMUNCULUS_DIR,\n            \"instincts_personal\": GLOBAL_PERSONAL_DIR,\n            \"instincts_inherited\": GLOBAL_INHERITED_DIR,\n            \"evolved_dir\": GLOBAL_EVOLVED_DIR,\n            \"observations_file\": GLOBAL_OBSERVATIONS_FILE,\n        }\n\n    # 1. CLAUDE_PROJECT_DIR env var (explicit override)\n    env_dir = os.environ.get(\"CLAUDE_PROJECT_DIR\")\n    if env_dir and os.path.isdir(env_dir):\n        project_root = _git_repo_root(env_dir)\n        # Non-git directory explicitly pointed at by CLAUDE_PROJECT_DIR: honor it\n        # as a project root (path-hash identity) rather than collapsing to the\n        # shared `global` bucket. Mirrors detect-project.sh so the observer\n        # (shell) and this CLI agree on the project id for the same directory;\n        # os.path.realpath matches the shell's `cd ... && pwd -P`. Gated on the\n        # explicit env var so an arbitrary non-git cwd (priority 2) never\n        # becomes a \"project\".\n        if not project_root:\n            project_root = os.path.realpath(env_dir)\n\n    # 2. git repo root\n    if not project_root:\n        project_root = _git_repo_root()\n\n    # Normalize: strip trailing slashes to keep basename and hash stable\n    if project_root:\n        project_root = project_root.rstrip(\"/\")\n\n    # 3. No project — global fallback\n    if not project_root:\n        return {\n            \"id\": \"global\",\n            \"name\": \"global\",\n            \"root\": \"\",\n            \"project_dir\": HOMUNCULUS_DIR,\n            \"instincts_personal\": GLOBAL_PERSONAL_DIR,\n            \"instincts_inherited\": GLOBAL_INHERITED_DIR,\n            \"evolved_dir\": GLOBAL_EVOLVED_DIR,\n            \"observations_file\": GLOBAL_OBSERVATIONS_FILE,\n        }\n\n    project_name = os.path.basename(project_root)\n\n    # Derive project ID from git remote URL or path\n    remote_url = \"\"\n    try:\n        result = subprocess.run(\n            [\"git\", \"-C\", project_root, \"remote\", \"get-url\", \"origin\"],\n            capture_output=True, text=True, timeout=5\n        )\n        if result.returncode == 0:\n            remote_url = result.stdout.strip()\n    except (subprocess.TimeoutExpired, FileNotFoundError):\n        pass\n\n    raw_remote_url = remote_url\n    if remote_url:\n        remote_url = _strip_remote_credentials(remote_url)\n\n    fallback_root = _main_worktree_root(project_root) if not remote_url else project_root\n    legacy_hash_source = remote_url if remote_url else project_root\n    normalized_remote = _normalize_remote_url(remote_url) if remote_url else \"\"\n    hash_source = normalized_remote if normalized_remote else (remote_url if remote_url else fallback_root)\n    project_id = _project_hash(hash_source)\n\n    project_dir = PROJECTS_DIR / project_id\n\n    if not project_dir.exists():\n        legacy_sources = []\n        if legacy_hash_source and legacy_hash_source != hash_source:\n            legacy_sources.append(legacy_hash_source)\n        if raw_remote_url and raw_remote_url not in {hash_source, legacy_hash_source}:\n            legacy_sources.append(raw_remote_url)\n\n        for legacy_source in legacy_sources:\n            legacy_id = _project_hash(legacy_source)\n            legacy_dir = PROJECTS_DIR / legacy_id\n            if legacy_id != project_id and legacy_dir.exists():\n                try:\n                    legacy_dir.rename(project_dir)\n                except OSError:\n                    project_id = legacy_id\n                    project_dir = legacy_dir\n                break\n\n    # Ensure project directory structure\n    for d in [\n        project_dir / \"instincts\" / \"personal\",\n        project_dir / \"instincts\" / \"inherited\",\n        project_dir / \"observations.archive\",\n        project_dir / \"evolved\" / \"skills\",\n        project_dir / \"evolved\" / \"commands\",\n        project_dir / \"evolved\" / \"agents\",\n    ]:\n        d.mkdir(parents=True, exist_ok=True)\n\n    # Update registry\n    _update_registry(project_id, project_name, project_root, remote_url)\n\n    return {\n        \"id\": project_id,\n        \"name\": project_name,\n        \"root\": project_root,\n        \"remote\": remote_url,\n        \"project_dir\": project_dir,\n        \"instincts_personal\": project_dir / \"instincts\" / \"personal\",\n        \"instincts_inherited\": project_dir / \"instincts\" / \"inherited\",\n        \"evolved_dir\": project_dir / \"evolved\",\n        \"observations_file\": project_dir / \"observations.jsonl\",\n    }\n\n\n@contextmanager\ndef _registry_lock():\n    \"\"\"Serialize registry read-modify-write across concurrent sessions.\n\n    Acquires the same advisory lock for every registry writer (``_update_registry``\n    and ``_write_registry``) so ``projects delete/gc/merge`` cannot interleave with\n    a concurrent observe-time update and corrupt ``projects.json``. No-op on\n    platforms without ``fcntl`` (Windows).\n    \"\"\"\n    REGISTRY_FILE.parent.mkdir(parents=True, exist_ok=True)\n    lock_path = REGISTRY_FILE.parent / f\".{REGISTRY_FILE.name}.lock\"\n    lock_fd = None\n    try:\n        if _HAS_FCNTL:\n            lock_fd = open(lock_path, \"w\")\n            fcntl.flock(lock_fd, fcntl.LOCK_EX)\n        yield\n    finally:\n        if lock_fd is not None:\n            fcntl.flock(lock_fd, fcntl.LOCK_UN)\n            lock_fd.close()\n\n\ndef _update_registry(pid: str, pname: str, proot: str, premote: str) -> None:\n    \"\"\"Update the projects.json registry.\n\n    Uses file locking (where available) to prevent concurrent sessions from\n    overwriting each other's updates.\n    \"\"\"\n    with _registry_lock():\n        try:\n            with open(REGISTRY_FILE, encoding=\"utf-8\") as f:\n                registry = json.load(f)\n        except (FileNotFoundError, json.JSONDecodeError):\n            registry = {}\n        # A registry that is valid JSON but not a mapping (e.g. a list from a\n        # corrupt projects.json) must not crash the update before the per-entry\n        # guard below: fall back to an empty dict so the whole file is healed.\n        if not isinstance(registry, dict):\n            registry = {}\n\n        # Mirror the shell counterpart in detect-project.sh: the entry carries\n        # \"id\" and \"created_at\" alongside the other fields so a projects.json\n        # record has the same shape regardless of which path (Python CLI or\n        # shell hook) last wrote it. \"created_at\" is preserved from any\n        # existing entry; only \"last_seen\" advances on update.\n        now = datetime.now(timezone.utc).isoformat().replace(\"+00:00\", \"Z\")\n        existing = registry.get(pid, {})\n        # A malformed registry (e.g. a non-dict value for this id) must not\n        # crash the update: fall back to an empty dict so the corrupt entry is\n        # healed by the rewrite, matching the old unconditional-overwrite\n        # behavior.\n        if not isinstance(existing, dict):\n            existing = {}\n        registry[pid] = {\n            \"id\": pid,\n            \"name\": pname,\n            \"root\": proot,\n            \"remote\": premote,\n            \"created_at\": existing.get(\"created_at\", now),\n            \"last_seen\": now,\n        }\n\n        tmp_file = REGISTRY_FILE.parent / f\".{REGISTRY_FILE.name}.tmp.{os.getpid()}\"\n        with open(tmp_file, \"w\", encoding=\"utf-8\") as f:\n            json.dump(registry, f, indent=2)\n            f.flush()\n            os.fsync(f.fileno())\n        os.replace(tmp_file, REGISTRY_FILE)\n\n\ndef load_registry() -> dict:\n    \"\"\"Load the projects registry.\"\"\"\n    try:\n        with open(REGISTRY_FILE, encoding=\"utf-8\") as f:\n            return json.load(f)\n    except (FileNotFoundError, json.JSONDecodeError):\n        return {}\n\n\ndef _write_registry(registry: dict) -> None:\n    \"\"\"Write the project registry atomically.\n\n    Holds the same advisory lock as ``_update_registry`` so concurrent\n    ``projects delete/gc/merge`` and observe-time updates cannot corrupt the file.\n    \"\"\"\n    with _registry_lock():\n        tmp_file = REGISTRY_FILE.parent / f\".{REGISTRY_FILE.name}.tmp.{os.getpid()}\"\n        with open(tmp_file, \"w\", encoding=\"utf-8\") as f:\n            json.dump(registry, f, indent=2)\n            f.write(\"\\n\")\n            f.flush()\n            os.fsync(f.fileno())\n        os.replace(tmp_file, REGISTRY_FILE)\n\n\ndef _validate_project_id(project_id: str) -> bool:\n    if not project_id or len(project_id) > 128:\n        return False\n    if \"/\" in project_id or \"\\\\\" in project_id or \"..\" in project_id:\n        return False\n    return bool(re.match(r\"^[A-Za-z0-9][A-Za-z0-9._-]*$\", project_id))\n\n\n# ─────────────────────────────────────────────\n# Instinct Parser\n# ─────────────────────────────────────────────\n\ndef parse_instinct_file(content: str) -> list[dict]:\n    \"\"\"Parse YAML-like instinct file format.\n\n    Each instinct is delimited by a pair of ``---`` markers (YAML frontmatter).\n    Note: ``---`` is always treated as a frontmatter boundary; instinct body\n    content must use ``***`` or ``___`` for horizontal rules to avoid ambiguity.\n    \"\"\"\n    instincts = []\n    current = {}\n    in_frontmatter = False\n    content_lines = []\n\n    for line in content.split('\\n'):\n        if line.strip() == '---':\n            if in_frontmatter:\n                # End of frontmatter - content comes next\n                in_frontmatter = False\n            else:\n                # Start of new frontmatter block\n                in_frontmatter = True\n                if current:\n                    current['content'] = '\\n'.join(content_lines).strip()\n                    instincts.append(current)\n                current = {}\n                content_lines = []\n        elif in_frontmatter:\n            # Parse YAML-like frontmatter\n            if ':' in line:\n                key, value = line.split(':', 1)\n                key = key.strip()\n                value = value.strip()\n                # Unescape quoted YAML strings\n                if value.startswith('\"') and value.endswith('\"'):\n                    value = value[1:-1].replace('\\\\\"', '\"').replace('\\\\\\\\', '\\\\')\n                elif value.startswith(\"'\") and value.endswith(\"'\"):\n                    value = value[1:-1].replace(\"''\", \"'\")\n                if key == 'confidence':\n                    try:\n                        current[key] = float(value)\n                    except ValueError:\n                        current[key] = 0.5  # default on malformed confidence\n                else:\n                    current[key] = value\n        else:\n            content_lines.append(line)\n\n    # Don't forget the last instinct\n    if current:\n        current['content'] = '\\n'.join(content_lines).strip()\n        instincts.append(current)\n\n    return [i for i in instincts if i.get('id')]\n\n\ndef _load_instincts_from_dir(directory: Path, source_type: str, scope_label: str) -> list[dict]:\n    \"\"\"Load instincts from a single directory.\"\"\"\n    instincts = []\n    if not directory.exists():\n        return instincts\n    files = [\n        file for file in sorted(directory.iterdir())\n        if file.is_file() and file.suffix.lower() in ALLOWED_INSTINCT_EXTENSIONS\n    ]\n    for file in files:\n        try:\n            content = file.read_text(encoding=\"utf-8\")\n            parsed = parse_instinct_file(content)\n            for inst in parsed:\n                inst['_source_file'] = str(file)\n                inst['_source_type'] = source_type\n                inst['_scope_label'] = scope_label\n                # Default scope if not set in frontmatter\n                if 'scope' not in inst:\n                    inst['scope'] = scope_label\n            instincts.extend(parsed)\n        except Exception as e:\n            print(f\"Warning: Failed to parse {file}: {e}\", file=sys.stderr)\n    return instincts\n\n\ndef _project_counts(project_id: str) -> dict:\n    project_dir = PROJECTS_DIR / project_id\n    personal_dir = project_dir / \"instincts\" / \"personal\"\n    inherited_dir = project_dir / \"instincts\" / \"inherited\"\n    observations_file = project_dir / \"observations.jsonl\"\n\n    personal_count = len(_load_instincts_from_dir(personal_dir, \"personal\", \"project\"))\n    inherited_count = len(_load_instincts_from_dir(inherited_dir, \"inherited\", \"project\"))\n    observations_count = 0\n    if observations_file.exists():\n        try:\n            with open(observations_file, encoding=\"utf-8\") as f:\n                observations_count = sum(1 for _ in f)\n        except OSError:\n            observations_count = 0\n\n    return {\n        \"personal\": personal_count,\n        \"inherited\": inherited_count,\n        \"observations\": observations_count,\n        \"total\": personal_count + inherited_count + observations_count,\n    }\n\n\ndef _remove_project_storage(project_id: str) -> None:\n    # Defense-in-depth: resolve and confirm the target is contained within\n    # PROJECTS_DIR before recursively deleting, even though callers validate the\n    # project id. A relaxed validator or a future caller must never be able to\n    # turn this into an arbitrary-directory delete.\n    projects_root = PROJECTS_DIR.resolve()\n    project_dir = (PROJECTS_DIR / project_id).resolve()\n    if project_dir == projects_root or projects_root not in project_dir.parents:\n        raise ValueError(f\"refusing to remove {project_dir}: escapes {projects_root}\")\n    if project_dir.exists():\n        shutil.rmtree(project_dir)\n\n\ndef _project_instinct_ids(project_dir: Path, source_type: str) -> set[str]:\n    instinct_dir = project_dir / \"instincts\" / source_type\n    return {\n        inst.get(\"id\")\n        for inst in _load_instincts_from_dir(instinct_dir, source_type, \"project\")\n        if inst.get(\"id\")\n    }\n\n\ndef _merge_instinct_dir(from_dir: Path, into_dir: Path, existing_ids: set[str]) -> tuple[int, int]:\n    moved = 0\n    skipped = 0\n    if not from_dir.exists():\n        return moved, skipped\n\n    into_dir.mkdir(parents=True, exist_ok=True)\n    for file_path in sorted(from_dir.iterdir()):\n        if not file_path.is_file() or file_path.suffix.lower() not in ALLOWED_INSTINCT_EXTENSIONS:\n            continue\n        try:\n            instincts = parse_instinct_file(file_path.read_text(encoding=\"utf-8\"))\n        except (OSError, UnicodeDecodeError):\n            instincts = []\n        instinct_ids = [inst.get(\"id\") for inst in instincts if inst.get(\"id\")]\n        if any(instinct_id in existing_ids for instinct_id in instinct_ids):\n            skipped += 1\n            continue\n\n        target_path = into_dir / file_path.name\n        if target_path.exists():\n            target_path = into_dir / f\"{file_path.stem}-{_project_hash(str(file_path))}{file_path.suffix}\"\n        shutil.copy2(file_path, target_path)\n        existing_ids.update(instinct_ids)\n        moved += 1\n\n    return moved, skipped\n\n\ndef _append_observations(from_project_dir: Path, into_project_dir: Path) -> int:\n    from_file = from_project_dir / \"observations.jsonl\"\n    if not from_file.exists():\n        return 0\n\n    into_file = into_project_dir / \"observations.jsonl\"\n    into_file.parent.mkdir(parents=True, exist_ok=True)\n    try:\n        lines = from_file.read_text(encoding=\"utf-8\").splitlines()\n    except (OSError, UnicodeDecodeError):\n        return 0\n\n    if not lines:\n        return 0\n\n    with open(into_file, \"a\", encoding=\"utf-8\") as f:\n        for line in lines:\n            if line.strip():\n                f.write(line.rstrip(\"\\n\") + \"\\n\")\n    return len([line for line in lines if line.strip()])\n\n\ndef load_all_instincts(project: dict, include_global: bool = True) -> list[dict]:\n    \"\"\"Load all instincts: project-scoped + global.\n\n    Project-scoped instincts take precedence over global ones when IDs conflict.\n    \"\"\"\n    instincts = []\n\n    # 1. Load project-scoped instincts (if not already global)\n    if project[\"id\"] != \"global\":\n        instincts.extend(_load_instincts_from_dir(\n            project[\"instincts_personal\"], \"personal\", \"project\"\n        ))\n        instincts.extend(_load_instincts_from_dir(\n            project[\"instincts_inherited\"], \"inherited\", \"project\"\n        ))\n\n    # 2. Load global instincts\n    if include_global:\n        global_instincts = []\n        global_instincts.extend(_load_instincts_from_dir(\n            GLOBAL_PERSONAL_DIR, \"personal\", \"global\"\n        ))\n        global_instincts.extend(_load_instincts_from_dir(\n            GLOBAL_INHERITED_DIR, \"inherited\", \"global\"\n        ))\n\n        # Deduplicate: project-scoped wins over global when same ID\n        project_ids = {i.get('id') for i in instincts}\n        for gi in global_instincts:\n            if gi.get('id') not in project_ids:\n                instincts.append(gi)\n\n    return instincts\n\n\ndef load_project_only_instincts(project: dict) -> list[dict]:\n    \"\"\"Load only project-scoped instincts (no global).\n\n    In global fallback mode (no git project), returns global instincts.\n    \"\"\"\n    if project.get(\"id\") == \"global\":\n        instincts = _load_instincts_from_dir(GLOBAL_PERSONAL_DIR, \"personal\", \"global\")\n        instincts += _load_instincts_from_dir(GLOBAL_INHERITED_DIR, \"inherited\", \"global\")\n        return instincts\n    return load_all_instincts(project, include_global=False)\n\n\n# ─────────────────────────────────────────────\n# Status Command\n# ─────────────────────────────────────────────\n\ndef cmd_status(args) -> int:\n    \"\"\"Show status of all instincts (project + global).\"\"\"\n    project = detect_project()\n    instincts = load_all_instincts(project)\n\n    if not instincts:\n        print(\"No instincts found.\")\n        print(f\"\\nProject: {project['name']} ({project['id']})\")\n        print(f\"  Project instincts:  {project['instincts_personal']}\")\n        print(f\"  Global instincts:   {GLOBAL_PERSONAL_DIR}\")\n    else:\n        # Split by scope\n        project_instincts = [i for i in instincts if i.get('_scope_label') == 'project']\n        global_instincts = [i for i in instincts if i.get('_scope_label') == 'global']\n\n        # Print header\n        print(f\"\\n{'='*60}\")\n        print(f\"  INSTINCT STATUS - {len(instincts)} total\")\n        print(f\"{'='*60}\\n\")\n\n        print(f\"  Project:  {project['name']} ({project['id']})\")\n        print(f\"  Project instincts: {len(project_instincts)}\")\n        print(f\"  Global instincts:  {len(global_instincts)}\")\n        print()\n\n        # Print project-scoped instincts\n        if project_instincts:\n            print(f\"## PROJECT-SCOPED ({project['name']})\")\n            print()\n            _print_instincts_by_domain(project_instincts)\n\n        # Print global instincts\n        if global_instincts:\n            print(\"## GLOBAL (apply to all projects)\")\n            print()\n            _print_instincts_by_domain(global_instincts)\n\n        # Observations stats\n        obs_file = project.get(\"observations_file\")\n        if obs_file and Path(obs_file).exists():\n            with open(obs_file, encoding=\"utf-8\") as f:\n                obs_count = sum(1 for _ in f)\n            print(f\"-\" * 60)\n            print(f\"  Observations: {obs_count} events logged\")\n            print(f\"  File: {obs_file}\")\n\n    # Pending instinct stats\n    pending = _collect_pending_instincts()\n    if pending:\n        print(f\"\\n{'-'*60}\")\n        print(f\"  Pending instincts: {len(pending)} awaiting review\")\n\n        if len(pending) >= 5:\n            print(f\"\\n  \\u26a0 {len(pending)} pending instincts awaiting review.\"\n                  f\" Unreviewed instincts auto-delete after {PENDING_TTL_DAYS} days.\")\n\n        # Show instincts expiring within PENDING_EXPIRY_WARNING_DAYS\n        expiry_threshold = PENDING_TTL_DAYS - PENDING_EXPIRY_WARNING_DAYS\n        expiring_soon = [p for p in pending\n                         if p[\"age_days\"] >= expiry_threshold and p[\"age_days\"] < PENDING_TTL_DAYS]\n        if expiring_soon:\n            print(f\"\\n  Expiring within {PENDING_EXPIRY_WARNING_DAYS} days:\")\n            for item in expiring_soon:\n                days_left = max(0, PENDING_TTL_DAYS - item[\"age_days\"])\n                print(f\"    - {item['name']} ({days_left}d remaining)\")\n\n    # Legacy data warning\n    _warn_legacy_data()\n\n    print(f\"\\n{'='*60}\\n\")\n    return 0\n\n\ndef _warn_legacy_data() -> None:\n    \"\"\"Warn if legacy ~/.claude/homunculus/ contains data while the active\n    path has moved to the XDG directory.\"\"\"\n    legacy_dir = Path.home() / \".claude\" / \"homunculus\"\n    if legacy_dir == HOMUNCULUS_DIR:\n        return  # CLV2_HOMUNCULUS_DIR explicitly points at the legacy path\n    if not legacy_dir.is_dir():\n        return\n\n    # Count substantive files (skip empty dirs and the directory itself)\n    try:\n        legacy_files = [f for f in legacy_dir.rglob(\"*\") if f.is_file()]\n    except (PermissionError, OSError):\n        print(f\"\\n  Note: legacy directory exists but cannot be read: {legacy_dir}\", file=sys.stderr)\n        return\n    if not legacy_files:\n        return\n\n    migrate_script = Path(__file__).resolve().parent / \"migrate-homunculus.sh\"\n\n    print(f\"\\n{'!'*60}\")\n    print(\"  LEGACY DATA DETECTED\")\n    print(f\"{'!'*60}\")\n    print(f\"  Found {len(legacy_files)} file(s) in legacy path:\")\n    print(f\"    {legacy_dir}\")\n    print(\"  Active data directory:\")\n    print(f\"    {HOMUNCULUS_DIR}\")\n    print()\n    print(\"  Run the migration script to move your data:\")\n    print(f'    bash \"{migrate_script}\"')\n    print(f\"  Or set CLV2_HOMUNCULUS_DIR={legacy_dir} to use the legacy path.\")\n    print(f\"{'!'*60}\\n\")\n\n\ndef _print_instincts_by_domain(instincts: list[dict]) -> None:\n    \"\"\"Helper to print instincts grouped by domain.\"\"\"\n    by_domain = defaultdict(list)\n    for inst in instincts:\n        domain = inst.get('domain', 'general')\n        by_domain[domain].append(inst)\n\n    for domain in sorted(by_domain.keys()):\n        domain_instincts = by_domain[domain]\n        print(f\"  ### {domain.upper()} ({len(domain_instincts)})\")\n        print()\n\n        for inst in sorted(domain_instincts, key=lambda x: -x.get('confidence', 0.5)):\n            conf = inst.get('confidence', 0.5)\n            conf_bar = _confidence_bar(conf)\n            trigger = inst.get('trigger', 'unknown trigger')\n            scope_tag = f\"[{inst.get('scope', '?')}]\"\n\n            print(f\"    {conf_bar} {int(conf*100):3d}%  {inst.get('id', 'unnamed')} {scope_tag}\")\n            print(f\"              trigger: {trigger}\")\n\n            # Extract action from content\n            content = inst.get('content', '')\n            action_match = re.search(r'## Action\\s*\\n\\s*(.+?)(?:\\n\\n|\\n##|$)', content, re.DOTALL)\n            if action_match:\n                action = action_match.group(1).strip().split('\\n')[0]\n                print(f\"              action: {action[:60]}{'...' if len(action) > 60 else ''}\")\n\n            print()\n\n\n# ─────────────────────────────────────────────\n# Import Command\n# ─────────────────────────────────────────────\n\ndef cmd_import(args) -> int:\n    \"\"\"Import instincts from file or URL.\"\"\"\n    project = detect_project()\n    source = args.source\n\n    # Determine target scope\n    target_scope = args.scope or \"project\"\n    if target_scope == \"project\" and project[\"id\"] == \"global\":\n        print(\"No project detected. Importing as global scope.\")\n        target_scope = \"global\"\n\n    # Fetch content\n    if source.startswith('http://') or source.startswith('https://'):\n        print(f\"Fetching from URL: {source}\")\n        try:\n            content = _fetch_import_url(source)\n        except Exception as e:\n            print(f\"Error fetching URL: {e}\", file=sys.stderr)\n            return 1\n    else:\n        try:\n            path = _validate_file_path(source, must_exist=True)\n        except ValueError as e:\n            print(f\"Invalid path: {e}\", file=sys.stderr)\n            return 1\n        if not path.is_file():\n            print(f\"Error: '{path}' is not a regular file.\", file=sys.stderr)\n            return 1\n        content = path.read_text(encoding=\"utf-8\")\n\n    # Parse instincts\n    new_instincts = parse_instinct_file(content)\n    if not new_instincts:\n        print(\"No valid instincts found in source.\")\n        return 1\n\n    print(f\"\\nFound {len(new_instincts)} instincts to import.\")\n    print(f\"Target scope: {target_scope}\")\n    if target_scope == \"project\":\n        print(f\"Target project: {project['name']} ({project['id']})\")\n    print()\n\n    # Load existing instincts for dedup, scoped to the target to avoid\n    # cross-scope shadowing (project instincts hiding global ones or vice versa)\n    if target_scope == \"global\":\n        existing = _load_instincts_from_dir(GLOBAL_PERSONAL_DIR, \"personal\", \"global\")\n        existing += _load_instincts_from_dir(GLOBAL_INHERITED_DIR, \"inherited\", \"global\")\n    else:\n        existing = load_project_only_instincts(project)\n    existing_ids = {i.get('id') for i in existing}\n\n    # Deduplicate within the import source: keep highest confidence per ID\n    best_by_id = {}\n    for inst in new_instincts:\n        inst_id = inst.get('id')\n        if inst_id not in best_by_id or inst.get('confidence', 0.5) > best_by_id[inst_id].get('confidence', 0.5):\n            best_by_id[inst_id] = inst\n    deduped_instincts = list(best_by_id.values())\n\n    # Categorize against existing instincts on disk\n    to_add = []\n    duplicates = []\n    to_update = []\n\n    for inst in deduped_instincts:\n        inst_id = inst.get('id')\n        if inst_id in existing_ids:\n            existing_inst = next((e for e in existing if e.get('id') == inst_id), None)\n            if existing_inst:\n                if inst.get('confidence', 0) > existing_inst.get('confidence', 0):\n                    to_update.append(inst)\n                else:\n                    duplicates.append(inst)\n        else:\n            to_add.append(inst)\n\n    # Filter by minimum confidence\n    min_conf = args.min_confidence if args.min_confidence is not None else 0.0\n    to_add = [i for i in to_add if i.get('confidence', 0.5) >= min_conf]\n    to_update = [i for i in to_update if i.get('confidence', 0.5) >= min_conf]\n\n    # Display summary\n    if to_add:\n        print(f\"NEW ({len(to_add)}):\")\n        for inst in to_add:\n            print(f\"  + {inst.get('id')} (confidence: {inst.get('confidence', 0.5):.2f})\")\n\n    if to_update:\n        print(f\"\\nUPDATE ({len(to_update)}):\")\n        for inst in to_update:\n            print(f\"  ~ {inst.get('id')} (confidence: {inst.get('confidence', 0.5):.2f})\")\n\n    if duplicates:\n        print(f\"\\nSKIP ({len(duplicates)} - already exists with equal/higher confidence):\")\n        for inst in duplicates[:5]:\n            print(f\"  - {inst.get('id')}\")\n        if len(duplicates) > 5:\n            print(f\"  ... and {len(duplicates) - 5} more\")\n\n    if args.dry_run:\n        print(\"\\n[DRY RUN] No changes made.\")\n        return 0\n\n    if not to_add and not to_update:\n        print(\"\\nNothing to import.\")\n        return 0\n\n    # Confirm\n    if not args.force:\n        response = input(f\"\\nImport {len(to_add)} new, update {len(to_update)}? [y/N] \")\n        if response.lower() != 'y':\n            print(\"Cancelled.\")\n            return 0\n\n    # Determine output directory based on scope\n    if target_scope == \"global\":\n        output_dir = GLOBAL_INHERITED_DIR\n    else:\n        output_dir = project[\"instincts_inherited\"]\n\n    output_dir.mkdir(parents=True, exist_ok=True)\n\n    # Collect stale files for instincts being updated (deleted after new file is written).\n    # Allow deletion from any subdirectory (personal/ or inherited/) within the\n    # target scope to prevent the same ID existing in both places. Guard against\n    # cross-scope deletion by restricting to the scope's instincts root.\n    if target_scope == \"global\":\n        scope_root = GLOBAL_INSTINCTS_DIR.resolve()\n    else:\n        scope_root = (project[\"project_dir\"] / \"instincts\").resolve() if project[\"id\"] != \"global\" else GLOBAL_INSTINCTS_DIR.resolve()\n    stale_paths = []\n    for inst in to_update:\n        inst_id = inst.get('id')\n        stale = next((e for e in existing if e.get('id') == inst_id), None)\n        if stale and stale.get('_source_file'):\n            stale_path = Path(stale['_source_file']).resolve()\n            if stale_path.exists() and str(stale_path).startswith(str(scope_root) + os.sep):\n                stale_paths.append(stale_path)\n\n    # Write new file first (safe: if this fails, stale files are preserved)\n    timestamp = datetime.now().strftime('%Y%m%d-%H%M%S')\n    source_name = Path(source).stem if not source.startswith('http') else 'web-import'\n    output_file = output_dir / f\"{source_name}-{timestamp}.yaml\"\n\n    all_to_write = to_add + to_update\n    output_content = f\"# Imported from {source}\\n# Date: {datetime.now().isoformat()}\\n# Scope: {target_scope}\\n\"\n    if target_scope == \"project\":\n        output_content += f\"# Project: {project['name']} ({project['id']})\\n\"\n    output_content += \"\\n\"\n\n    for inst in all_to_write:\n        output_content += \"---\\n\"\n        output_content += f\"id: {inst.get('id')}\\n\"\n        output_content += f\"trigger: {_yaml_quote(inst.get('trigger', 'unknown'))}\\n\"\n        output_content += f\"confidence: {inst.get('confidence', 0.5)}\\n\"\n        output_content += f\"domain: {inst.get('domain', 'general')}\\n\"\n        output_content += \"source: inherited\\n\"\n        output_content += f\"scope: {target_scope}\\n\"\n        output_content += f\"imported_from: {_yaml_quote(source)}\\n\"\n        if target_scope == \"project\":\n            output_content += f\"project_id: {project['id']}\\n\"\n            output_content += f\"project_name: {project['name']}\\n\"\n        if inst.get('source_repo'):\n            output_content += f\"source_repo: {inst.get('source_repo')}\\n\"\n        output_content += \"---\\n\\n\"\n        output_content += inst.get('content', '') + \"\\n\\n\"\n\n    output_file.write_text(output_content, encoding=\"utf-8\")\n\n    # Remove stale files only after the new file has been written successfully\n    for stale_path in stale_paths:\n        try:\n            stale_path.unlink()\n        except OSError:\n            pass  # best-effort removal\n\n    print(f\"\\nImport complete!\")\n    print(f\"   Scope: {target_scope}\")\n    print(f\"   Added: {len(to_add)}\")\n    print(f\"   Updated: {len(to_update)}\")\n    print(f\"   Saved to: {output_file}\")\n\n    return 0\n\n\n# ─────────────────────────────────────────────\n# Export Command\n# ─────────────────────────────────────────────\n\ndef cmd_export(args) -> int:\n    \"\"\"Export instincts to file.\"\"\"\n    project = detect_project()\n\n    # Determine what to export based on scope filter\n    if args.scope == \"project\":\n        instincts = load_project_only_instincts(project)\n    elif args.scope == \"global\":\n        instincts = _load_instincts_from_dir(GLOBAL_PERSONAL_DIR, \"personal\", \"global\")\n        instincts += _load_instincts_from_dir(GLOBAL_INHERITED_DIR, \"inherited\", \"global\")\n    else:\n        instincts = load_all_instincts(project)\n\n    if not instincts:\n        print(\"No instincts to export.\")\n        return 1\n\n    # Filter by domain if specified\n    if args.domain:\n        instincts = [i for i in instincts if i.get('domain') == args.domain]\n\n    # Filter by minimum confidence\n    if args.min_confidence:\n        instincts = [i for i in instincts if i.get('confidence', 0.5) >= args.min_confidence]\n\n    if not instincts:\n        print(\"No instincts match the criteria.\")\n        return 1\n\n    # Generate output\n    output = f\"# Instincts export\\n# Date: {datetime.now().isoformat()}\\n# Total: {len(instincts)}\\n\"\n    if args.scope:\n        output += f\"# Scope: {args.scope}\\n\"\n    if project[\"id\"] != \"global\":\n        output += f\"# Project: {project['name']} ({project['id']})\\n\"\n    output += \"\\n\"\n\n    for inst in instincts:\n        output += \"---\\n\"\n        for key in ['id', 'trigger', 'confidence', 'domain', 'source', 'scope',\n                     'project_id', 'project_name', 'source_repo']:\n            if inst.get(key):\n                value = inst[key]\n                if key == 'trigger':\n                    output += f'{key}: {_yaml_quote(value)}\\n'\n                else:\n                    output += f\"{key}: {value}\\n\"\n        output += \"---\\n\\n\"\n        output += inst.get('content', '') + \"\\n\\n\"\n\n    # Write to file or stdout\n    if args.output:\n        try:\n            out_path = _validate_file_path(args.output)\n        except ValueError as e:\n            print(f\"Invalid output path: {e}\", file=sys.stderr)\n            return 1\n        if out_path.is_dir():\n            print(f\"Error: '{out_path}' is a directory, not a file.\", file=sys.stderr)\n            return 1\n        out_path.parent.mkdir(parents=True, exist_ok=True)\n        out_path.write_text(output, encoding=\"utf-8\")\n        print(f\"Exported {len(instincts)} instincts to {out_path}\")\n    else:\n        print(output)\n\n    return 0\n\n\n# ─────────────────────────────────────────────\n# Evolve Command\n# ─────────────────────────────────────────────\n\n# Words carrying no topical signal in a trigger sentence.\nTRIGGER_STOP_WORDS = {\n    'when', 'while', 'the', 'and', 'or', 'to', 'of', 'in', 'on', 'for', 'with',\n    'that', 'this', 'from', 'into', 'at', 'by', 'as', 'is', 'are', 'be', 'it',\n    'its', 'they', 'them', 'their', 'you', 'your', 'new', 'any', 'all', 'about',\n    'after', 'before', 'over', 'via', 'use', 'using', 'need', 'needs', 'not',\n}\n\n# Overlap coefficient (shared / smaller set) two triggers need to cluster.\n# Jaccard is the wrong metric here: trigger keyword sets average ~7 words, so\n# even clearly-related pairs top out near 0.33 and nothing ever groups.\nTRIGGER_SIMILARITY_THRESHOLD = 0.5\n\n# Guard against one incidental shared word pulling unrelated instincts together.\nTRIGGER_MIN_SHARED_KEYWORDS = 2\n\n\n# Evolved artefact slugs are trimmed to keep file names short. The cut has to\n# land on a word boundary: a hard slice produced names like\n# \"investigating-comple\" and \"learning-about-compl\", which read as typos.\nEVOLVED_SKILL_SLUG_LENGTH = 30\nEVOLVED_COMMAND_SLUG_LENGTH = 20\nEVOLVED_AGENT_SLUG_LENGTH = 20\n\n\ndef _truncate_slug(slug: str, max_length: int) -> str:\n    \"\"\"Trim a slug to max_length without splitting a word.\n\n    Falls back to a hard cut only when the first word is already longer than\n    the limit, because then there is no boundary left to retreat to.\n    \"\"\"\n    if len(slug) <= max_length:\n        return slug\n    head = slug[:max_length]\n    # The cut can already land on a separator, in which case head is a whole\n    # sequence of words and dropping one more would lose a word for nothing.\n    if slug[max_length] == '-':\n        return head.rstrip('-')\n    boundary = head.rfind('-')\n    if boundary > 0:\n        return head[:boundary]\n    return head.strip('-')\n\n\ndef _evolved_skill_name(trigger: str) -> str:\n    \"\"\"Slug used for a generated skill directory. Shared by preview and writer.\"\"\"\n    return _truncate_slug(\n        re.sub(r'[^a-z0-9]+', '-', str(trigger or '').lower()).strip('-'),\n        EVOLVED_SKILL_SLUG_LENGTH,\n    )\n\n\ndef _evolved_command_name(trigger: str) -> str:\n    \"\"\"Slug used for a generated command file. Shared by preview and writer.\"\"\"\n    stripped = str(trigger or 'unknown').lower().replace('when ', '').replace('implementing ', '')\n    return _truncate_slug(\n        re.sub(r'[^a-z0-9]+', '-', stripped).strip('-'),\n        EVOLVED_COMMAND_SLUG_LENGTH,\n    )\n\n\ndef _evolved_agent_name(trigger: str) -> str:\n    \"\"\"Slug used for a generated agent file. Shared by preview and writer.\"\"\"\n    return _truncate_slug(\n        re.sub(r'[^a-z0-9]+', '-', str(trigger or '').lower()).strip('-'),\n        EVOLVED_AGENT_SLUG_LENGTH,\n    )\n\n\n# How many candidates of each kind the analysis prints before summarising the\n# rest. The preview is a sample, never the whole set, so it always says so.\nPREVIEW_LIMIT = 5\n\n\ndef _print_preview_remainder(total: int, shown: int, noun: str) -> None:\n    \"\"\"State how many candidates the preview left out.\n\n    Without this the truncated list reads as the complete set.\n    \"\"\"\n    if total > shown:\n        print(f\"  ... and {total - shown} more {noun} not shown\\n\")\n\n\ndef _assign_unique_slugs(items: list, slug_fn) -> list:\n    \"\"\"Pair every item with a collision-free slug, preserving input order.\n\n    Word-boundary trimming makes collisions more likely because two triggers\n    can now share a whole prefix, and a collision previously meant one\n    generated file silently overwriting another. Preview and writer both call\n    this over the same ordered list, so the names shown and the names written\n    stay identical.\n    \"\"\"\n    used = set()\n    assigned = []\n    for item in items:\n        base = slug_fn(item)\n        if not base:\n            assigned.append((item, ''))\n            continue\n        name = base\n        suffix = 2\n        while name in used:\n            name = f\"{base}-{suffix}\"\n            suffix += 1\n        used.add(name)\n        assigned.append((item, name))\n    return assigned\n\n\ndef _trigger_keywords(trigger: str) -> set:\n    \"\"\"Reduce a trigger sentence to the words that carry its topic.\"\"\"\n    words = re.findall(r'[a-z0-9]+', str(trigger or '').lower())\n    return {w for w in words if len(w) > 2 and w not in TRIGGER_STOP_WORDS}\n\n\ndef _cluster_by_keyword_overlap(instincts: list) -> dict:\n    \"\"\"Group instincts whose triggers share enough keywords.\n\n    Triggers are free-form sentences, so grouping on the whole normalized\n    string puts every instinct in its own bucket and no skill or agent\n    candidate is ever produced. Greedy clustering on keyword overlap groups\n    the near-duplicate instincts that accumulate in a project.\n    \"\"\"\n    clusters = []  # [(shared_keywords, [instincts])]\n\n    for inst in instincts:\n        keywords = _trigger_keywords(inst.get('trigger', ''))\n        if not keywords:\n            continue\n\n        best_index, best_score, best_shared = -1, 0.0, 0\n        for index, (cluster_keywords, _members) in enumerate(clusters):\n            shared = len(keywords & cluster_keywords)\n            smaller = min(len(keywords), len(cluster_keywords))\n            score = shared / smaller if smaller else 0.0\n            if score > best_score:\n                best_index, best_score, best_shared = index, score, shared\n\n        if (best_index >= 0\n                and best_score >= TRIGGER_SIMILARITY_THRESHOLD\n                and best_shared >= TRIGGER_MIN_SHARED_KEYWORDS):\n            cluster_keywords, members = clusters[best_index]\n            members.append(inst)\n            # Keep the shared core so a cluster stays on one topic.\n            clusters[best_index] = (cluster_keywords & keywords, members)\n        else:\n            clusters.append((keywords, [inst]))\n\n    grouped = {}\n    for cluster_keywords, members in clusters:\n        label = ' '.join(sorted(cluster_keywords)[:4]) or 'general'\n        while label in grouped:\n            label += ' +'\n        grouped[label] = members\n    return grouped\n\n\ndef cmd_evolve(args) -> int:\n    \"\"\"Analyze instincts and suggest evolutions to skills/commands/agents.\"\"\"\n    project = detect_project()\n    instincts = load_all_instincts(project)\n\n    if len(instincts) < 3:\n        print(\"Need at least 3 instincts to analyze patterns.\")\n        print(f\"Currently have: {len(instincts)}\")\n        return 1\n\n    project_instincts = [i for i in instincts if i.get('_scope_label') == 'project']\n    global_instincts = [i for i in instincts if i.get('_scope_label') == 'global']\n\n    print(f\"\\n{'='*60}\")\n    print(f\"  EVOLVE ANALYSIS - {len(instincts)} instincts\")\n    print(f\"  Project: {project['name']} ({project['id']})\")\n    print(f\"  Project-scoped: {len(project_instincts)} | Global: {len(global_instincts)}\")\n    print(f\"{'='*60}\\n\")\n\n    # Group by domain\n    by_domain = defaultdict(list)\n    for inst in instincts:\n        domain = inst.get('domain', 'general')\n        by_domain[domain].append(inst)\n\n    # High-confidence instincts by domain (candidates for skills)\n    high_conf = [i for i in instincts if i.get('confidence', 0) >= 0.8]\n    print(f\"High confidence instincts (>=80%): {len(high_conf)}\")\n\n    # Find clusters (instincts with similar triggers)\n    trigger_clusters = _cluster_by_keyword_overlap(instincts)\n\n    # Find clusters with 2+ instincts (good skill candidates)\n    skill_candidates = []\n    for trigger, cluster in trigger_clusters.items():\n        if len(cluster) >= 2:\n            avg_conf = sum(i.get('confidence', 0.5) for i in cluster) / len(cluster)\n            skill_candidates.append({\n                'trigger': trigger,\n                'instincts': cluster,\n                'avg_confidence': avg_conf,\n                'domains': list(set(i.get('domain', 'general') for i in cluster)),\n                'scopes': list(set(i.get('scope', 'project') for i in cluster)),\n            })\n\n    # Sort by cluster size and confidence\n    skill_candidates.sort(key=lambda x: (-len(x['instincts']), -x['avg_confidence']))\n\n    print(f\"\\nPotential skill clusters found: {len(skill_candidates)}\")\n\n    if skill_candidates:\n        print(f\"\\n## SKILL CANDIDATES ({len(skill_candidates)})\\n\")\n        for i, cand in enumerate(skill_candidates[:PREVIEW_LIMIT], 1):\n            scope_info = ', '.join(cand['scopes'])\n            print(f\"{i}. Cluster: \\\"{cand['trigger']}\\\"\")\n            print(f\"   Instincts: {len(cand['instincts'])}\")\n            print(f\"   Avg confidence: {cand['avg_confidence']:.0%}\")\n            print(f\"   Domains: {', '.join(cand['domains'])}\")\n            print(f\"   Scopes: {scope_info}\")\n            print(f\"   Instincts:\")\n            for inst in cand['instincts'][:3]:\n                print(f\"     - {inst.get('id')} [{inst.get('scope', '?')}]\")\n            print()\n        _print_preview_remainder(len(skill_candidates), PREVIEW_LIMIT, 'skill clusters')\n\n    # Command candidates (workflow instincts with high confidence)\n    workflow_instincts = [i for i in instincts if i.get('domain') == 'workflow' and i.get('confidence', 0) >= 0.7]\n    if workflow_instincts:\n        print(f\"\\n## COMMAND CANDIDATES ({len(workflow_instincts)})\\n\")\n        # Slugs come from the same helper the writer uses, over the same ordered\n        # list, or the preview advertises names that differ from the files\n        # --generate actually writes.\n        for inst, cmd_name in _assign_unique_slugs(\n            workflow_instincts,\n            lambda i: _evolved_command_name(i.get('trigger', 'unknown')),\n        )[:PREVIEW_LIMIT]:\n            print(f\"  /{cmd_name}\")\n            print(f\"    From: {inst.get('id')} [{inst.get('scope', '?')}]\")\n            print(f\"    Confidence: {inst.get('confidence', 0.5):.0%}\")\n            print()\n        _print_preview_remainder(len(workflow_instincts), PREVIEW_LIMIT, 'command candidates')\n\n    # Agent candidates (complex multi-step patterns)\n    agent_candidates = [c for c in skill_candidates if len(c['instincts']) >= 3 and c['avg_confidence'] >= 0.75]\n    if agent_candidates:\n        print(f\"\\n## AGENT CANDIDATES ({len(agent_candidates)})\\n\")\n        for cand, agent_name in _assign_unique_slugs(\n            agent_candidates,\n            lambda c: _evolved_agent_name(str(c.get('trigger', '')).strip()),\n        )[:PREVIEW_LIMIT]:\n            print(f\"  {agent_name}\")\n            print(f\"    Covers {len(cand['instincts'])} instincts\")\n            print(f\"    Avg confidence: {cand['avg_confidence']:.0%}\")\n            print()\n        _print_preview_remainder(len(agent_candidates), PREVIEW_LIMIT, 'agent candidates')\n\n    # Promotion candidates (project instincts that could be global)\n    _show_promotion_candidates(project)\n\n    if args.generate:\n        evolved_dir = project[\"evolved_dir\"] if project[\"id\"] != \"global\" else GLOBAL_EVOLVED_DIR\n        generated = _generate_evolved(\n            skill_candidates,\n            workflow_instincts,\n            agent_candidates,\n            evolved_dir,\n            limit=max(0, getattr(args, 'limit', 0) or 0),\n        )\n        if generated:\n            print(f\"\\nGenerated {len(generated)} evolved structures:\")\n            for path in generated:\n                print(f\"   {path}\")\n        else:\n            print(\"\\nNo structures generated (need higher-confidence clusters).\")\n\n    print(f\"\\n{'='*60}\\n\")\n    return 0\n\n\n# ─────────────────────────────────────────────\n# Promote Command\n# ─────────────────────────────────────────────\n\ndef _find_cross_project_instincts() -> dict:\n    \"\"\"Find instincts that appear in multiple projects (promotion candidates).\n\n    Returns dict mapping instinct ID → list of (project_id, instinct) tuples.\n    \"\"\"\n    registry = load_registry()\n    cross_project = defaultdict(list)\n\n    for pid, pinfo in registry.items():\n        project_dir = PROJECTS_DIR / pid\n        personal_dir = project_dir / \"instincts\" / \"personal\"\n        inherited_dir = project_dir / \"instincts\" / \"inherited\"\n\n        # Track instinct IDs already seen for this project to avoid counting\n        # the same instinct twice within one project (e.g. in both personal/ and inherited/)\n        seen_in_project = set()\n        for d, stype in [(personal_dir, \"personal\"), (inherited_dir, \"inherited\")]:\n            for inst in _load_instincts_from_dir(d, stype, \"project\"):\n                iid = inst.get('id')\n                if iid and iid not in seen_in_project:\n                    seen_in_project.add(iid)\n                    cross_project[iid].append((pid, pinfo.get('name', pid), inst))\n\n    # Filter to only those appearing in 2+ unique projects\n    return {iid: entries for iid, entries in cross_project.items() if len(entries) >= 2}\n\n\ndef _show_promotion_candidates(project: dict) -> None:\n    \"\"\"Show instincts that could be promoted from project to global.\"\"\"\n    cross = _find_cross_project_instincts()\n\n    if not cross:\n        return\n\n    # Filter to high-confidence ones not already global\n    global_instincts = _load_instincts_from_dir(GLOBAL_PERSONAL_DIR, \"personal\", \"global\")\n    global_instincts += _load_instincts_from_dir(GLOBAL_INHERITED_DIR, \"inherited\", \"global\")\n    global_ids = {i.get('id') for i in global_instincts}\n\n    candidates = []\n    for iid, entries in cross.items():\n        if iid in global_ids:\n            continue\n        avg_conf = sum(e[2].get('confidence', 0.5) for e in entries) / len(entries)\n        if avg_conf >= PROMOTE_CONFIDENCE_THRESHOLD:\n            candidates.append({\n                'id': iid,\n                'projects': [(pid, pname) for pid, pname, _ in entries],\n                'avg_confidence': avg_conf,\n                'sample': entries[0][2],\n            })\n\n    if candidates:\n        print(f\"\\n## PROMOTION CANDIDATES (project -> global)\\n\")\n        print(f\"  These instincts appear in {PROMOTE_MIN_PROJECTS}+ projects with high confidence:\\n\")\n        for cand in candidates[:10]:\n            proj_names = ', '.join(pname for _, pname in cand['projects'])\n            print(f\"  * {cand['id']} (avg: {cand['avg_confidence']:.0%})\")\n            print(f\"    Found in: {proj_names}\")\n            print()\n        print(f\"  Run `instinct-cli.py promote` to promote these to global scope.\\n\")\n\n\ndef _frontmatter_scalar(lines: list[str], key: str) -> Optional[str]:\n    \"\"\"Extract a simple scalar value from frontmatter lines.\"\"\"\n    for line in lines:\n        if ':' not in line:\n            continue\n        parsed_key, value = line.split(':', 1)\n        if parsed_key.strip() != key:\n            continue\n        value = value.strip()\n        if value.startswith('\"') and value.endswith('\"'):\n            return value[1:-1].replace('\\\\\"', '\"').replace('\\\\\\\\', '\\\\')\n        if value.startswith(\"'\") and value.endswith(\"'\"):\n            return value[1:-1].replace(\"''\", \"'\")\n        return value\n    return None\n\n\ndef _remove_instinct_blocks(content: str, instinct_id: str) -> tuple[str, int]:\n    \"\"\"Remove raw frontmatter blocks with a matching instinct ID.\"\"\"\n    lines = content.splitlines(keepends=True)\n    retained = []\n    removed = 0\n    index = 0\n\n    while index < len(lines):\n        if lines[index].strip() != '---':\n            retained.append(lines[index])\n            index += 1\n            continue\n\n        block_start = index\n        frontmatter_end = index + 1\n        while frontmatter_end < len(lines) and lines[frontmatter_end].strip() != '---':\n            frontmatter_end += 1\n\n        if frontmatter_end >= len(lines):\n            retained.extend(lines[block_start:])\n            break\n\n        next_block_start = frontmatter_end + 1\n        while next_block_start < len(lines) and lines[next_block_start].strip() != '---':\n            next_block_start += 1\n\n        block_id = _frontmatter_scalar(lines[block_start + 1:frontmatter_end], 'id')\n        if block_id == instinct_id:\n            removed += 1\n        else:\n            retained.extend(lines[block_start:next_block_start])\n        index = next_block_start\n\n    return ''.join(retained), removed\n\n\ndef _write_text_atomic(file_path: Path, content: str) -> None:\n    \"\"\"Replace a text file via same-directory temp file.\"\"\"\n    temp_fd, temp_name = tempfile.mkstemp(\n        prefix=f\".{file_path.name}.\",\n        suffix=\".tmp\",\n        dir=file_path.parent,\n        text=True,\n    )\n    temp_file = Path(temp_name)\n    try:\n        with os.fdopen(temp_fd, \"w\", encoding=\"utf-8\") as f:\n            f.write(content)\n            f.flush()\n            os.fsync(f.fileno())\n        os.replace(temp_file, file_path)\n    finally:\n        try:\n            temp_file.unlink()\n        except FileNotFoundError:\n            pass\n\n\ndef _remove_instinct_from_source(source_file_str: str, instinct_id: str) -> None:\n    \"\"\"Strip promoted instinct blocks from the project-scoped source file.\"\"\"\n    source_file = Path(source_file_str)\n    if not source_file.exists():\n        return\n\n    try:\n        content = source_file.read_text(encoding=\"utf-8\")\n    except OSError as exc:\n        print(f\"Warning: Failed to read promoted instinct source {source_file}: {exc}\", file=sys.stderr)\n        return\n\n    remaining_content, removed = _remove_instinct_blocks(content, instinct_id)\n    if removed == 0:\n        return\n\n    try:\n        if remaining_content:\n            _write_text_atomic(source_file, remaining_content)\n        else:\n            source_file.unlink()\n    except OSError as exc:\n        print(f\"Warning: Failed to remove promoted instinct from {source_file}: {exc}\", file=sys.stderr)\n\n\ndef cmd_promote(args) -> int:\n    \"\"\"Promote project-scoped instincts to global scope.\"\"\"\n    project = detect_project()\n\n    if args.instinct_id:\n        # Promote a specific instinct\n        return _promote_specific(project, args.instinct_id, args.force, args.dry_run)\n    else:\n        # Auto-detect promotion candidates\n        return _promote_auto(project, args.force, args.dry_run)\n\n\ndef _promote_specific(project: dict, instinct_id: str, force: bool, dry_run: bool = False) -> int:\n    \"\"\"Promote a specific instinct by ID from current project to global.\"\"\"\n    if not _validate_instinct_id(instinct_id):\n        print(f\"Invalid instinct ID: '{instinct_id}'.\", file=sys.stderr)\n        return 1\n\n    project_instincts = load_project_only_instincts(project)\n    target = next((i for i in project_instincts if i.get('id') == instinct_id), None)\n\n    if not target:\n        print(f\"Instinct '{instinct_id}' not found in project {project['name']}.\")\n        return 1\n\n    # Check if already global\n    global_instincts = _load_instincts_from_dir(GLOBAL_PERSONAL_DIR, \"personal\", \"global\")\n    global_instincts += _load_instincts_from_dir(GLOBAL_INHERITED_DIR, \"inherited\", \"global\")\n    if any(i.get('id') == instinct_id for i in global_instincts):\n        print(f\"Instinct '{instinct_id}' already exists in global scope.\")\n        return 1\n\n    print(f\"\\nPromoting: {instinct_id}\")\n    print(f\"  From: project '{project['name']}'\")\n    print(f\"  Confidence: {target.get('confidence', 0.5):.0%}\")\n    print(f\"  Domain: {target.get('domain', 'general')}\")\n\n    if dry_run:\n        print(\"\\n[DRY RUN] No changes made.\")\n        return 0\n\n    if not force:\n        response = input(f\"\\nPromote to global? [y/N] \")\n        if response.lower() != 'y':\n            print(\"Cancelled.\")\n            return 0\n\n    # Write to global personal directory\n    output_file = GLOBAL_PERSONAL_DIR / f\"{instinct_id}.yaml\"\n    output_content = \"---\\n\"\n    output_content += f\"id: {target.get('id')}\\n\"\n    output_content += f\"trigger: {_yaml_quote(target.get('trigger', 'unknown'))}\\n\"\n    output_content += f\"confidence: {target.get('confidence', 0.5)}\\n\"\n    output_content += f\"domain: {target.get('domain', 'general')}\\n\"\n    output_content += f\"source: {target.get('source', 'promoted')}\\n\"\n    output_content += f\"scope: global\\n\"\n    output_content += f\"promoted_from: {project['id']}\\n\"\n    output_content += f\"promoted_date: {datetime.now(timezone.utc).isoformat().replace('+00:00', 'Z')}\\n\"\n    output_content += \"---\\n\\n\"\n    output_content += target.get('content', '') + \"\\n\"\n\n    output_file.write_text(output_content, encoding=\"utf-8\")\n    source_file = target.get('_source_file')\n    if source_file:\n        _remove_instinct_from_source(source_file, instinct_id)\n    print(f\"\\nPromoted '{instinct_id}' to global scope.\")\n    print(f\"  Saved to: {output_file}\")\n    return 0\n\n\ndef _promote_auto(project: dict, force: bool, dry_run: bool) -> int:\n    \"\"\"Auto-promote instincts found in multiple projects.\"\"\"\n    cross = _find_cross_project_instincts()\n\n    global_instincts = _load_instincts_from_dir(GLOBAL_PERSONAL_DIR, \"personal\", \"global\")\n    global_instincts += _load_instincts_from_dir(GLOBAL_INHERITED_DIR, \"inherited\", \"global\")\n    global_ids = {i.get('id') for i in global_instincts}\n\n    candidates = []\n    for iid, entries in cross.items():\n        if iid in global_ids:\n            continue\n        avg_conf = sum(e[2].get('confidence', 0.5) for e in entries) / len(entries)\n        if avg_conf >= PROMOTE_CONFIDENCE_THRESHOLD and len(entries) >= PROMOTE_MIN_PROJECTS:\n            candidates.append({\n                'id': iid,\n                'entries': entries,\n                'avg_confidence': avg_conf,\n            })\n\n    if not candidates:\n        print(\"No instincts qualify for auto-promotion.\")\n        print(f\"  Criteria: appears in {PROMOTE_MIN_PROJECTS}+ projects, avg confidence >= {PROMOTE_CONFIDENCE_THRESHOLD:.0%}\")\n        return 0\n\n    print(f\"\\n{'='*60}\")\n    print(f\"  AUTO-PROMOTION CANDIDATES - {len(candidates)} found\")\n    print(f\"{'='*60}\\n\")\n\n    for cand in candidates:\n        proj_names = ', '.join(pname for _, pname, _ in cand['entries'])\n        print(f\"  {cand['id']} (avg: {cand['avg_confidence']:.0%})\")\n        print(f\"    Found in {len(cand['entries'])} projects: {proj_names}\")\n\n    if dry_run:\n        print(f\"\\n[DRY RUN] No changes made.\")\n        return 0\n\n    if not force:\n        response = input(f\"\\nPromote {len(candidates)} instincts to global? [y/N] \")\n        if response.lower() != 'y':\n            print(\"Cancelled.\")\n            return 0\n\n    promoted = 0\n    for cand in candidates:\n        if not _validate_instinct_id(cand['id']):\n            print(f\"Skipping invalid instinct ID during promotion: {cand['id']}\", file=sys.stderr)\n            continue\n\n        # Use the highest-confidence version\n        best_entry = max(cand['entries'], key=lambda e: e[2].get('confidence', 0.5))\n        inst = best_entry[2]\n\n        output_file = GLOBAL_PERSONAL_DIR / f\"{cand['id']}.yaml\"\n        output_content = \"---\\n\"\n        output_content += f\"id: {inst.get('id')}\\n\"\n        output_content += f\"trigger: {_yaml_quote(inst.get('trigger', 'unknown'))}\\n\"\n        output_content += f\"confidence: {cand['avg_confidence']}\\n\"\n        output_content += f\"domain: {inst.get('domain', 'general')}\\n\"\n        output_content += f\"source: auto-promoted\\n\"\n        output_content += f\"scope: global\\n\"\n        output_content += f\"promoted_date: {datetime.now(timezone.utc).isoformat().replace('+00:00', 'Z')}\\n\"\n        output_content += f\"seen_in_projects: {len(cand['entries'])}\\n\"\n        output_content += \"---\\n\\n\"\n        output_content += inst.get('content', '') + \"\\n\"\n\n        output_file.write_text(output_content, encoding=\"utf-8\")\n        for _, _, entry_inst in cand['entries']:\n            entry_source = entry_inst.get('_source_file')\n            if entry_source:\n                _remove_instinct_from_source(entry_source, cand['id'])\n        promoted += 1\n\n    print(f\"\\nPromoted {promoted} instincts to global scope.\")\n    return 0\n\n\n# ─────────────────────────────────────────────\n# Projects Command\n# ─────────────────────────────────────────────\n\ndef cmd_projects(args) -> int:\n    \"\"\"List or maintain known projects and their instinct counts.\"\"\"\n    if getattr(args, \"project_action\", None) == \"delete\":\n        return _cmd_projects_delete(args)\n    if getattr(args, \"project_action\", None) == \"merge\":\n        return _cmd_projects_merge(args)\n    if getattr(args, \"project_action\", None) == \"gc\":\n        return _cmd_projects_gc(args)\n\n    registry = load_registry()\n\n    if not registry:\n        print(\"No projects registered yet.\")\n        print(\"Projects are auto-detected when you use Claude Code in a git repo.\")\n        return 0\n\n    print(f\"\\n{'='*60}\")\n    print(f\"  KNOWN PROJECTS - {len(registry)} total\")\n    print(f\"{'='*60}\\n\")\n\n    for pid, pinfo in sorted(registry.items(), key=lambda x: x[1].get('last_seen', ''), reverse=True):\n        project_dir = PROJECTS_DIR / pid\n        personal_dir = project_dir / \"instincts\" / \"personal\"\n        inherited_dir = project_dir / \"instincts\" / \"inherited\"\n\n        personal_count = len(_load_instincts_from_dir(personal_dir, \"personal\", \"project\"))\n        inherited_count = len(_load_instincts_from_dir(inherited_dir, \"inherited\", \"project\"))\n        obs_file = project_dir / \"observations.jsonl\"\n        if obs_file.exists():\n            with open(obs_file, encoding=\"utf-8\") as f:\n                obs_count = sum(1 for _ in f)\n        else:\n            obs_count = 0\n\n        print(f\"  {pinfo.get('name', pid)} [{pid}]\")\n        print(f\"    Root: {pinfo.get('root', 'unknown')}\")\n        if pinfo.get('remote'):\n            print(f\"    Remote: {pinfo['remote']}\")\n        print(f\"    Instincts: {personal_count} personal, {inherited_count} inherited\")\n        print(f\"    Observations: {obs_count} events\")\n        print(f\"    Last seen: {pinfo.get('last_seen', 'unknown')}\")\n        print()\n\n    # Global stats\n    global_personal = len(_load_instincts_from_dir(GLOBAL_PERSONAL_DIR, \"personal\", \"global\"))\n    global_inherited = len(_load_instincts_from_dir(GLOBAL_INHERITED_DIR, \"inherited\", \"global\"))\n    print(f\"  GLOBAL\")\n    print(f\"    Instincts: {global_personal} personal, {global_inherited} inherited\")\n\n    print(f\"\\n{'='*60}\\n\")\n    return 0\n\n\ndef _cmd_projects_delete(args) -> int:\n    registry = load_registry()\n    project_id = args.project_id\n\n    if not _validate_project_id(project_id):\n        print(f\"Invalid project ID: {project_id}\", file=sys.stderr)\n        return 1\n    if project_id not in registry and not (PROJECTS_DIR / project_id).exists():\n        print(f\"Project '{project_id}' not found.\", file=sys.stderr)\n        return 1\n\n    counts = _project_counts(project_id)\n    print(f\"Project: {project_id}\")\n    print(f\"  Instincts: {counts['personal']} personal, {counts['inherited']} inherited\")\n    print(f\"  Observations: {counts['observations']} events\")\n\n    if args.dry_run:\n        print(f\"\\n[DRY RUN] Would delete project '{project_id}' from registry and storage.\")\n        return 0\n\n    if not args.force:\n        if counts[\"total\"] > 0:\n            print(\"\\nWarning: this project has instincts or observations.\")\n        response = input(f\"Delete project '{project_id}'? [y/N] \")\n        if response.lower() != \"y\":\n            print(\"Cancelled.\")\n            return 0\n\n    registry.pop(project_id, None)\n    _write_registry(registry)\n    _remove_project_storage(project_id)\n    print(f\"\\nDeleted project '{project_id}'.\")\n    return 0\n\n\ndef _cmd_projects_gc(args) -> int:\n    registry = load_registry()\n    candidates = [\n        project_id\n        for project_id in sorted(registry)\n        if _validate_project_id(project_id) and _project_counts(project_id)[\"total\"] == 0\n    ]\n\n    if not candidates:\n        print(\"No zero-value project entries found.\")\n        return 0\n\n    print(f\"Zero-value project entries: {len(candidates)}\")\n    for project_id in candidates:\n        pinfo = registry.get(project_id, {})\n        print(f\"  - {pinfo.get('name', project_id)} [{project_id}]\")\n\n    if args.dry_run:\n        print(f\"\\n[DRY RUN] Would delete {len(candidates)} project entr{'y' if len(candidates) == 1 else 'ies'}.\")\n        return 0\n\n    if not args.force:\n        response = input(f\"\\nDelete {len(candidates)} zero-value project entr{'y' if len(candidates) == 1 else 'ies'}? [y/N] \")\n        if response.lower() != \"y\":\n            print(\"Cancelled.\")\n            return 0\n\n    for project_id in candidates:\n        registry.pop(project_id, None)\n        _remove_project_storage(project_id)\n    _write_registry(registry)\n    print(f\"\\nDeleted {len(candidates)} zero-value project entr{'y' if len(candidates) == 1 else 'ies'}.\")\n    return 0\n\n\ndef _cmd_projects_merge(args) -> int:\n    from_id = args.from_id\n    into_id = args.into_id\n\n    if not _validate_project_id(from_id) or not _validate_project_id(into_id):\n        print(\"Invalid project ID.\", file=sys.stderr)\n        return 1\n    if from_id == into_id:\n        print(\"Cannot merge a project into itself.\", file=sys.stderr)\n        return 1\n\n    registry = load_registry()\n    if from_id not in registry:\n        print(f\"Source project '{from_id}' not found.\", file=sys.stderr)\n        return 1\n    if into_id not in registry:\n        print(f\"Destination project '{into_id}' not found.\", file=sys.stderr)\n        return 1\n\n    from_counts = _project_counts(from_id)\n    into_counts = _project_counts(into_id)\n    print(f\"Merge: {from_id} -> {into_id}\")\n    print(f\"  Source: {from_counts['personal']} personal, {from_counts['inherited']} inherited, {from_counts['observations']} observations\")\n    print(f\"  Destination before merge: {into_counts['personal']} personal, {into_counts['inherited']} inherited, {into_counts['observations']} observations\")\n\n    if args.dry_run:\n        print(\"\\n[DRY RUN] Would merge source project into destination and remove source.\")\n        return 0\n\n    if not args.force:\n        response = input(f\"\\nMerge '{from_id}' into '{into_id}' and remove source? [y/N] \")\n        if response.lower() != \"y\":\n            print(\"Cancelled.\")\n            return 0\n\n    from_project_dir = PROJECTS_DIR / from_id\n    into_project_dir = PROJECTS_DIR / into_id\n    into_project_dir.mkdir(parents=True, exist_ok=True)\n\n    personal_existing = _project_instinct_ids(into_project_dir, \"personal\")\n    inherited_existing = _project_instinct_ids(into_project_dir, \"inherited\")\n    personal_moved, personal_skipped = _merge_instinct_dir(\n        from_project_dir / \"instincts\" / \"personal\",\n        into_project_dir / \"instincts\" / \"personal\",\n        personal_existing,\n    )\n    inherited_moved, inherited_skipped = _merge_instinct_dir(\n        from_project_dir / \"instincts\" / \"inherited\",\n        into_project_dir / \"instincts\" / \"inherited\",\n        inherited_existing,\n    )\n    observations_moved = _append_observations(from_project_dir, into_project_dir)\n\n    registry.pop(from_id, None)\n    destination = registry.get(into_id, {})\n    destination[\"last_seen\"] = datetime.now(timezone.utc).isoformat().replace(\"+00:00\", \"Z\")\n    registry[into_id] = destination\n    _write_registry(registry)\n    _remove_project_storage(from_id)\n\n    print(\"\\nMerged project registry entry.\")\n    print(f\"  Moved instincts: {personal_moved + inherited_moved}\")\n    print(f\"  Skipped duplicate instincts: {personal_skipped + inherited_skipped}\")\n    print(f\"  Appended observations: {observations_moved}\")\n    return 0\n\n\n# ─────────────────────────────────────────────\n# Generate Evolved Structures\n# ─────────────────────────────────────────────\n\ndef _generate_evolved(skill_candidates: list, workflow_instincts: list, agent_candidates: list, evolved_dir: Path, limit: int = 0) -> list[str]:\n    \"\"\"Generate skill/command/agent files from analyzed instinct clusters.\n\n    ``limit`` caps how many candidates of each kind are written; 0 writes them\n    all. Anything a cap leaves out is reported, because the previous fixed\n    caps (5 skills, 5 commands, 3 agents) discarded most candidates without\n    saying a word — 35 command candidates produced 5 files and no warning.\n    \"\"\"\n    generated = []\n\n    def bounded(assigned: list, kind: str) -> list:\n        if limit and len(assigned) > limit:\n            print(f\"\\nNote: writing {limit} of {len(assigned)} {kind} candidates \"\n                  f\"(--limit {limit}); {len(assigned) - limit} skipped.\")\n            return assigned[:limit]\n        return assigned\n\n    # Generate skills from candidate clusters\n    for cand, name in bounded(\n        _assign_unique_slugs(\n            skill_candidates,\n            lambda c: _evolved_skill_name(str(c.get('trigger', '')).strip()),\n        ),\n        'skill',\n    ):\n        trigger = cand['trigger'].strip()\n        if not trigger or not name:\n            continue\n\n        skill_dir = evolved_dir / \"skills\" / name\n        skill_dir.mkdir(parents=True, exist_ok=True)\n\n        content = f\"# {name}\\n\\n\"\n        content += f\"Evolved from {len(cand['instincts'])} instincts \"\n        content += f\"(avg confidence: {cand['avg_confidence']:.0%})\\n\\n\"\n        content += f\"## When to Apply\\n\\n\"\n        content += f\"Trigger: {trigger}\\n\\n\"\n        content += f\"## Actions\\n\\n\"\n        for inst in cand['instincts']:\n            inst_content = inst.get('content', '')\n            action_match = re.search(r'## Action\\s*\\n\\s*(.+?)(?:\\n\\n|\\n##|$)', inst_content, re.DOTALL)\n            action = action_match.group(1).strip() if action_match else inst.get('id', 'unnamed')\n            content += f\"- {action}\\n\"\n\n        (skill_dir / \"SKILL.md\").write_text(content, encoding=\"utf-8\")\n        generated.append(str(skill_dir / \"SKILL.md\"))\n\n    # Generate commands from workflow instincts\n    for inst, cmd_name in bounded(\n        _assign_unique_slugs(\n            workflow_instincts,\n            lambda i: _evolved_command_name(i.get('trigger', 'unknown')),\n        ),\n        'command',\n    ):\n        if not cmd_name:\n            continue\n\n        cmd_file = evolved_dir / \"commands\" / f\"{cmd_name}.md\"\n        content = f\"# {cmd_name}\\n\\n\"\n        content += f\"Evolved from instinct: {inst.get('id', 'unnamed')}\\n\"\n        content += f\"Confidence: {inst.get('confidence', 0.5):.0%}\\n\\n\"\n        content += inst.get('content', '')\n\n        cmd_file.write_text(content, encoding=\"utf-8\")\n        generated.append(str(cmd_file))\n\n    # Generate agents from complex clusters\n    for cand, agent_name in bounded(\n        _assign_unique_slugs(\n            agent_candidates,\n            lambda c: _evolved_agent_name(str(c.get('trigger', '')).strip()),\n        ),\n        'agent',\n    ):\n        if not agent_name:\n            continue\n\n        agent_file = evolved_dir / \"agents\" / f\"{agent_name}.md\"\n        domains = ', '.join(cand['domains'])\n        instinct_ids = [i.get('id', 'unnamed') for i in cand['instincts']]\n\n        content = f\"---\\nmodel: sonnet\\ntools: Read, Grep, Glob\\n---\\n\"\n        content += f\"# {agent_name}\\n\\n\"\n        content += f\"Evolved from {len(cand['instincts'])} instincts \"\n        content += f\"(avg confidence: {cand['avg_confidence']:.0%})\\n\"\n        content += f\"Domains: {domains}\\n\\n\"\n        content += f\"## Source Instincts\\n\\n\"\n        for iid in instinct_ids:\n            content += f\"- {iid}\\n\"\n\n        agent_file.write_text(content, encoding=\"utf-8\")\n        generated.append(str(agent_file))\n\n    return generated\n\n\n# ─────────────────────────────────────────────\n# Pending Instinct Helpers\n# ─────────────────────────────────────────────\n\ndef _collect_pending_dirs() -> list[Path]:\n    \"\"\"Return all pending instinct directories (global + per-project).\"\"\"\n    dirs = []\n    global_pending = GLOBAL_INSTINCTS_DIR / \"pending\"\n    if global_pending.is_dir():\n        dirs.append(global_pending)\n    if PROJECTS_DIR.is_dir():\n        for project_dir in sorted(PROJECTS_DIR.iterdir()):\n            if project_dir.is_dir():\n                pending = project_dir / \"instincts\" / \"pending\"\n                if pending.is_dir():\n                    dirs.append(pending)\n    return dirs\n\n\ndef _parse_created_date(file_path: Path) -> Optional[datetime]:\n    \"\"\"Parse the 'created' date from YAML frontmatter of an instinct file.\n\n    Falls back to file mtime if no 'created' field is found.\n    \"\"\"\n    try:\n        content = file_path.read_text(encoding=\"utf-8\")\n    except (OSError, UnicodeDecodeError):\n        return None\n\n    in_frontmatter = False\n    for line in content.split('\\n'):\n        stripped = line.strip()\n        if stripped == '---':\n            if in_frontmatter:\n                break  # end of frontmatter without finding created\n            in_frontmatter = True\n            continue\n        if in_frontmatter and ':' in line:\n            key, value = line.split(':', 1)\n            if key.strip() == 'created':\n                date_str = value.strip().strip('\"').strip(\"'\")\n                for fmt in (\n                    \"%Y-%m-%dT%H:%M:%S%z\",\n                    \"%Y-%m-%dT%H:%M:%SZ\",\n                    \"%Y-%m-%dT%H:%M:%S\",\n                    \"%Y-%m-%d\",\n                ):\n                    try:\n                        dt = datetime.strptime(date_str, fmt)\n                        if dt.tzinfo is None:\n                            dt = dt.replace(tzinfo=timezone.utc)\n                        return dt\n                    except ValueError:\n                        continue\n\n    # Fallback: file modification time\n    try:\n        mtime = file_path.stat().st_mtime\n        return datetime.fromtimestamp(mtime, tz=timezone.utc)\n    except OSError:\n        return None\n\n\ndef _collect_pending_instincts() -> list[dict]:\n    \"\"\"Scan all pending directories and return info about each pending instinct.\n\n    Each dict contains: path, created, age_days, name, parent_dir.\n    \"\"\"\n    now = datetime.now(timezone.utc)\n    results = []\n    for pending_dir in _collect_pending_dirs():\n        files = [\n            f for f in sorted(pending_dir.iterdir())\n            if f.is_file() and f.suffix.lower() in ALLOWED_INSTINCT_EXTENSIONS\n        ]\n        for file_path in files:\n            created = _parse_created_date(file_path)\n            if created is None:\n                print(f\"Warning: could not parse age for pending instinct: {file_path.name}\", file=sys.stderr)\n                continue\n            age = now - created\n            results.append({\n                \"path\": file_path,\n                \"created\": created,\n                \"age_days\": age.days,\n                \"name\": file_path.stem,\n                \"parent_dir\": str(pending_dir),\n            })\n    return results\n\n\n# ─────────────────────────────────────────────\n# Prune Command\n# ─────────────────────────────────────────────\n\ndef cmd_prune(args) -> int:\n    \"\"\"Delete pending instincts older than the TTL threshold.\"\"\"\n    max_age = args.max_age\n    dry_run = args.dry_run\n    quiet = args.quiet\n\n    pending = _collect_pending_instincts()\n\n    expired = [p for p in pending if p[\"age_days\"] >= max_age]\n    remaining = [p for p in pending if p[\"age_days\"] < max_age]\n\n    if dry_run:\n        if not quiet:\n            if expired:\n                print(f\"\\n[DRY RUN] Would prune {len(expired)} pending instinct(s) older than {max_age} days:\\n\")\n                for item in expired:\n                    print(f\"  - {item['name']} (age: {item['age_days']}d) — {item['path']}\")\n            else:\n                print(f\"No pending instincts older than {max_age} days.\")\n            print(f\"\\nSummary: {len(expired)} would be pruned, {len(remaining)} remaining\")\n        return 0\n\n    pruned = 0\n    pruned_items = []\n    for item in expired:\n        try:\n            item[\"path\"].unlink()\n            pruned += 1\n            pruned_items.append(item)\n        except OSError as e:\n            if not quiet:\n                print(f\"Warning: Failed to delete {item['path']}: {e}\", file=sys.stderr)\n\n    if not quiet:\n        if pruned > 0:\n            print(f\"\\nPruned {pruned} pending instinct(s) older than {max_age} days.\")\n            for item in pruned_items:\n                print(f\"  - {item['name']} (age: {item['age_days']}d)\")\n        else:\n            print(f\"No pending instincts older than {max_age} days.\")\n        failed = len(expired) - pruned\n        remaining_total = len(remaining) + failed\n        print(f\"\\nSummary: {pruned} pruned, {remaining_total} remaining\")\n\n    return 0\n\n\n# ─────────────────────────────────────────────\n# Main\n# ─────────────────────────────────────────────\n\ndef main() -> int:\n    _ensure_global_dirs()\n    parser = argparse.ArgumentParser(description='Instinct CLI for Continuous Learning v2.1 (Project-Scoped)')\n    subparsers = parser.add_subparsers(dest='command', help='Available commands')\n\n    # Status\n    status_parser = subparsers.add_parser('status', help='Show instinct status (project + global)')\n\n    # Import\n    import_parser = subparsers.add_parser('import', help='Import instincts')\n    import_parser.add_argument('source', help='File path or URL')\n    import_parser.add_argument('--dry-run', action='store_true', help='Preview without importing')\n    import_parser.add_argument('--force', action='store_true', help='Skip confirmation')\n    import_parser.add_argument('--min-confidence', type=float, help='Minimum confidence threshold')\n    import_parser.add_argument('--scope', choices=['project', 'global'], default='project',\n                               help='Import scope (default: project)')\n\n    # Export\n    export_parser = subparsers.add_parser('export', help='Export instincts')\n    export_parser.add_argument('--output', '-o', help='Output file')\n    export_parser.add_argument('--domain', help='Filter by domain')\n    export_parser.add_argument('--min-confidence', type=float, help='Minimum confidence')\n    export_parser.add_argument('--scope', choices=['project', 'global', 'all'], default='all',\n                               help='Export scope (default: all)')\n\n    # Evolve\n    evolve_parser = subparsers.add_parser('evolve', help='Analyze and evolve instincts')\n    evolve_parser.add_argument('--generate', action='store_true', help='Generate evolved structures')\n    evolve_parser.add_argument('--limit', type=int, default=0, metavar='N',\n                               help='Max candidates of each kind to generate (default: 0 = all)')\n\n    # Promote (new in v2.1)\n    promote_parser = subparsers.add_parser('promote', help='Promote project instincts to global scope')\n    promote_parser.add_argument('instinct_id', nargs='?', help='Specific instinct ID to promote')\n    promote_parser.add_argument('--force', action='store_true', help='Skip confirmation')\n    promote_parser.add_argument('--dry-run', action='store_true', help='Preview without promoting')\n\n    # Projects (new in v2.1)\n    projects_parser = subparsers.add_parser('projects', help='List known projects and instinct counts')\n    projects_subparsers = projects_parser.add_subparsers(dest='project_action')\n    projects_delete = projects_subparsers.add_parser('delete', help='Delete a project registry entry')\n    projects_delete.add_argument('project_id', help='Project ID to delete')\n    projects_delete.add_argument('--dry-run', action='store_true', help='Preview without deleting')\n    projects_delete.add_argument('--force', action='store_true', help='Skip confirmation')\n    projects_merge = projects_subparsers.add_parser('merge', help='Merge one project registry entry into another')\n    projects_merge.add_argument('from_id', help='Source project ID')\n    projects_merge.add_argument('into_id', help='Destination project ID')\n    projects_merge.add_argument('--dry-run', action='store_true', help='Preview without merging')\n    projects_merge.add_argument('--force', action='store_true', help='Skip confirmation')\n    projects_gc = projects_subparsers.add_parser('gc', help='Delete zero-value project registry entries')\n    projects_gc.add_argument('--dry-run', action='store_true', help='Preview without deleting')\n    projects_gc.add_argument('--force', action='store_true', help='Skip confirmation')\n\n    # Prune (pending instinct TTL)\n    prune_parser = subparsers.add_parser('prune', help='Delete pending instincts older than TTL')\n    prune_parser.add_argument('--max-age', type=int, default=PENDING_TTL_DAYS,\n                              help=f'Max age in days before pruning (default: {PENDING_TTL_DAYS})')\n    prune_parser.add_argument('--dry-run', action='store_true', help='Preview without deleting')\n    prune_parser.add_argument('--quiet', action='store_true', help='Suppress output (for automated use)')\n\n    args = parser.parse_args()\n\n    if args.command == 'status':\n        return cmd_status(args)\n    elif args.command == 'import':\n        return cmd_import(args)\n    elif args.command == 'export':\n        return cmd_export(args)\n    elif args.command == 'evolve':\n        return cmd_evolve(args)\n    elif args.command == 'promote':\n        return cmd_promote(args)\n    elif args.command == 'projects':\n        return cmd_projects(args)\n    elif args.command == 'prune':\n        return cmd_prune(args)\n    else:\n        parser.print_help()\n        return 1\n\n\nif __name__ == '__main__':\n    sys.exit(main())\n"},{"path":"scripts/lib/homunculus-dir.sh","text":"#!/usr/bin/env bash\n# Shared continuous-learning-v2 data-directory resolver.\n#\n# Resolution precedence:\n#   1. CLV2_HOMUNCULUS_DIR, when absolute\n#   2. XDG_DATA_HOME/ecc-homunculus, when XDG_DATA_HOME is absolute\n#   3. HOME/.local/share/ecc-homunculus\n\n_clv2_resolve_homunculus_dir() {\n  if [ -n \"${CLV2_HOMUNCULUS_DIR:-}\" ]; then\n    case \"$CLV2_HOMUNCULUS_DIR\" in\n      /*) printf '%s\\n' \"$CLV2_HOMUNCULUS_DIR\"; return 0 ;;\n      *) printf '[ecc] CLV2_HOMUNCULUS_DIR=%s is not absolute; ignoring\\n' \"$CLV2_HOMUNCULUS_DIR\" >&2 ;;\n    esac\n  fi\n\n  if [ -n \"${XDG_DATA_HOME:-}\" ]; then\n    case \"$XDG_DATA_HOME\" in\n      /*) printf '%s/ecc-homunculus\\n' \"$XDG_DATA_HOME\"; return 0 ;;\n      *) printf '[ecc] XDG_DATA_HOME=%s is not absolute; ignoring\\n' \"$XDG_DATA_HOME\" >&2 ;;\n    esac\n  fi\n\n  case \"${HOME:-}\" in\n    /*) printf '%s/.local/share/ecc-homunculus\\n' \"$HOME\" ;;\n    *)\n      printf '[ecc] HOME=%s is not absolute; cannot resolve homunculus dir\\n' \"${HOME:-}\" >&2\n      return 1\n      ;;\n  esac\n}\n"},{"path":"scripts/migrate-homunculus.sh","text":"#!/usr/bin/env bash\n# One-shot migration from the legacy Claude config tree into the\n# continuous-learning-v2 data directory.\nset -euo pipefail\n\nOLD=\"${HOME}/.claude/homunculus\"\n\n# shellcheck disable=SC1091\n. \"$(dirname \"$0\")/lib/homunculus-dir.sh\"\nNEW=\"$(_clv2_resolve_homunculus_dir)\"\n\nif [ \"$NEW\" = \"$OLD\" ]; then\n  echo \"Resolved destination equals source ($OLD); nothing to migrate.\"\n  exit 0\nfi\n\nif [ ! -d \"$OLD\" ]; then\n  echo \"Nothing to migrate (no $OLD).\"\n  exit 0\nfi\n\nif command -v pgrep >/dev/null 2>&1; then\n  # pgrep -f treats its argument as an extended regular expression, so $HOME\n  # must be escaped before interpolation. Without this, regex metacharacters in\n  # the path (e.g. /home/user.name, /home/c++dev, /home/user (work)) would make\n  # the match over-broad or invalid, causing false negatives (observer missed,\n  # migration proceeds unsafely) or false positives (migration blocked).\n  escaped_home=\"$(printf '%s' \"$HOME\" | sed 's/[]\\.[(){}+*?|^$]/\\\\&/g')\"\n  if pgrep -f \"${escaped_home}.*observer-loop\\\\.sh\" >/dev/null 2>&1; then\n    echo \"Refusing to migrate: observer-loop.sh is running.\" >&2\n    echo \"Exit all Claude Code sessions, then re-run.\" >&2\n    exit 1\n  fi\nelse\n  echo \"Warning: pgrep not available; skipping running-observer check.\" >&2\nfi\n\nmkdir -p \"$(dirname \"$NEW\")\"\n\nif [ ! -d \"$NEW\" ]; then\n  mv \"$OLD\" \"$NEW\"\n  echo \"Moved $OLD -> $NEW\"\nelif [ -z \"$(ls -A \"$NEW\" 2>/dev/null || true)\" ]; then\n  rmdir \"$NEW\"\n  mv \"$OLD\" \"$NEW\"\n  echo \"Moved $OLD -> $NEW (replaced empty destination)\"\nelse\n  old_count=\"$(find \"$OLD\" -type f 2>/dev/null | wc -l | tr -d ' ')\"\n  new_count=\"$(find \"$NEW\" -type f 2>/dev/null | wc -l | tr -d ' ')\"\n  echo \"Refusing to migrate: both paths exist with content.\" >&2\n  echo \"  Old: $OLD ($old_count files)\" >&2\n  echo \"  New: $NEW ($new_count files)\" >&2\n  echo \"Resolve manually, then re-run.\" >&2\n  exit 1\nfi\n\nsettings=\"${HOME}/.claude/settings.json\"\nif [ -f \"$settings\" ] && grep -q '\"CLV2_CONFIG\"' \"$settings\" 2>/dev/null; then\n  if grep -q '\\.claude/homunculus' \"$settings\" 2>/dev/null; then\n    cat >&2 <<WARN\n\nAdvisory: ~/.claude/settings.json still sets CLV2_CONFIG under the old path.\nUpdate it to: ${NEW}/config.json\n(Not editing settings.json automatically.)\n\nWARN\n  fi\nfi\n"},{"path":"scripts/test_parse_instinct.py","text":"\"\"\"Tests for continuous-learning-v2 instinct-cli.py\n\nCovers:\n  - parse_instinct_file() — content preservation, edge cases\n  - _validate_file_path() — path traversal blocking\n  - detect_project() — project detection with mocked git/env\n  - load_all_instincts() — loading from project + global dirs, dedup\n  - _load_instincts_from_dir() — directory scanning\n  - cmd_projects() — listing projects from registry\n  - cmd_status() — status display\n  - _promote_specific() — single instinct promotion\n  - _promote_auto() — auto-promotion across projects\n\"\"\"\n\nimport importlib.util\nimport io\nimport json\nimport os\nimport sys\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport pytest\n\n# Load instinct-cli.py (hyphenated filename requires importlib)\n_spec = importlib.util.spec_from_file_location(\n    \"instinct_cli\",\n    os.path.join(os.path.dirname(__file__), \"instinct-cli.py\"),\n)\n_mod = importlib.util.module_from_spec(_spec)\n_spec.loader.exec_module(_mod)\n\nparse_instinct_file = _mod.parse_instinct_file\n_validate_file_path = _mod._validate_file_path\ndetect_project = _mod.detect_project\nload_all_instincts = _mod.load_all_instincts\nload_project_only_instincts = _mod.load_project_only_instincts\n_load_instincts_from_dir = _mod._load_instincts_from_dir\ncmd_status = _mod.cmd_status\ncmd_projects = _mod.cmd_projects\n_promote_specific = _mod._promote_specific\n_promote_auto = _mod._promote_auto\n_find_cross_project_instincts = _mod._find_cross_project_instincts\nload_registry = _mod.load_registry\n_validate_instinct_id = _mod._validate_instinct_id\n_validate_import_url = _mod._validate_import_url\n_update_registry = _mod._update_registry\n_write_registry = _mod._write_registry\n_remove_project_storage = _mod._remove_project_storage\n_confidence_bar = _mod._confidence_bar\n\n\n# ─────────────────────────────────────────────\n# Fixtures\n# ─────────────────────────────────────────────\n\nSAMPLE_INSTINCT_YAML = \"\"\"\\\n---\nid: test-instinct\ntrigger: \"when writing tests\"\nconfidence: 0.8\ndomain: testing\nscope: project\n---\n\n## Action\nAlways write tests first.\n\n## Evidence\nTDD leads to better design.\n\"\"\"\n\nSAMPLE_GLOBAL_INSTINCT_YAML = \"\"\"\\\n---\nid: global-instinct\ntrigger: \"always\"\nconfidence: 0.9\ndomain: security\nscope: global\n---\n\n## Action\nValidate all user input.\n\"\"\"\n\n\n@pytest.fixture\ndef project_tree(tmp_path):\n    \"\"\"Create a realistic project directory tree for testing.\"\"\"\n    homunculus = tmp_path / \".claude\" / \"homunculus\"\n    projects_dir = homunculus / \"projects\"\n    global_personal = homunculus / \"instincts\" / \"personal\"\n    global_inherited = homunculus / \"instincts\" / \"inherited\"\n    global_evolved = homunculus / \"evolved\"\n\n    for d in [\n        global_personal, global_inherited,\n        global_evolved / \"skills\", global_evolved / \"commands\", global_evolved / \"agents\",\n        projects_dir,\n    ]:\n        d.mkdir(parents=True, exist_ok=True)\n\n    return {\n        \"root\": tmp_path,\n        \"homunculus\": homunculus,\n        \"projects_dir\": projects_dir,\n        \"global_personal\": global_personal,\n        \"global_inherited\": global_inherited,\n        \"global_evolved\": global_evolved,\n        \"registry_file\": homunculus / \"projects.json\",\n    }\n\n\n@pytest.fixture\ndef patch_globals(project_tree, monkeypatch):\n    \"\"\"Patch module-level globals to use tmp_path-based directories.\"\"\"\n    monkeypatch.setattr(_mod, \"HOMUNCULUS_DIR\", project_tree[\"homunculus\"])\n    monkeypatch.setattr(_mod, \"PROJECTS_DIR\", project_tree[\"projects_dir\"])\n    monkeypatch.setattr(_mod, \"REGISTRY_FILE\", project_tree[\"registry_file\"])\n    monkeypatch.setattr(_mod, \"GLOBAL_PERSONAL_DIR\", project_tree[\"global_personal\"])\n    monkeypatch.setattr(_mod, \"GLOBAL_INHERITED_DIR\", project_tree[\"global_inherited\"])\n    monkeypatch.setattr(_mod, \"GLOBAL_EVOLVED_DIR\", project_tree[\"global_evolved\"])\n    monkeypatch.setattr(_mod, \"GLOBAL_OBSERVATIONS_FILE\", project_tree[\"homunculus\"] / \"observations.jsonl\")\n    return project_tree\n\n\ndef _make_project(tree, pid=\"abc123\", pname=\"test-project\"):\n    \"\"\"Create project directory structure and return a project dict.\"\"\"\n    project_dir = tree[\"projects_dir\"] / pid\n    personal_dir = project_dir / \"instincts\" / \"personal\"\n    inherited_dir = project_dir / \"instincts\" / \"inherited\"\n    for d in [personal_dir, inherited_dir,\n              project_dir / \"evolved\" / \"skills\",\n              project_dir / \"evolved\" / \"commands\",\n              project_dir / \"evolved\" / \"agents\",\n              project_dir / \"observations.archive\"]:\n        d.mkdir(parents=True, exist_ok=True)\n\n    return {\n        \"id\": pid,\n        \"name\": pname,\n        \"root\": str(tree[\"root\"] / \"fake-repo\"),\n        \"remote\": \"https://github.com/test/test-project.git\",\n        \"project_dir\": project_dir,\n        \"instincts_personal\": personal_dir,\n        \"instincts_inherited\": inherited_dir,\n        \"evolved_dir\": project_dir / \"evolved\",\n        \"observations_file\": project_dir / \"observations.jsonl\",\n    }\n\n\n# ─────────────────────────────────────────────\n# parse_instinct_file tests\n# ─────────────────────────────────────────────\n\nMULTI_SECTION = \"\"\"\\\n---\nid: instinct-a\ntrigger: \"when coding\"\nconfidence: 0.9\ndomain: general\n---\n\n## Action\nDo thing A.\n\n## Examples\n- Example A1\n\n---\nid: instinct-b\ntrigger: \"when testing\"\nconfidence: 0.7\ndomain: testing\n---\n\n## Action\nDo thing B.\n\"\"\"\n\n\ndef test_multiple_instincts_preserve_content():\n    result = parse_instinct_file(MULTI_SECTION)\n    assert len(result) == 2\n    assert \"Do thing A.\" in result[0][\"content\"]\n    assert \"Example A1\" in result[0][\"content\"]\n    assert \"Do thing B.\" in result[1][\"content\"]\n\n\ndef test_single_instinct_preserves_content():\n    content = \"\"\"\\\n---\nid: solo\ntrigger: \"when reviewing\"\nconfidence: 0.8\ndomain: review\n---\n\n## Action\nCheck for security issues.\n\n## Evidence\nPrevents vulnerabilities.\n\"\"\"\n    result = parse_instinct_file(content)\n    assert len(result) == 1\n    assert \"Check for security issues.\" in result[0][\"content\"]\n    assert \"Prevents vulnerabilities.\" in result[0][\"content\"]\n\n\ndef test_empty_content_no_error():\n    content = \"\"\"\\\n---\nid: empty\ntrigger: \"placeholder\"\nconfidence: 0.5\ndomain: general\n---\n\"\"\"\n    result = parse_instinct_file(content)\n    assert len(result) == 1\n    assert result[0][\"content\"] == \"\"\n\n\ndef test_parse_no_id_skipped():\n    \"\"\"Instincts without an 'id' field should be silently dropped.\"\"\"\n    content = \"\"\"\\\n---\ntrigger: \"when doing nothing\"\nconfidence: 0.5\n---\n\nNo id here.\n\"\"\"\n    result = parse_instinct_file(content)\n    assert len(result) == 0\n\n\ndef test_parse_confidence_is_float():\n    content = \"\"\"\\\n---\nid: float-check\ntrigger: \"when parsing\"\nconfidence: 0.42\ndomain: general\n---\n\nBody.\n\"\"\"\n    result = parse_instinct_file(content)\n    assert isinstance(result[0][\"confidence\"], float)\n    assert result[0][\"confidence\"] == pytest.approx(0.42)\n\n\ndef test_parse_trigger_strips_quotes():\n    content = \"\"\"\\\n---\nid: quote-check\ntrigger: \"when quoting\"\nconfidence: 0.5\ndomain: general\n---\n\nBody.\n\"\"\"\n    result = parse_instinct_file(content)\n    assert result[0][\"trigger\"] == \"when quoting\"\n\n\ndef test_parse_empty_string():\n    result = parse_instinct_file(\"\")\n    assert result == []\n\n\ndef test_parse_garbage_input():\n    result = parse_instinct_file(\"this is not yaml at all\\nno frontmatter here\")\n    assert result == []\n\n\n# ─────────────────────────────────────────────\n# _validate_file_path tests\n# ─────────────────────────────────────────────\n\ndef test_validate_normal_path(tmp_path):\n    test_file = tmp_path / \"test.yaml\"\n    test_file.write_text(\"hello\")\n    result = _validate_file_path(str(test_file), must_exist=True)\n    assert result == test_file.resolve()\n\n\ndef test_validate_rejects_etc():\n    with pytest.raises(ValueError, match=\"system directory\"):\n        _validate_file_path(\"/etc/passwd\")\n\n\ndef test_validate_rejects_var_log():\n    with pytest.raises(ValueError, match=\"system directory\"):\n        _validate_file_path(\"/var/log/syslog\")\n\n\ndef test_validate_rejects_usr():\n    with pytest.raises(ValueError, match=\"system directory\"):\n        _validate_file_path(\"/usr/local/bin/foo\")\n\n\ndef test_validate_rejects_proc():\n    with pytest.raises(ValueError, match=\"system directory\"):\n        _validate_file_path(\"/proc/self/status\")\n\n\ndef test_validate_must_exist_fails(tmp_path):\n    with pytest.raises(ValueError, match=\"does not exist\"):\n        _validate_file_path(str(tmp_path / \"nonexistent.yaml\"), must_exist=True)\n\n\ndef test_validate_home_expansion(tmp_path):\n    \"\"\"Tilde expansion should work.\"\"\"\n    result = _validate_file_path(\"~/test.yaml\")\n    assert str(result).startswith(str(Path.home()))\n\n\ndef test_validate_relative_path(tmp_path, monkeypatch):\n    \"\"\"Relative paths should be resolved.\"\"\"\n    monkeypatch.chdir(tmp_path)\n    test_file = tmp_path / \"rel.yaml\"\n    test_file.write_text(\"content\")\n    result = _validate_file_path(\"rel.yaml\", must_exist=True)\n    assert result == test_file.resolve()\n\n\ndef test_validate_import_url_rejects_http():\n    \"\"\"Remote imports should not downgrade to plaintext HTTP.\"\"\"\n    with pytest.raises(ValueError, match=\"require https\"):\n        _validate_import_url(\"http://example.com/instincts.yaml\")\n\n\ndef test_validate_import_url_rejects_private_hosts(monkeypatch):\n    \"\"\"Remote imports should not resolve to private or loopback addresses.\"\"\"\n    monkeypatch.setattr(\n        _mod.socket,\n        \"getaddrinfo\",\n        lambda *args, **kwargs: [(None, None, None, None, (\"127.0.0.1\", 443))],\n    )\n    with pytest.raises(ValueError, match=\"non-public address\"):\n        _validate_import_url(\"https://example.com/instincts.yaml\")\n\n\ndef test_validate_import_url_allows_public_https(monkeypatch):\n    monkeypatch.setattr(\n        _mod.socket,\n        \"getaddrinfo\",\n        lambda *args, **kwargs: [(None, None, None, None, (\"93.184.216.34\", 443))],\n    )\n    assert _validate_import_url(\"https://example.com/instincts.yaml\") == \"https://example.com/instincts.yaml\"\n\n\n# ─────────────────────────────────────────────\n# detect_project tests\n# ─────────────────────────────────────────────\n\ndef test_detect_project_global_fallback(patch_globals, monkeypatch):\n    \"\"\"When no git and no env var, should return global project.\"\"\"\n    monkeypatch.delenv(\"CLAUDE_PROJECT_DIR\", raising=False)\n\n    # Mock subprocess.run to simulate git not available\n    def mock_run(*args, **kwargs):\n        raise FileNotFoundError(\"git not found\")\n\n    monkeypatch.setattr(\"subprocess.run\", mock_run)\n\n    project = detect_project()\n    assert project[\"id\"] == \"global\"\n    assert project[\"name\"] == \"global\"\n\n\ndef test_detect_project_from_env(patch_globals, monkeypatch, tmp_path):\n    \"\"\"CLAUDE_PROJECT_DIR env var should be used as project root.\"\"\"\n    fake_repo = tmp_path / \"my-repo\"\n    fake_repo.mkdir()\n    monkeypatch.setenv(\"CLAUDE_PROJECT_DIR\", str(fake_repo))\n\n    # Mock git remote to return a URL\n    def mock_run(cmd, **kwargs):\n        if \"rev-parse\" in cmd:\n            return SimpleNamespace(returncode=0, stdout=str(fake_repo) + \"\\n\", stderr=\"\")\n        if \"get-url\" in cmd:\n            return SimpleNamespace(returncode=0, stdout=\"https://github.com/test/my-repo.git\\n\", stderr=\"\")\n        return SimpleNamespace(returncode=1, stdout=\"\", stderr=\"\")\n\n    monkeypatch.setattr(\"subprocess.run\", mock_run)\n\n    project = detect_project()\n    assert project[\"id\"] != \"global\"\n    assert project[\"name\"] == \"my-repo\"\n\n\ndef test_detect_project_git_timeout(patch_globals, monkeypatch):\n    \"\"\"Git timeout should fall through to global.\"\"\"\n    monkeypatch.delenv(\"CLAUDE_PROJECT_DIR\", raising=False)\n    import subprocess as sp\n\n    def mock_run(cmd, **kwargs):\n        raise sp.TimeoutExpired(cmd, 5)\n\n    monkeypatch.setattr(\"subprocess.run\", mock_run)\n\n    project = detect_project()\n    assert project[\"id\"] == \"global\"\n\n\ndef test_detect_project_creates_directories(patch_globals, monkeypatch, tmp_path):\n    \"\"\"detect_project should create the project dir structure.\"\"\"\n    fake_repo = tmp_path / \"structured-repo\"\n    fake_repo.mkdir()\n    monkeypatch.setenv(\"CLAUDE_PROJECT_DIR\", str(fake_repo))\n\n    def mock_run(cmd, **kwargs):\n        if \"rev-parse\" in cmd:\n            return SimpleNamespace(returncode=0, stdout=str(fake_repo) + \"\\n\", stderr=\"\")\n        if \"get-url\" in cmd:\n            return SimpleNamespace(returncode=1, stdout=\"\", stderr=\"no remote\")\n        return SimpleNamespace(returncode=1, stdout=\"\", stderr=\"\")\n\n    monkeypatch.setattr(\"subprocess.run\", mock_run)\n\n    project = detect_project()\n    assert project[\"instincts_personal\"].exists()\n    assert project[\"instincts_inherited\"].exists()\n    assert (project[\"evolved_dir\"] / \"skills\").exists()\n\n\n# ─────────────────────────────────────────────\n# _load_instincts_from_dir tests\n# ─────────────────────────────────────────────\n\ndef test_load_from_empty_dir(tmp_path):\n    result = _load_instincts_from_dir(tmp_path, \"personal\", \"project\")\n    assert result == []\n\n\ndef test_load_from_nonexistent_dir(tmp_path):\n    result = _load_instincts_from_dir(tmp_path / \"does-not-exist\", \"personal\", \"project\")\n    assert result == []\n\n\ndef test_load_annotates_metadata(tmp_path):\n    \"\"\"Loaded instincts should have _source_file, _source_type, _scope_label.\"\"\"\n    yaml_file = tmp_path / \"test.yaml\"\n    yaml_file.write_text(SAMPLE_INSTINCT_YAML)\n\n    result = _load_instincts_from_dir(tmp_path, \"personal\", \"project\")\n    assert len(result) == 1\n    assert result[0][\"_source_file\"] == str(yaml_file)\n    assert result[0][\"_source_type\"] == \"personal\"\n    assert result[0][\"_scope_label\"] == \"project\"\n\n\ndef test_load_defaults_scope_from_label(tmp_path):\n    \"\"\"If an instinct has no 'scope' in frontmatter, it should default to scope_label.\"\"\"\n    no_scope_yaml = \"\"\"\\\n---\nid: no-scope\ntrigger: \"test\"\nconfidence: 0.5\ndomain: general\n---\n\nBody.\n\"\"\"\n    (tmp_path / \"no-scope.yaml\").write_text(no_scope_yaml)\n    result = _load_instincts_from_dir(tmp_path, \"inherited\", \"global\")\n    assert result[0][\"scope\"] == \"global\"\n\n\ndef test_load_preserves_explicit_scope(tmp_path):\n    \"\"\"If frontmatter has explicit scope, it should be preserved.\"\"\"\n    yaml_file = tmp_path / \"test.yaml\"\n    yaml_file.write_text(SAMPLE_INSTINCT_YAML)\n\n    result = _load_instincts_from_dir(tmp_path, \"personal\", \"global\")\n    # Frontmatter says scope: project, scope_label is global\n    # The explicit scope should be preserved (not overwritten)\n    assert result[0][\"scope\"] == \"project\"\n\n\ndef test_load_handles_corrupt_file(tmp_path, capsys):\n    \"\"\"Corrupt YAML files should be warned about but not crash.\"\"\"\n    # A file that will cause parse_instinct_file to return empty\n    (tmp_path / \"good.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n    (tmp_path / \"bad.yaml\").write_text(\"not yaml\\nno frontmatter\")\n\n    result = _load_instincts_from_dir(tmp_path, \"personal\", \"project\")\n    # bad.yaml has no valid instincts (no id), so only good.yaml contributes\n    assert len(result) == 1\n    assert result[0][\"id\"] == \"test-instinct\"\n\n\ndef test_load_supports_yml_extension(tmp_path):\n    yml_file = tmp_path / \"test.yml\"\n    yml_file.write_text(SAMPLE_INSTINCT_YAML)\n\n    result = _load_instincts_from_dir(tmp_path, \"personal\", \"project\")\n    ids = {i[\"id\"] for i in result}\n    assert \"test-instinct\" in ids\n\n\ndef test_load_supports_md_extension(tmp_path):\n    md_file = tmp_path / \"legacy-instinct.md\"\n    md_file.write_text(SAMPLE_INSTINCT_YAML)\n\n    result = _load_instincts_from_dir(tmp_path, \"personal\", \"project\")\n    ids = {i[\"id\"] for i in result}\n    assert \"test-instinct\" in ids\n\n\ndef test_load_instincts_from_dir_uses_utf8_encoding(tmp_path, monkeypatch):\n    yaml_file = tmp_path / \"test.yaml\"\n    yaml_file.write_text(\"placeholder\")\n    calls = []\n\n    def fake_read_text(self, *args, **kwargs):\n        calls.append(kwargs.get(\"encoding\"))\n        return SAMPLE_INSTINCT_YAML\n\n    monkeypatch.setattr(Path, \"read_text\", fake_read_text)\n    result = _load_instincts_from_dir(tmp_path, \"personal\", \"project\")\n    assert result[0][\"id\"] == \"test-instinct\"\n    assert calls == [\"utf-8\"]\n\n\n# ─────────────────────────────────────────────\n# load_all_instincts tests\n# ─────────────────────────────────────────────\n\ndef test_load_all_project_and_global(patch_globals):\n    \"\"\"Should load from both project and global directories.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n\n    # Write a project instinct\n    (project[\"instincts_personal\"] / \"proj.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n    # Write a global instinct\n    (tree[\"global_personal\"] / \"glob.yaml\").write_text(SAMPLE_GLOBAL_INSTINCT_YAML)\n\n    result = load_all_instincts(project)\n    ids = {i[\"id\"] for i in result}\n    assert \"test-instinct\" in ids\n    assert \"global-instinct\" in ids\n\n\ndef test_load_all_project_overrides_global(patch_globals):\n    \"\"\"When project and global have same ID, project wins.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n\n    # Same ID but different confidence\n    proj_yaml = SAMPLE_INSTINCT_YAML.replace(\"id: test-instinct\", \"id: shared-id\")\n    proj_yaml = proj_yaml.replace(\"confidence: 0.8\", \"confidence: 0.9\")\n    glob_yaml = SAMPLE_GLOBAL_INSTINCT_YAML.replace(\"id: global-instinct\", \"id: shared-id\")\n    glob_yaml = glob_yaml.replace(\"confidence: 0.9\", \"confidence: 0.3\")\n\n    (project[\"instincts_personal\"] / \"shared.yaml\").write_text(proj_yaml)\n    (tree[\"global_personal\"] / \"shared.yaml\").write_text(glob_yaml)\n\n    result = load_all_instincts(project)\n    shared = [i for i in result if i[\"id\"] == \"shared-id\"]\n    assert len(shared) == 1\n    assert shared[0][\"_scope_label\"] == \"project\"\n    assert shared[0][\"confidence\"] == 0.9\n\n\ndef test_load_all_global_only(patch_globals):\n    \"\"\"Global project should only load global instincts.\"\"\"\n    tree = patch_globals\n    (tree[\"global_personal\"] / \"glob.yaml\").write_text(SAMPLE_GLOBAL_INSTINCT_YAML)\n\n    global_project = {\n        \"id\": \"global\",\n        \"name\": \"global\",\n        \"root\": \"\",\n        \"project_dir\": tree[\"homunculus\"],\n        \"instincts_personal\": tree[\"global_personal\"],\n        \"instincts_inherited\": tree[\"global_inherited\"],\n        \"evolved_dir\": tree[\"global_evolved\"],\n        \"observations_file\": tree[\"homunculus\"] / \"observations.jsonl\",\n    }\n\n    result = load_all_instincts(global_project)\n    assert len(result) == 1\n    assert result[0][\"id\"] == \"global-instinct\"\n\n\ndef test_load_project_only_excludes_global(patch_globals):\n    \"\"\"load_project_only_instincts should NOT include global instincts.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n\n    (project[\"instincts_personal\"] / \"proj.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n    (tree[\"global_personal\"] / \"glob.yaml\").write_text(SAMPLE_GLOBAL_INSTINCT_YAML)\n\n    result = load_project_only_instincts(project)\n    ids = {i[\"id\"] for i in result}\n    assert \"test-instinct\" in ids\n    assert \"global-instinct\" not in ids\n\n\ndef test_load_project_only_global_fallback_loads_global(patch_globals):\n    \"\"\"Global fallback should return global instincts for project-only queries.\"\"\"\n    tree = patch_globals\n    (tree[\"global_personal\"] / \"glob.yaml\").write_text(SAMPLE_GLOBAL_INSTINCT_YAML)\n\n    global_project = {\n        \"id\": \"global\",\n        \"name\": \"global\",\n        \"root\": \"\",\n        \"project_dir\": tree[\"homunculus\"],\n        \"instincts_personal\": tree[\"global_personal\"],\n        \"instincts_inherited\": tree[\"global_inherited\"],\n        \"evolved_dir\": tree[\"global_evolved\"],\n        \"observations_file\": tree[\"homunculus\"] / \"observations.jsonl\",\n    }\n\n    result = load_project_only_instincts(global_project)\n    assert len(result) == 1\n    assert result[0][\"id\"] == \"global-instinct\"\n\n\ndef test_load_all_empty(patch_globals):\n    \"\"\"No instincts at all should return empty list.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n\n    result = load_all_instincts(project)\n    assert result == []\n\n\n# ─────────────────────────────────────────────\n# cmd_status tests\n# ─────────────────────────────────────────────\n\ndef test_cmd_status_no_instincts(patch_globals, monkeypatch, capsys):\n    \"\"\"Status with no instincts should print fallback message.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n    monkeypatch.setattr(_mod, \"detect_project\", lambda: project)\n\n    args = SimpleNamespace()\n    ret = cmd_status(args)\n    assert ret == 0\n    out = capsys.readouterr().out\n    assert \"No instincts found.\" in out\n\n\ndef test_cmd_status_with_instincts(patch_globals, monkeypatch, capsys):\n    \"\"\"Status should show project and global instinct counts.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n    monkeypatch.setattr(_mod, \"detect_project\", lambda: project)\n\n    (project[\"instincts_personal\"] / \"proj.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n    (tree[\"global_personal\"] / \"glob.yaml\").write_text(SAMPLE_GLOBAL_INSTINCT_YAML)\n\n    args = SimpleNamespace()\n    ret = cmd_status(args)\n    assert ret == 0\n    out = capsys.readouterr().out\n    assert \"INSTINCT STATUS\" in out\n    assert \"Project instincts: 1\" in out\n    assert \"Global instincts:  1\" in out\n    assert \"PROJECT-SCOPED\" in out\n    assert \"GLOBAL\" in out\n\n\ndef test_confidence_bar_uses_unicode_when_supported():\n    \"\"\"Confidence bars should retain block glyphs on UTF-8 streams.\"\"\"\n    stream = SimpleNamespace(encoding=\"utf-8\")\n    assert _confidence_bar(0.8, stream=stream) == \"\\u2588\" * 8 + \"\\u2591\" * 2\n\n\ndef test_confidence_bar_uses_ascii_when_stream_rejects_block_glyphs():\n    \"\"\"Windows cp1252 streams cannot encode block glyphs.\"\"\"\n    stream = SimpleNamespace(encoding=\"cp1252\")\n    assert _confidence_bar(0.8, stream=stream) == \"########..\"\n\n\ndef test_print_instincts_by_domain_is_cp1252_safe(monkeypatch):\n    \"\"\"Status rendering should not crash on Windows cp1252 stdout.\"\"\"\n    raw = io.BytesIO()\n    stream = io.TextIOWrapper(raw, encoding=\"cp1252\")\n    monkeypatch.setattr(_mod.sys, \"stdout\", stream)\n\n    _mod._print_instincts_by_domain([{\n        \"id\": \"windows-safe\",\n        \"trigger\": \"when stdout uses cp1252\",\n        \"confidence\": 0.8,\n        \"domain\": \"platform\",\n        \"scope\": \"project\",\n    }])\n\n    stream.flush()\n    out = raw.getvalue().decode(\"cp1252\")\n    assert \"########..\" in out\n    assert \"\\u2588\" not in out\n    assert \"\\u2591\" not in out\n\n\ndef test_cmd_status_returns_int(patch_globals, monkeypatch):\n    \"\"\"cmd_status should always return an int.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n    monkeypatch.setattr(_mod, \"detect_project\", lambda: project)\n\n    args = SimpleNamespace()\n    ret = cmd_status(args)\n    assert isinstance(ret, int)\n\n\n# ─────────────────────────────────────────────\n# cmd_projects tests\n# ─────────────────────────────────────────────\n\ndef test_cmd_projects_empty_registry(patch_globals, capsys):\n    \"\"\"No projects should print helpful message.\"\"\"\n    args = SimpleNamespace()\n    ret = cmd_projects(args)\n    assert ret == 0\n    out = capsys.readouterr().out\n    assert \"No projects registered yet.\" in out\n\n\ndef test_cmd_projects_with_registry(patch_globals, capsys):\n    \"\"\"Should list projects from registry.\"\"\"\n    tree = patch_globals\n\n    # Create a project dir with instincts\n    pid = \"test123abc\"\n    project = _make_project(tree, pid=pid, pname=\"my-app\")\n    (project[\"instincts_personal\"] / \"inst.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n\n    # Write registry\n    registry = {\n        pid: {\n            \"name\": \"my-app\",\n            \"root\": \"/home/user/my-app\",\n            \"remote\": \"https://github.com/user/my-app.git\",\n            \"last_seen\": \"2025-01-15T12:00:00Z\",\n        }\n    }\n    tree[\"registry_file\"].write_text(json.dumps(registry))\n\n    args = SimpleNamespace()\n    ret = cmd_projects(args)\n    assert ret == 0\n    out = capsys.readouterr().out\n    assert \"my-app\" in out\n    assert pid in out\n    assert \"1 personal\" in out\n\n\n# ─────────────────────────────────────────────\n# _promote_specific tests\n# ─────────────────────────────────────────────\n\ndef test_promote_specific_not_found(patch_globals, capsys):\n    \"\"\"Promoting nonexistent instinct should fail.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n\n    ret = _promote_specific(project, \"nonexistent\", force=True)\n    assert ret == 1\n    out = capsys.readouterr().out\n    assert \"not found\" in out\n\n\ndef test_promote_specific_rejects_invalid_id(patch_globals, capsys):\n    \"\"\"Path-like instinct IDs should be rejected before file writes.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n\n    ret = _promote_specific(project, \"../escape\", force=True)\n    assert ret == 1\n    err = capsys.readouterr().err\n    assert \"Invalid instinct ID\" in err\n\n\ndef test_promote_specific_already_global(patch_globals, capsys):\n    \"\"\"Promoting an instinct that already exists globally should fail.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n\n    # Write same-id instinct in both project and global\n    (project[\"instincts_personal\"] / \"shared.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n    global_yaml = SAMPLE_INSTINCT_YAML  # same id: test-instinct\n    (tree[\"global_personal\"] / \"shared.yaml\").write_text(global_yaml)\n\n    ret = _promote_specific(project, \"test-instinct\", force=True)\n    assert ret == 1\n    out = capsys.readouterr().out\n    assert \"already exists in global\" in out\n\n\ndef test_promote_specific_success(patch_globals, capsys):\n    \"\"\"Promote a project instinct to global with --force.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n\n    (project[\"instincts_personal\"] / \"inst.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n\n    ret = _promote_specific(project, \"test-instinct\", force=True)\n    assert ret == 0\n    out = capsys.readouterr().out\n    assert \"Promoted\" in out\n\n    # Verify file was created in global dir\n    promoted_file = tree[\"global_personal\"] / \"test-instinct.yaml\"\n    assert promoted_file.exists()\n    content = promoted_file.read_text()\n    assert \"scope: global\" in content\n    assert \"promoted_from: abc123\" in content\n\n\n# ─────────────────────────────────────────────\n# _promote_auto tests\n# ─────────────────────────────────────────────\n\ndef test_promote_auto_no_candidates(patch_globals, capsys):\n    \"\"\"Auto-promote with no cross-project instincts should say so.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n\n    # Empty registry\n    tree[\"registry_file\"].write_text(\"{}\")\n\n    ret = _promote_auto(project, force=True, dry_run=False)\n    assert ret == 0\n    out = capsys.readouterr().out\n    assert \"No instincts qualify\" in out\n\n\ndef test_promote_auto_dry_run(patch_globals, capsys):\n    \"\"\"Dry run should list candidates but not write files.\"\"\"\n    tree = patch_globals\n\n    # Create two projects with the same high-confidence instinct\n    p1 = _make_project(tree, pid=\"proj1\", pname=\"project-one\")\n    p2 = _make_project(tree, pid=\"proj2\", pname=\"project-two\")\n\n    high_conf_yaml = \"\"\"\\\n---\nid: cross-project-instinct\ntrigger: \"when reviewing\"\nconfidence: 0.95\ndomain: security\nscope: project\n---\n\n## Action\nAlways review for injection.\n\"\"\"\n    (p1[\"instincts_personal\"] / \"cross.yaml\").write_text(high_conf_yaml)\n    (p2[\"instincts_personal\"] / \"cross.yaml\").write_text(high_conf_yaml)\n\n    # Write registry\n    registry = {\n        \"proj1\": {\"name\": \"project-one\", \"root\": \"/a\", \"remote\": \"\", \"last_seen\": \"2025-01-01T00:00:00Z\"},\n        \"proj2\": {\"name\": \"project-two\", \"root\": \"/b\", \"remote\": \"\", \"last_seen\": \"2025-01-01T00:00:00Z\"},\n    }\n    tree[\"registry_file\"].write_text(json.dumps(registry))\n\n    project = p1\n    ret = _promote_auto(project, force=True, dry_run=True)\n    assert ret == 0\n    out = capsys.readouterr().out\n    assert \"DRY RUN\" in out\n    assert \"cross-project-instinct\" in out\n\n    # Verify no file was created\n    assert not (tree[\"global_personal\"] / \"cross-project-instinct.yaml\").exists()\n\n\ndef test_promote_auto_writes_file(patch_globals, capsys):\n    \"\"\"Auto-promote with force should write global instinct file.\"\"\"\n    tree = patch_globals\n\n    p1 = _make_project(tree, pid=\"proj1\", pname=\"project-one\")\n    p2 = _make_project(tree, pid=\"proj2\", pname=\"project-two\")\n\n    high_conf_yaml = \"\"\"\\\n---\nid: universal-pattern\ntrigger: \"when coding\"\nconfidence: 0.85\ndomain: general\nscope: project\n---\n\n## Action\nUse descriptive variable names.\n\"\"\"\n    (p1[\"instincts_personal\"] / \"uni.yaml\").write_text(high_conf_yaml)\n    (p2[\"instincts_personal\"] / \"uni.yaml\").write_text(high_conf_yaml)\n\n    registry = {\n        \"proj1\": {\"name\": \"project-one\", \"root\": \"/a\", \"remote\": \"\", \"last_seen\": \"2025-01-01T00:00:00Z\"},\n        \"proj2\": {\"name\": \"project-two\", \"root\": \"/b\", \"remote\": \"\", \"last_seen\": \"2025-01-01T00:00:00Z\"},\n    }\n    tree[\"registry_file\"].write_text(json.dumps(registry))\n\n    ret = _promote_auto(p1, force=True, dry_run=False)\n    assert ret == 0\n\n    promoted = tree[\"global_personal\"] / \"universal-pattern.yaml\"\n    assert promoted.exists()\n    content = promoted.read_text()\n    assert \"scope: global\" in content\n    assert \"auto-promoted\" in content\n\n\ndef test_promote_auto_skips_invalid_id(patch_globals, capsys):\n    tree = patch_globals\n\n    p1 = _make_project(tree, pid=\"proj1\", pname=\"project-one\")\n    p2 = _make_project(tree, pid=\"proj2\", pname=\"project-two\")\n\n    bad_id_yaml = \"\"\"\\\n---\nid: ../escape\ntrigger: \"when coding\"\nconfidence: 0.9\ndomain: general\nscope: project\n---\n\n## Action\nInvalid id should be skipped.\n\"\"\"\n    (p1[\"instincts_personal\"] / \"bad.yaml\").write_text(bad_id_yaml)\n    (p2[\"instincts_personal\"] / \"bad.yaml\").write_text(bad_id_yaml)\n\n    registry = {\n        \"proj1\": {\"name\": \"project-one\", \"root\": \"/a\", \"remote\": \"\", \"last_seen\": \"2025-01-01T00:00:00Z\"},\n        \"proj2\": {\"name\": \"project-two\", \"root\": \"/b\", \"remote\": \"\", \"last_seen\": \"2025-01-01T00:00:00Z\"},\n    }\n    tree[\"registry_file\"].write_text(json.dumps(registry))\n\n    ret = _promote_auto(p1, force=True, dry_run=False)\n    assert ret == 0\n    err = capsys.readouterr().err\n    assert \"Skipping invalid instinct ID\" in err\n    assert not (tree[\"global_personal\"] / \"../escape.yaml\").exists()\n\n\n# ─────────────────────────────────────────────\n# _find_cross_project_instincts tests\n# ─────────────────────────────────────────────\n\ndef test_find_cross_project_empty_registry(patch_globals):\n    tree = patch_globals\n    tree[\"registry_file\"].write_text(\"{}\")\n    result = _find_cross_project_instincts()\n    assert result == {}\n\n\ndef test_find_cross_project_single_project(patch_globals):\n    \"\"\"Single project should return nothing (need 2+).\"\"\"\n    tree = patch_globals\n    p1 = _make_project(tree, pid=\"proj1\", pname=\"project-one\")\n    (p1[\"instincts_personal\"] / \"inst.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n\n    registry = {\"proj1\": {\"name\": \"project-one\", \"root\": \"/a\", \"remote\": \"\", \"last_seen\": \"2025-01-01T00:00:00Z\"}}\n    tree[\"registry_file\"].write_text(json.dumps(registry))\n\n    result = _find_cross_project_instincts()\n    assert result == {}\n\n\ndef test_find_cross_project_shared_instinct(patch_globals):\n    \"\"\"Same instinct ID in 2 projects should be found.\"\"\"\n    tree = patch_globals\n    p1 = _make_project(tree, pid=\"proj1\", pname=\"project-one\")\n    p2 = _make_project(tree, pid=\"proj2\", pname=\"project-two\")\n\n    (p1[\"instincts_personal\"] / \"shared.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n    (p2[\"instincts_personal\"] / \"shared.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n\n    registry = {\n        \"proj1\": {\"name\": \"project-one\", \"root\": \"/a\", \"remote\": \"\", \"last_seen\": \"2025-01-01T00:00:00Z\"},\n        \"proj2\": {\"name\": \"project-two\", \"root\": \"/b\", \"remote\": \"\", \"last_seen\": \"2025-01-01T00:00:00Z\"},\n    }\n    tree[\"registry_file\"].write_text(json.dumps(registry))\n\n    result = _find_cross_project_instincts()\n    assert \"test-instinct\" in result\n    assert len(result[\"test-instinct\"]) == 2\n\n\n# ─────────────────────────────────────────────\n# load_registry tests\n# ─────────────────────────────────────────────\n\ndef test_load_registry_missing_file(patch_globals):\n    result = load_registry()\n    assert result == {}\n\n\ndef test_load_registry_corrupt_json(patch_globals):\n    tree = patch_globals\n    tree[\"registry_file\"].write_text(\"not json at all {{{\")\n    result = load_registry()\n    assert result == {}\n\n\ndef test_load_registry_valid(patch_globals):\n    tree = patch_globals\n    data = {\"abc\": {\"name\": \"test\", \"root\": \"/test\"}}\n    tree[\"registry_file\"].write_text(json.dumps(data))\n    result = load_registry()\n    assert result == data\n\n\ndef test_load_registry_uses_utf8_encoding(monkeypatch):\n    calls = []\n\n    def fake_open(path, mode=\"r\", *args, **kwargs):\n        calls.append(kwargs.get(\"encoding\"))\n        return io.StringIO(\"{}\")\n\n    monkeypatch.setattr(_mod, \"open\", fake_open, raising=False)\n    assert load_registry() == {}\n    assert calls == [\"utf-8\"]\n\n\ndef test_validate_instinct_id():\n    assert _validate_instinct_id(\"good-id_1.0\")\n    assert not _validate_instinct_id(\"../bad\")\n    assert not _validate_instinct_id(\"bad/name\")\n    assert not _validate_instinct_id(\".hidden\")\n\n\ndef test_update_registry_atomic_replaces_file(patch_globals):\n    tree = patch_globals\n    _update_registry(\"abc123\", \"demo\", \"/repo\", \"https://example.com/repo.git\")\n    data = json.loads(tree[\"registry_file\"].read_text())\n    assert \"abc123\" in data\n    leftovers = list(tree[\"registry_file\"].parent.glob(\".projects.json.tmp.*\"))\n    assert leftovers == []\n\n\ndef test_update_registry_matches_shell_schema(patch_globals):\n    # Issue #2299: the Python writer must emit the same field set as the shell\n    # counterpart in detect-project.sh (id, name, root, remote, created_at,\n    # last_seen) so a projects.json entry has a consistent shape regardless of\n    # which path wrote it.\n    tree = patch_globals\n    _update_registry(\"abc123\", \"demo\", \"/repo\", \"https://example.com/repo.git\")\n    entry = json.loads(tree[\"registry_file\"].read_text())[\"abc123\"]\n    assert set(entry) == {\"id\", \"name\", \"root\", \"remote\", \"created_at\", \"last_seen\"}\n    assert entry[\"id\"] == \"abc123\"\n    assert entry[\"name\"] == \"demo\"\n    assert entry[\"root\"] == \"/repo\"\n    assert entry[\"remote\"] == \"https://example.com/repo.git\"\n    # On the initial write both timestamps come from the same `now`, so the\n    # first-write contract is created_at == last_seen.\n    assert entry[\"created_at\"]\n    assert entry[\"created_at\"] == entry[\"last_seen\"]\n\n\ndef test_update_registry_preserves_created_at(patch_globals):\n    # created_at is stamped on first write and preserved on subsequent updates,\n    # while last_seen advances — matching entry.get(\"created_at\", now) in the\n    # shell counterpart.\n    tree = patch_globals\n    _update_registry(\"abc123\", \"demo\", \"/repo\", \"https://example.com/repo.git\")\n    first = json.loads(tree[\"registry_file\"].read_text())[\"abc123\"]\n\n    _update_registry(\"abc123\", \"demo-renamed\", \"/repo\", \"https://example.com/repo.git\")\n    second = json.loads(tree[\"registry_file\"].read_text())[\"abc123\"]\n\n    assert second[\"created_at\"] == first[\"created_at\"]\n    assert second[\"name\"] == \"demo-renamed\"\n    assert second[\"last_seen\"] >= first[\"last_seen\"]\n\n\ndef test_update_registry_heals_malformed_entry(patch_globals):\n    # Issue #2299 follow-up: a non-dict value for the project id (e.g. a\n    # corrupt registry) must not crash _update_registry. The entry is healed by\n    # the rewrite, preserving the old unconditional-overwrite behavior.\n    tree = patch_globals\n    tree[\"registry_file\"].write_text(json.dumps({\"abc123\": None}), encoding=\"utf-8\")\n    _update_registry(\"abc123\", \"demo\", \"/repo\", \"https://example.com/repo.git\")\n    entry = json.loads(tree[\"registry_file\"].read_text())[\"abc123\"]\n    assert isinstance(entry, dict)\n    assert entry[\"id\"] == \"abc123\"\n    assert entry[\"created_at\"]\n    assert entry[\"created_at\"] == entry[\"last_seen\"]\n\n\ndef test_update_registry_heals_non_dict_registry(patch_globals):\n    # Issue #2299 follow-up: a top-level registry that is valid JSON but not a\n    # mapping (e.g. a list or string from a corrupt projects.json) must not\n    # crash _update_registry before the per-entry guard runs. The whole file is\n    # healed by the rewrite, preserving the old unconditional-overwrite behavior.\n    tree = patch_globals\n    tree[\"registry_file\"].write_text(json.dumps([\"oops\"]), encoding=\"utf-8\")\n    _update_registry(\"abc123\", \"demo\", \"/repo\", \"https://example.com/repo.git\")\n    registry = json.loads(tree[\"registry_file\"].read_text())\n    assert isinstance(registry, dict)\n    entry = registry[\"abc123\"]\n    assert entry[\"id\"] == \"abc123\"\n    assert entry[\"created_at\"] == entry[\"last_seen\"]\n\n\ndef test_write_registry_atomic_no_tmp_leftovers(patch_globals):\n    # Issue #2294: _write_registry now holds the registry lock like\n    # _update_registry. It must still write atomically with no stray tmp files.\n    tree = patch_globals\n    _write_registry({\"keep\": {\"name\": \"demo\", \"root\": \"/repo\", \"remote\": \"\"}})\n    data = json.loads(tree[\"registry_file\"].read_text())\n    assert data == {\"keep\": {\"name\": \"demo\", \"root\": \"/repo\", \"remote\": \"\"}}\n    leftovers = list(tree[\"registry_file\"].parent.glob(\".projects.json.tmp.*\"))\n    assert leftovers == []\n\n\ndef test_remove_project_storage_deletes_contained_dir(patch_globals):\n    tree = patch_globals\n    target = tree[\"projects_dir\"] / \"proj-1\"\n    (target / \"instincts\").mkdir(parents=True)\n    (target / \"instincts\" / \"x.md\").write_text(\"hi\", encoding=\"utf-8\")\n    _remove_project_storage(\"proj-1\")\n    assert not target.exists()\n\n\ndef test_remove_project_storage_missing_dir_is_noop(patch_globals):\n    # No raise when the contained dir simply does not exist.\n    _remove_project_storage(\"never-created\")\n\n\ndef test_remove_project_storage_blocks_traversal(patch_globals):\n    # Issue #2297: defense-in-depth — a traversal id must be refused even when a\n    # caller skips _validate_project_id, so this can never delete outside\n    # PROJECTS_DIR.\n    with pytest.raises(ValueError):\n        _remove_project_storage(\"../../etc\")\n\n\ndef test_remove_project_storage_blocks_root_itself(patch_globals):\n    with pytest.raises(ValueError):\n        _remove_project_storage(\".\")\n\n\n# ─────────────────────────────────────────────\n# Issue #2302 coverage:\n#   _normalize_remote_url, _promote_specific dry-run,\n#   projects delete/gc/merge, cmd_prune\n# ─────────────────────────────────────────────\n\n_normalize_remote_url = _mod._normalize_remote_url\n_cmd_projects_delete = _mod._cmd_projects_delete\n_cmd_projects_gc = _mod._cmd_projects_gc\n_cmd_projects_merge = _mod._cmd_projects_merge\ncmd_prune = _mod.cmd_prune\n\n\n# ── _normalize_remote_url ────────────────────\n\ndef test_normalize_remote_url_empty_returns_empty():\n    assert _normalize_remote_url(\"\") == \"\"\n    assert _normalize_remote_url(None) == \"\"\n\n\ndef test_normalize_remote_url_scp_form():\n    # scp-style host:path -> host/path, credentials/.git stripped, lowercased\n    assert _normalize_remote_url(\"git@github.com:Test/Repo.git\") == \"github.com/test/repo\"\n\n\ndef test_normalize_remote_url_https_strips_credentials_and_scheme():\n    assert (\n        _normalize_remote_url(\"https://user:token@github.com/test/repo.git\")\n        == \"github.com/test/repo\"\n    )\n\n\ndef test_normalize_remote_url_network_is_lowercased():\n    assert _normalize_remote_url(\"https://GitHub.com/Owner/Project\") == \"github.com/owner/project\"\n\n\ndef test_normalize_remote_url_trailing_slash_and_dotgit_stripped():\n    assert _normalize_remote_url(\"https://github.com/a/b.git/\") == \"github.com/a/b\"\n\n\ndef test_normalize_remote_url_file_scheme_preserves_case():\n    # Local file paths are not network URLs: scheme is stripped but case is preserved.\n    assert _normalize_remote_url(\"file:///srv/Repos/My-Repo/\") == \"/srv/Repos/My-Repo\"\n\n\ndef test_normalize_remote_url_idempotent():\n    once = _normalize_remote_url(\"https://user@github.com/Test/Repo.git\")\n    assert _normalize_remote_url(once) == once\n\n\n# ── _promote_specific dry-run ────────────────\n\ndef test_promote_specific_dry_run_writes_nothing(patch_globals, capsys):\n    \"\"\"dry_run returns 0, prints [DRY RUN], and writes no global file.\"\"\"\n    tree = patch_globals\n    project = _make_project(tree)\n    (project[\"instincts_personal\"] / \"inst.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n\n    ret = _promote_specific(project, \"test-instinct\", force=True, dry_run=True)\n    assert ret == 0\n    out = capsys.readouterr().out\n    assert \"[DRY RUN]\" in out\n    assert not (tree[\"global_personal\"] / \"test-instinct.yaml\").exists()\n    assert list(tree[\"global_personal\"].iterdir()) == []\n\n\n# ── projects delete ──────────────────────────\n\ndef test_projects_delete_rejects_invalid_id(patch_globals, capsys):\n    args = SimpleNamespace(project_id=\"../escape\", dry_run=False, force=True)\n    assert _cmd_projects_delete(args) == 1\n    assert \"Invalid project ID\" in capsys.readouterr().err\n\n\ndef test_projects_delete_not_found(patch_globals, capsys):\n    args = SimpleNamespace(project_id=\"ghost123\", dry_run=False, force=True)\n    assert _cmd_projects_delete(args) == 1\n    assert \"not found\" in capsys.readouterr().err\n\n\ndef test_projects_delete_dry_run_keeps_registry_and_storage(patch_globals, capsys):\n    tree = patch_globals\n    _make_project(tree, pid=\"proj1\", pname=\"p1\")\n    tree[\"registry_file\"].write_text(json.dumps({\"proj1\": {\"name\": \"p1\"}}))\n\n    args = SimpleNamespace(project_id=\"proj1\", dry_run=True, force=False)\n    assert _cmd_projects_delete(args) == 0\n    assert \"[DRY RUN]\" in capsys.readouterr().out\n    assert (tree[\"projects_dir\"] / \"proj1\").exists()\n    assert \"proj1\" in json.loads(tree[\"registry_file\"].read_text())\n\n\ndef test_projects_delete_force_removes_registry_and_storage(patch_globals, capsys):\n    tree = patch_globals\n    _make_project(tree, pid=\"proj1\", pname=\"p1\")\n    tree[\"registry_file\"].write_text(json.dumps({\"proj1\": {\"name\": \"p1\"}}))\n\n    args = SimpleNamespace(project_id=\"proj1\", dry_run=False, force=True)\n    assert _cmd_projects_delete(args) == 0\n    assert \"Deleted project\" in capsys.readouterr().out\n    assert not (tree[\"projects_dir\"] / \"proj1\").exists()\n    assert \"proj1\" not in json.loads(tree[\"registry_file\"].read_text())\n\n\n# ── projects gc ──────────────────────────────\n\ndef test_projects_gc_no_candidates(patch_globals, capsys):\n    tree = patch_globals\n    tree[\"registry_file\"].write_text(\"{}\")\n    args = SimpleNamespace(dry_run=False, force=True)\n    assert _cmd_projects_gc(args) == 0\n    assert \"No zero-value project entries\" in capsys.readouterr().out\n\n\ndef test_projects_gc_dry_run_keeps_entry(patch_globals, capsys):\n    tree = patch_globals\n    _make_project(tree, pid=\"empty1\", pname=\"e1\")  # zero instincts/observations\n    tree[\"registry_file\"].write_text(json.dumps({\"empty1\": {\"name\": \"e1\"}}))\n\n    args = SimpleNamespace(dry_run=True, force=False)\n    assert _cmd_projects_gc(args) == 0\n    assert \"[DRY RUN]\" in capsys.readouterr().out\n    assert \"empty1\" in json.loads(tree[\"registry_file\"].read_text())\n    # dry-run must not touch storage on disk\n    assert (tree[\"projects_dir\"] / \"empty1\").exists()\n\n\ndef test_projects_gc_force_removes_only_zero_value(patch_globals, capsys):\n    tree = patch_globals\n    _make_project(tree, pid=\"empty1\", pname=\"e1\")\n    full = _make_project(tree, pid=\"full1\", pname=\"f1\")\n    (full[\"instincts_personal\"] / \"inst.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n    tree[\"registry_file\"].write_text(\n        json.dumps({\"empty1\": {\"name\": \"e1\"}, \"full1\": {\"name\": \"f1\"}})\n    )\n\n    args = SimpleNamespace(dry_run=False, force=True)\n    assert _cmd_projects_gc(args) == 0\n    reg = json.loads(tree[\"registry_file\"].read_text())\n    assert \"empty1\" not in reg\n    assert \"full1\" in reg\n    assert not (tree[\"projects_dir\"] / \"empty1\").exists()\n    assert (tree[\"projects_dir\"] / \"full1\").exists()\n\n\n# ── projects merge ───────────────────────────\n\ndef test_projects_merge_rejects_same_id(patch_globals, capsys):\n    args = SimpleNamespace(from_id=\"dup\", into_id=\"dup\", dry_run=False, force=True)\n    assert _cmd_projects_merge(args) == 1\n    assert \"into itself\" in capsys.readouterr().err\n\n\ndef test_projects_merge_missing_source(patch_globals, capsys):\n    tree = patch_globals\n    tree[\"registry_file\"].write_text(json.dumps({\"dest\": {\"name\": \"d\"}}))\n    args = SimpleNamespace(from_id=\"src\", into_id=\"dest\", dry_run=False, force=True)\n    assert _cmd_projects_merge(args) == 1\n    assert \"Source project\" in capsys.readouterr().err\n\n\ndef test_projects_merge_missing_destination(patch_globals, capsys):\n    tree = patch_globals\n    # Source present, destination absent — exercises the symmetric error branch.\n    tree[\"registry_file\"].write_text(json.dumps({\"src\": {\"name\": \"s\"}}))\n    args = SimpleNamespace(from_id=\"src\", into_id=\"dest\", dry_run=False, force=True)\n    assert _cmd_projects_merge(args) == 1\n    assert \"Destination project\" in capsys.readouterr().err\n\n\ndef test_projects_merge_dry_run_no_changes(patch_globals, capsys):\n    tree = patch_globals\n    src = _make_project(tree, pid=\"src\", pname=\"s\")\n    _make_project(tree, pid=\"dest\", pname=\"d\")\n    (src[\"instincts_personal\"] / \"i.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n    tree[\"registry_file\"].write_text(json.dumps({\"src\": {\"name\": \"s\"}, \"dest\": {\"name\": \"d\"}}))\n\n    args = SimpleNamespace(from_id=\"src\", into_id=\"dest\", dry_run=True, force=False)\n    assert _cmd_projects_merge(args) == 0\n    assert \"[DRY RUN]\" in capsys.readouterr().out\n    reg = json.loads(tree[\"registry_file\"].read_text())\n    assert \"src\" in reg and \"dest\" in reg\n    assert (tree[\"projects_dir\"] / \"src\").exists()\n    # dry-run must not copy any instinct into the destination storage\n    assert not list((tree[\"projects_dir\"] / \"dest\" / \"instincts\" / \"personal\").glob(\"*.yaml\"))\n\n\ndef test_projects_merge_force_moves_and_removes_source(patch_globals, capsys):\n    tree = patch_globals\n    src = _make_project(tree, pid=\"src\", pname=\"s\")\n    _make_project(tree, pid=\"dest\", pname=\"d\")\n    (src[\"instincts_personal\"] / \"i.yaml\").write_text(SAMPLE_INSTINCT_YAML)\n    tree[\"registry_file\"].write_text(json.dumps({\"src\": {\"name\": \"s\"}, \"dest\": {\"name\": \"d\"}}))\n\n    args = SimpleNamespace(from_id=\"src\", into_id=\"dest\", dry_run=False, force=True)\n    assert _cmd_projects_merge(args) == 0\n    reg = json.loads(tree[\"registry_file\"].read_text())\n    assert \"src\" not in reg\n    assert \"dest\" in reg\n    assert not (tree[\"projects_dir\"] / \"src\").exists()\n    moved = list((tree[\"projects_dir\"] / \"dest\" / \"instincts\" / \"personal\").glob(\"*.yaml\"))\n    assert len(moved) >= 1\n\n\n# ── cmd_prune ────────────────────────────────\n\ndef _pending_item(path, age_days):\n    return {\n        \"path\": path,\n        \"created\": None,\n        \"age_days\": age_days,\n        \"name\": path.stem,\n        \"parent_dir\": str(path.parent),\n    }\n\n\ndef test_cmd_prune_dry_run_keeps_files(monkeypatch, tmp_path, capsys):\n    f_old = tmp_path / \"old.yaml\"\n    f_old.write_text(\"x\", encoding=\"utf-8\")\n    f_new = tmp_path / \"new.yaml\"\n    f_new.write_text(\"y\", encoding=\"utf-8\")\n    items = [_pending_item(f_old, 40), _pending_item(f_new, 5)]\n    monkeypatch.setattr(_mod, \"_collect_pending_instincts\", lambda: items)\n\n    args = SimpleNamespace(max_age=30, dry_run=True, quiet=False)\n    assert cmd_prune(args) == 0\n    assert \"[DRY RUN]\" in capsys.readouterr().out\n    assert f_old.exists()\n    assert f_new.exists()\n\n\ndef test_cmd_prune_deletes_only_expired(monkeypatch, tmp_path, capsys):\n    f_old = tmp_path / \"old.yaml\"\n    f_old.write_text(\"x\", encoding=\"utf-8\")\n    f_new = tmp_path / \"new.yaml\"\n    f_new.write_text(\"y\", encoding=\"utf-8\")\n    items = [_pending_item(f_old, 40), _pending_item(f_new, 5)]\n    monkeypatch.setattr(_mod, \"_collect_pending_instincts\", lambda: items)\n\n    args = SimpleNamespace(max_age=30, dry_run=False, quiet=False)\n    assert cmd_prune(args) == 0\n    assert not f_old.exists()\n    assert f_new.exists()\n    assert \"Pruned 1\" in capsys.readouterr().out\n\n\ndef test_cmd_prune_quiet_suppresses_output(monkeypatch, tmp_path, capsys):\n    f_old = tmp_path / \"old.yaml\"\n    f_old.write_text(\"x\", encoding=\"utf-8\")\n    items = [_pending_item(f_old, 99)]\n    monkeypatch.setattr(_mod, \"_collect_pending_instincts\", lambda: items)\n\n    args = SimpleNamespace(max_age=30, dry_run=False, quiet=True)\n    assert cmd_prune(args) == 0\n    assert not f_old.exists()\n    captured = capsys.readouterr()\n    assert captured.out == \"\"\n    assert captured.err == \"\"\n\n\ndef test_cmd_prune_empty_pending_nothing_to_do(monkeypatch, capsys):\n    # Nothing pending at all: the non-dry-run, non-quiet branch must report\n    # \"nothing to do\" (not \"[DRY RUN]\"), return 0, and not crash.\n    monkeypatch.setattr(_mod, \"_collect_pending_instincts\", lambda: [])\n\n    args = SimpleNamespace(max_age=30, dry_run=False, quiet=False)\n    assert cmd_prune(args) == 0\n    out = capsys.readouterr().out\n    assert \"No pending instincts older than 30 days.\" in out\n    assert \"[DRY RUN]\" not in out\n"},{"path":"SKILL.md","text":"---\nname: continuous-learning-v2\ndescription: Instinct-based learning system that observes sessions via hooks, creates atomic instincts with confidence scoring, and evolves them into skills/commands/agents. v2.1 adds project-scoped instincts to prevent cross-project contamination.\nmetadata:\n  origin: ECC\nversion: 2.1.0\n---\n\n# Continuous Learning v2.1 - Instinct\n-Based Architecture\n\nAn advanced learning system that turns your Claude Code sessions into reusable knowledge through atomic \"instincts\" - small learned behaviors with confidence scoring.\n\n**v2.1** adds **project-scoped instincts** — React patterns stay in your React project, Python conventions stay in your Python project, and universal patterns (like \"always validate input\") are shared globally.\n\n## When to Activate\n\n- Setting up automatic learning from Claude Code sessions\n- Configuring instinct-based behavior extraction via hooks\n- Tuning confidence thresholds for learned behaviors\n- Reviewing, exporting, or importing instinct libraries\n- Evolving instincts into full skills, commands, or agents\n- Managing project-scoped vs global instincts\n- Promoting instincts from project to global scope\n\n## What's New in v2.1\n\n| Feature | v2.0 | v2.1 |\n|---------|------|------|\n| Storage | Global (`~/.claude/homunculus/`) | Project-scoped (`${XDG_DATA_HOME:-~/.local/share}/ecc-homunculus/projects/<hash>/`) |\n| Scope | All instincts apply everywhere | Project-scoped + global |\n| Detection | None | git remote URL / repo path |\n| Promotion | N/A | Project → global when seen in 2+ projects |\n| Commands | 4 (status/evolve/export/import) | 6 (+promote/projects) |\n| Cross-project | Contamination risk | Isolated by default |\n\n## What's New in v2 (vs v1)\n\n| Feature | v1 | v2 |\n|---------|----|----|\n| Observation | Stop hook (session end) | PreToolUse/PostToolUse (100% reliable) |\n| Analysis | Main context | Background agent (Haiku) |\n| Granularity | Full skills | Atomic \"instincts\" |\n| Confidence | None | 0.3-0.9 weighted |\n| Evolution | Direct to skill | Instincts -> cluster -> skill/command/agent |\n| Sharing | None | Export/import instincts |\n\n## The Instinct Model\n\nAn instinct is a small learned behavior:\n\n```yaml\n---\nid: prefer-functional-style\ntrigger: \"when writing new functions\"\nconfidence: 0.7\ndomain: \"code-style\"\nsource: \"session-observation\"\nscope: project\nproject_id: \"a1b2c3d4e5f6\"\nproject_name: \"my-react-app\"\n---\n\n# Prefer Functional Style\n\n## Action\nUse functional patterns over classes when appropriate.\n\n## Evidence\n- Observed 5 instances of functional pattern preference\n- User corrected class-based approach to functional on 2025-01-15\n```\n\n**Properties:**\n- **Atomic** -- one trigger, one action\n- **Confidence-weighted** -- 0.3 = tentative, 0.9 = near certain\n- **Domain-tagged** -- code-style, testing, git, debugging, workflow, etc.\n- **Evidence-backed** -- tracks what observations created it\n- **Scope-aware** -- `project` (default) or `global`\n\n## How It Works\n\n```\nSession Activity (in a git repo)\n      |\n      | Hooks capture prompts + tool use (100% reliable)\n      | + detect project context (git remote / repo path)\n      v\n+---------------------------------------------+\n|  projects/<project-hash>/observations.jsonl  |\n|   (prompts, tool calls, outcomes, project)   |\n+---------------------------------------------+\n      |\n      | Observer agent reads (background, Haiku)\n      v\n+---------------------------------------------+\n|          PATTERN DETECTION                   |\n|   * User corrections -> instinct             |\n|   * Error resolutions -> instinct            |\n|   * Repeated workflows -> instinct           |\n|   * Scope decision: project or global?       |\n+---------------------------------------------+\n      |\n      | Creates/updates\n      v\n+---------------------------------------------+\n|  projects/<project-hash>/instincts/personal/ |\n|   * prefer-functional.yaml (0.7) [project]   |\n|   * use-react-hooks.yaml (0.9) [project]     |\n+---------------------------------------------+\n|  instincts/personal/  (GLOBAL)               |\n|   * always-validate-input.yaml (0.85) [global]|\n|   * grep-before-edit.yaml (0.6) [global]     |\n+---------------------------------------------+\n      |\n      | /evolve clusters + /promote\n      v\n+---------------------------------------------+\n|  projects/<hash>/evolved/ (project-scoped)   |\n|  evolved/ (global)                           |\n|   * commands/new-feature.md                  |\n|   * skills/testing-workflow.md               |\n|   * agents/refactor-specialist.md            |\n+---------------------------------------------+\n```\n\n## Project Detection\n\nThe system automatically detects your current project:\n\n1. **`CLAUDE_PROJECT_DIR` env var** (highest priority) -- honored as an explicit override even when the directory is not a git repo (hashed by its absolute path)\n2. **`git remote get-url origin`** -- hashed to create a portable project ID (same repo on different machines gets the same ID)\n3. **`git rev-parse --show-toplevel`** -- fallback using repo path (machine-specific)\n4. **Global fallback** -- if no project is detected, instincts go to global scope\n\nEach project gets a 12-character hash ID (e.g., `a1b2c3d4e5f6`). A registry file at `${XDG_DATA_HOME:-~/.local/share}/ecc-homunculus/projects.json` maps IDs to human-readable names.\n\n### Data Directory\n\nContinuous-learning-v2 stores observer data outside `~/.claude` so Claude Code's sensitive-path guard does not block background instinct writes:\n\n1. `CLV2_HOMUNCULUS_DIR` when set to an absolute path\n2. `$XDG_DATA_HOME/ecc-homunculus`\n3. `$HOME/.local/share/ecc-homunculus`\n\nExisting users with data at `~/.claude/homunculus` can migrate once:\n\n```bash\nbash skills/continuous-learning-v2/scripts/migrate-homunculus.sh\n```\n\n## Quick Start\n\n### 1. Enable Observation Hooks\n\n**If installed as a plugin** (recommended):\n\nNo extra `settings.json` hook block is required. Claude Code v2.1+ auto-loads the plugin `hooks/hooks.json`, and `observe.sh` is already registered there.\n\nIf you previously copied `observe.sh` into `~/.claude/settings.json`, remove that duplicate `PreToolUse` / `PostToolUse` block. Duplicating the plugin hook causes double execution and `${CLAUDE_PLUGIN_ROOT}` resolution errors because that variable is only available inside plugin-managed `hooks/hooks.json` entries.\n\n**If installed manually** to `~/.claude/skills`, add this to your `~/.claude/settings.json`:\n\n```json\n{\n  \"hooks\": {\n    \"PreToolUse\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"~/.claude/skills/continuous-learning-v2/hooks/observe.sh\"\n      }]\n    }],\n    \"PostToolUse\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"~/.claude/skills/continuous-learning-v2/hooks/observe.sh\"\n      }]\n    }]\n  }\n}\n```\n\n### 2. Initialize Directory Structure\n\nThe system creates directories automatically on first use, but you can also create them manually:\n\n```bash\n# Global directories\nmkdir -p \"${XDG_DATA_HOME:-$HOME/.local/share}/ecc-homunculus\"/{instincts/{personal,inherited},evolved/{agents,skills,commands},projects}\n\n# Project directories are auto-created when the hook first runs in a git repo\n```\n\n### 3. Use the Instinct Commands\n\n```bash\n/instinct-status     # Show learned instincts (project + global)\n/evolve              # Cluster related instincts into skills/commands\n/instinct-export     # Export instincts to file\n/instinct-import     # Import instincts from others\n/promote             # Promote project instincts to global scope\n/projects            # List all known projects and their instinct counts\n```\n\n## Commands\n\n| Command | Description |\n|---------|-------------|\n| `/instinct-status` | Show all instincts (project-scoped + global) with confidence |\n| `/evolve` | Cluster related instincts into skills/commands, suggest promotions |\n| `/instinct-export` | Export instincts (filterable by scope/domain) |\n| `/instinct-import <file>` | Import instincts with scope control |\n| `/promote [id]` | Promote project instincts to global scope |\n| `/projects` | List all known projects and their instinct counts |\n\n## Configuration\n\nEdit `config.json` to control the background observer:\n\n```json\n{\n  \"version\": \"2.1\",\n  \"observer\": {\n    \"enabled\": false,\n    \"run_interval_minutes\": 5,\n    \"min_observations_to_analyze\": 20\n  }\n}\n```\n\n| Key | Default | Description |\n|-----|---------|-------------|\n| `observer.enabled` | `false` | Enable the background observer agent |\n| `observer.run_interval_minutes` | `5` | How often the observer analyzes observations |\n| `observer.min_observations_to_analyze` | `20` | Minimum observations before analysis runs |\n\nOther behavior (observation capture, instinct thresholds, project scoping, promotion criteria) is configured via code defaults in `instinct-cli.py` and `observe.sh`.\n\n## File Structure\n\n```\n${XDG_DATA_HOME:-~/.local/share}/ecc-homunculus/\n+-- identity.json           # Your profile, technical level\n+-- projects.json           # Registry: project hash -> name/path/remote\n+-- observations.jsonl      # Global observations (fallback)\n+-- instincts/\n|   +-- personal/           # Global auto-learned instincts\n|   +-- inherited/          # Global imported instincts\n+-- evolved/\n|   +-- agents/             # Global generated agents\n|   +-- skills/             # Global generated skills\n|   +-- commands/           # Global generated commands\n+-- projects/\n    +-- a1b2c3d4e5f6/       # Project hash (from git remote URL)\n    |   +-- project.json    # Per-project metadata mirror (id/name/root/remote)\n    |   +-- observations.jsonl\n    |   +-- observations.archive/\n    |   +-- instincts/\n    |   |   +-- personal/   # Project-specific auto-learned\n    |   |   +-- inherited/  # Project-specific imported\n    |   +-- evolved/\n    |       +-- skills/\n    |       +-- commands/\n    |       +-- agents/\n    +-- f6e5d4c3b2a1/       # Another project\n        +-- ...\n```\n\n## Scope Decision Guide\n\n| Pattern Type | Scope | Examples |\n|-------------|-------|---------|\n| Language/framework conventions | **project** | \"Use React hooks\", \"Follow Django REST patterns\" |\n| File structure preferences | **project** | \"Tests in `__tests__`/\", \"Components in src/components/\" |\n| Code style | **project** | \"Use functional style\", \"Prefer dataclasses\" |\n| Error handling strategies | **project** | \"Use Result type for errors\" |\n| Security practices | **global** | \"Validate user input\", \"Sanitize SQL\" |\n| General best practices | **global** | \"Write tests first\", \"Always handle errors\" |\n| Tool workflow preferences | **global** | \"Grep before Edit\", \"Read before Write\" |\n| Git practices | **global** | \"Conventional commits\", \"Small focused commits\" |\n\n## Instinct Promotion (Project -> Global)\n\nWhen the same instinct appears in multiple projects with high confidence, it's a candidate for promotion to global scope.\n\n**Auto-promotion criteria:**\n- Same instinct ID in 2+ projects\n- Average confidence >= 0.8\n\n**How to promote:**\n\n```bash\n# Promote a specific instinct\npython3 instinct-cli.py promote prefer-explicit-errors\n\n# Auto-promote all qualifying instincts\npython3 instinct-cli.py promote\n\n# Preview without changes\npython3 instinct-cli.py promote --dry-run\n```\n\nThe `/evolve` command also suggests promotion candidates.\n\n## Confidence Scoring\n\nConfidence evolves over time:\n\n| Score | Meaning | Behavior |\n|-------|---------|----------|\n| 0.3 | Tentative | Suggested but not enforced |\n| 0.5 | Moderate | Applied when relevant |\n| 0.7 | Strong | Auto-approved for application |\n| 0.9 | Near-certain | Core behavior |\n\n**Confidence increases** when:\n- Pattern is repeatedly observed\n- User doesn't correct the suggested behavior\n- Similar instincts from other sources agree\n\n**Confidence decreases** when:\n- User explicitly corrects the behavior\n- Pattern isn't observed for extended periods\n- Contradicting evidence appears\n\n## Why Hooks vs Skills for Observation?\n\n> \"v1 relied on skills to observe. Skills are probabilistic -- they fire ~50-80% of the time based on Claude's judgment.\"\n\nHooks fire **100% of the time**, deterministically. This means:\n- Every tool call is observed\n- No patterns are missed\n- Learning is comprehensive\n\n## Backward Compatibility\n\nv2.1 is fully compatible with v2.0 and v1:\n- Existing global instincts can be migrated from `~/.claude/homunculus/instincts/` with `scripts/migrate-homunculus.sh`\n- Existing `~/.claude/skills/learned/` skills from v1 still work\n- Stop hook still runs (but now also feeds into v2)\n- Gradual migration: run both in parallel\n\n## Privacy\n\n- Observations stay **local** on your machine\n- Project-scoped instincts are isolated per project\n- Only **instincts** (patterns) can be exported — not raw observations\n- No actual code or conversation content is shared\n- You control what gets exported and promoted\n\n## Related\n\n- [ECC-Tools GitHub App](https://github.com/apps/ecc-tools) - Generate instincts from repo history\n- Homunculus - Community project that inspired the v2 instinct-based architecture (atomic observations, confidence scoring, instinct evolution pipeline)\n- [The Longform Guide](https://x.com/affaanmustafa/status/2014040193557471352) - Continuous learning section\n\n---\n\n*Instinct-based learning: teaching Claude your patterns, one project at a time.*\n"}];
